{
  "name": "vscode-database-client-clone",
  "displayName": "Database Client Clone",
  "description": "Full-featured Database Client extension for VS Code inspired by cweijan.vscode-database-client2",
  "version": "0.1.0",
  "publisher": "custom-developer",
  "engines": {
    "vscode": "^1.85.0"
  },
  "categories": [
    "Other"
  ],
  "activationEvents": [
    "onView:database-client-explorer"
  ],
  "main": "./out/extension.js",
  "contributes": {
    "viewsContainers": {
      "activitybar": [
        {
          "id": "database-client",
          "title": "Database Client",
          "icon": "$(database)"
        }
      ]
    },
    "views": {
      "database-client": [
        {
          "id": "database-client-explorer",
          "name": "DATABASE EXPLORER"
        }
      ]
    },
    "commands": [
      {
        "command": "dbClient.addConnection",
        "title": "Add Connection",
        "icon": "$(add)"
      },
      {
        "command": "dbClient.refreshTree",
        "title": "Refresh",
        "icon": "$(refresh)"
      },
      {
        "command": "dbClient.deleteConnection",
        "title": "Delete Connection",
        "icon": "$(trash)"
      },
      {
        "command": "dbClient.openTable",
        "title": "Open Table"
      },
      {
        "command": "dbClient.newQuery",
        "title": "New Query Console",
        "icon": "$(terminal)"
      },
      {
        "command": "dbClient.runQuery",
        "title": "Run SQL Query"
      }
    ],
    "menus": {
      "view/title": [
        {
          "command": "dbClient.addConnection",
          "when": "view == database-client-explorer",
          "group": "navigation@1"
        },
        {
          "command": "dbClient.refreshTree",
          "when": "view == database-client-explorer",
          "group": "navigation@2"
        }
      ],
      "view/item/context": [
        {
          "command": "dbClient.deleteConnection",
          "when": "view == database-client-explorer && viewItem == connectionNode",
          "group": "inline"
        },
        {
          "command": "dbClient.newQuery",
          "when": "view == database-client-explorer && (viewItem == connectionNode || viewItem == databaseNode)",
          "group": "inline"
        },
        {
          "command": "dbClient.openTable",
          "when": "view == database-client-explorer && viewItem == tableNode",
          "group": "inline"
        }
      ],
      "editor/context": [
        {
          "command": "dbClient.runQuery",
          "when": "editorLangId == sql",
          "group": "1_modification"
        }
      ]
    },
    "keybindings": [
      {
        "command": "dbClient.runQuery",
        "key": "ctrl+enter",
        "mac": "cmd+enter",
        "when": "editorLangId == sql"
      }
    ]
  },
  "scripts": {
    "vscode:prepublish": "npm run build",
    "compile": "tsc -p ./",
    "watch": "tsc -w -p ./",
    "build": "node esbuild.js",
    "dev": "node esbuild.js --watch"
  },
  "devDependencies": {
    "@types/node": "^20.0.0",
    "@types/vscode": "^1.85.0",
    "esbuild": "^0.20.0",
    "typescript": "^5.3.0"
  },
  "dependencies": {
    "pg": "^8.11.3",
    "@types/pg": "^8.11.0"
  }
}

const esbuild = require('esbuild');

const isWatch = process.argv.includes('--watch');

async function main() {
  const ctx = await esbuild.context({
    entryPoints: ['src/extension.ts'],
    bundle: true,
    format: 'cjs',
    minify: false,
    sourcemap: true,
    sourcesContent: false,
    platform: 'node',
    outfile: 'out/extension.js',
    external: ['vscode', 'pg-native'],
    logLevel: 'info',
  });

  if (isWatch) {
    await ctx.watch();
    console.log('Watching for changes...');
  } else {
    await ctx.rebuild();
    await ctx.dispose();
  }
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

export type DatabaseType = 'PostgreSQL' | 'MySQL' | 'SQLite' | 'Redis' | 'MongoDB';

export interface ConnectionConfig {
  id: string;
  name: string;
  type: DatabaseType;
  host?: string;
  port?: number;
  user?: string;
  database?: string;
  schema?: string;
  dbPath?: string; // For SQLite
  ssl?: boolean;
  ssh?: {
    enabled: boolean;
    host?: string;
    port?: number;
    username?: string;
    privateKeyPath?: string;
  };
}

export interface SavedConnectionProfile extends Omit<ConnectionConfig, 'password'> {
  // Password is saved separately in SecretStorage using key `password_${id}`
}

export interface ColumnInfo {
  name: string;
  type: string;
  nullable: boolean;
  isPrimaryKey?: boolean;
  defaultValue?: string | null;
}

export interface TableInfo {
  name: string;
  schema?: string;
  type?: 'table' | 'view';
  comment?: string;
}

export interface QueryResult {
  rows: Record<string, any>[];
  fields: ColumnInfo[];
  affectedRows?: number;
  costTimeMs: number;
  totalCount?: number;
}

export interface PageParams {
  page: number;
  pageSize: number;
  sortField?: string;
  sortOrder?: 'ASC' | 'DESC';
  filterSql?: string;
}

import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { ColumnInfo, QueryResult, TableInfo, PageParams } from '../model/QueryTypes.js';

export abstract class BaseDriver {
  protected config: ConnectionConfig;
  protected password?: string;
  protected isConnected: boolean = false;

  constructor(config: ConnectionConfig, password?: string) {
    this.config = config;
    this.password = password;
  }

  abstract connect(): Promise<void>;
  abstract disconnect(): Promise<void>;
  abstract testConnection(): Promise<{ success: boolean; message?: string }>;

  abstract getDatabases(): Promise<string[]>;
  abstract getTables(databaseName?: string, schemaName?: string): Promise<TableInfo[]>;
  abstract getColumns(tableName: string, databaseName?: string, schemaName?: string): Promise<ColumnInfo[]>;

  abstract executeQuery(sql: string): Promise<QueryResult>;
  abstract getTableData(tableName: string, params: PageParams, schemaName?: string): Promise<QueryResult>;

  public getIsConnected(): boolean {
    return this.isConnected;
  }
}

import { Client } from 'pg';
import { BaseDriver } from './BaseDriver.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { ColumnInfo, PageParams, QueryResult, TableInfo } from '../model/QueryTypes.js';

export class PostgresDriver extends BaseDriver {
  private client: Client | null = null;

  constructor(config: ConnectionConfig, password?: string) {
    super(config, password);
  }

  private createClient(databaseName?: string): Client {
    return new Client({
      host: this.config.host || 'localhost',
      port: this.config.port || 5432,
      user: this.config.user || 'postgres',
      password: this.password || '',
      database: databaseName || this.config.database || 'postgres',
      ssl: this.config.ssl ? { rejectUnauthorized: false } : undefined,
      connectionTimeoutMillis: 5000,
    });
  }

  async connect(): Promise<void> {
    if (this.client) {
      await this.disconnect();
    }
    this.client = this.createClient();
    await this.client.connect();
    this.isConnected = true;
  }

  async disconnect(): Promise<void> {
    if (this.client) {
      try {
        await this.client.end();
      } catch (e) {
        // Ignore disconnect errors
      }
      this.client = null;
      this.isConnected = false;
    }
  }

  async testConnection(): Promise<{ success: boolean; message?: string }> {
    const tempClient = this.createClient();
    try {
      await tempClient.connect();
      await tempClient.query('SELECT 1');
      await tempClient.end();
      return { success: true, message: 'Successfully connected to PostgreSQL database!' };
    } catch (err: any) {
      return { success: false, message: err.message || 'Connection failed' };
    }
  }

  async getDatabases(): Promise<string[]> {
    const res = await this.executeQuery(
      "SELECT datname FROM pg_database WHERE datistemplate = false AND datname != 'postgres' ORDER BY datname ASC;"
    );
    return res.rows.map((r) => r.datname);
  }

  async getTables(databaseName?: string, schemaName: string = 'public'): Promise<TableInfo[]> {
    const sql = `
      SELECT table_name, table_type
      FROM information_schema.tables
      WHERE table_schema = '${schemaName}'
      ORDER BY table_name ASC;
    `;
    const res = await this.executeQuery(sql);
    return res.rows.map((r) => ({
      name: r.table_name,
      schema: schemaName,
      type: r.table_type === 'VIEW' ? 'view' : 'table',
    }));
  }

  async getColumns(tableName: string, databaseName?: string, schemaName: string = 'public'): Promise<ColumnInfo[]> {
    const sql = `
      SELECT 
        c.column_name, 
        c.data_type, 
        c.is_nullable, 
        c.column_default,
        tc.constraint_type
      FROM information_schema.columns c
      LEFT JOIN information_schema.key_column_usage kcu
        ON c.table_schema = kcu.table_schema 
        AND c.table_name = kcu.table_name 
        AND c.column_name = kcu.column_name
      LEFT JOIN information_schema.table_constraints tc
        ON kcu.table_schema = tc.table_schema 
        AND kcu.table_name = tc.table_name 
        AND kcu.constraint_name = tc.constraint_name 
        AND tc.constraint_type = 'PRIMARY KEY'
      WHERE c.table_schema = '${schemaName}' AND c.table_name = '${tableName}'
      ORDER BY c.ordinal_position ASC;
    `;
    const res = await this.executeQuery(sql);
    return res.rows.map((r) => ({
      name: r.column_name,
      type: r.data_type,
      nullable: r.is_nullable === 'YES',
      isPrimaryKey: r.constraint_type === 'PRIMARY KEY',
      defaultValue: r.column_default,
    }));
  }

  async executeQuery(sql: string): Promise<QueryResult> {
    if (!this.client) {
      await this.connect();
    }
    const startTime = Date.now();
    const res = await this.client!.query(sql);
    const costTimeMs = Date.now() - startTime;

    const fields: ColumnInfo[] = (res.fields || []).map((f) => ({
      name: f.name,
      type: 'unknown',
      nullable: true,
    }));

    return {
      rows: res.rows || [],
      fields,
      affectedRows: res.rowCount || 0,
      costTimeMs,
    };
  }

  async getTableData(tableName: string, params: PageParams, schemaName: string = 'public'): Promise<QueryResult> {
    const offset = (params.page - 1) * params.pageSize;
    let sql = `SELECT * FROM "${schemaName}"."${tableName}"`;

    if (params.filterSql) {
      sql += ` WHERE ${params.filterSql}`;
    }

    if (params.sortField && params.sortOrder) {
      sql += ` ORDER BY "${params.sortField}" ${params.sortOrder}`;
    }

    sql += ` LIMIT ${params.pageSize} OFFSET ${offset};`;

    const countSql = `SELECT COUNT(*) as total FROM "${schemaName}"."${tableName}"`;
    const countRes = await this.executeQuery(countSql);
    const totalCount = parseInt(countRes.rows[0]?.total || '0', 10);

    const queryResult = await this.executeQuery(sql);
    queryResult.totalCount = totalCount;
    return queryResult;
  }
}

import { BaseDriver } from './BaseDriver.js';
import { PostgresDriver } from './PostgresDriver.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';

export class DriverManager {
  private static instance: DriverManager;
  private activeDrivers: Map<string, BaseDriver> = new Map();

  private constructor() {}

  public static getInstance(): DriverManager {
    if (!DriverManager.instance) {
      DriverManager.instance = new DriverManager();
    }
    return DriverManager.instance;
  }

  public getDriver(config: ConnectionConfig, password?: string): BaseDriver {
    let driver = this.activeDrivers.get(config.id);
    if (!driver) {
      switch (config.type) {
        case 'PostgreSQL':
          driver = new PostgresDriver(config, password);
          break;
        default:
          throw new Error(`Unsupported database type: ${config.type}`);
      }
      this.activeDrivers.set(config.id, driver);
    }
    return driver;
  }

  public async disconnectAll(): Promise<void> {
    for (const [id, driver] of this.activeDrivers.entries()) {
      await driver.disconnect();
    }
    this.activeDrivers.clear();
  }

  public async removeDriver(id: string): Promise<void> {
    const driver = this.activeDrivers.get(id);
    if (driver) {
      await driver.disconnect();
      this.activeDrivers.delete(id);
    }
  }
}

import * as vscode from 'vscode';
import { ConnectionConfig, SavedConnectionProfile } from '../model/ConnectionConfig.js';

export class ConnectionStorageService {
  private static readonly STORAGE_KEY = 'database_client_connections';
  private context: vscode.ExtensionContext;

  constructor(context: vscode.ExtensionContext) {
    this.context = context;
  }

  public getConnections(): SavedConnectionProfile[] {
    return this.context.globalState.get<SavedConnectionProfile[]>(ConnectionStorageService.STORAGE_KEY, []);
  }

  public async saveConnection(config: ConnectionConfig, password?: string): Promise<SavedConnectionProfile> {
    const connections = this.getConnections();
    const existingIndex = connections.findIndex((c) => c.id === config.id);

    const profile: SavedConnectionProfile = {
      id: config.id || `conn_${Date.now()}`,
      name: config.name,
      type: config.type,
      host: config.host,
      port: config.port,
      user: config.user,
      database: config.database,
      schema: config.schema,
      dbPath: config.dbPath,
      ssl: config.ssl,
      ssh: config.ssh,
    };

    if (password !== undefined) {
      await this.context.secrets.store(`password_${profile.id}`, password);
    }

    if (existingIndex >= 0) {
      connections[existingIndex] = profile;
    } else {
      connections.push(profile);
    }

    await this.context.globalState.update(ConnectionStorageService.STORAGE_KEY, connections);
    return profile;
  }

  public async getPassword(id: string): Promise<string | undefined> {
    return await this.context.secrets.get(`password_${id}`);
  }

  public async deleteConnection(id: string): Promise<void> {
    const connections = this.getConnections().filter((c) => c.id !== id);
    await this.context.globalState.update(ConnectionStorageService.STORAGE_KEY, connections);
    await this.context.secrets.delete(`password_${id}`);
  }
}

import * as vscode from 'vscode';

export abstract class BaseNode {
  public id: string;
  public label: string;
  public contextValue: string;
  public collapsibleState: vscode.TreeItemCollapsibleState;
  public parent?: BaseNode;

  constructor(id: string, label: string, contextValue: string, collapsibleState: vscode.TreeItemCollapsibleState = vscode.TreeItemCollapsibleState.None, parent?: BaseNode) {
    this.id = id;
    this.label = label;
    this.contextValue = contextValue;
    this.collapsibleState = collapsibleState;
    this.parent = parent;
  }

  abstract getTreeItem(): vscode.TreeItem | Promise<vscode.TreeItem>;
  abstract getChildren(): Promise<BaseNode[]>;
}

import * as vscode from 'vscode';
import { BaseNode } from './BaseNode.js';
import { ColumnInfo } from '../model/QueryTypes.js';

export class ColumnNode extends BaseNode {
  public column: ColumnInfo;

  constructor(column: ColumnInfo, parent?: BaseNode) {
    super(`col_${column.name}`, column.name, 'columnNode', vscode.TreeItemCollapsibleState.None, parent);
    this.column = column;
  }

  getTreeItem(): vscode.TreeItem {
    const item = new vscode.TreeItem(this.label, vscode.TreeItemCollapsibleState.None);
    item.description = `${this.column.type}${this.column.isPrimaryKey ? ' (PK)' : ''}`;
    item.iconPath = new vscode.ThemeIcon(this.column.isPrimaryKey ? 'key' : 'symbol-field');
    item.contextValue = 'columnNode';
    return item;
  }

  async getChildren(): Promise<BaseNode[]> {
    return [];
  }
}

import * as vscode from 'vscode';
