import { PageParams } from '../model/QueryTypes.js';

export class TableWebviewProvider {
  public static openTable(tableNode: TableNode) {
    const panel = vscode.window.createWebviewPanel(
      'dbClientDataGrid',
      `Data: ${tableNode.table.name}`,
      vscode.ViewColumn.One,
      {
        enableScripts: true,
        retainContextWhenHidden: true,
      }
    );

    const connectionConfig = tableNode.connectionConfig;
    const tableName = tableNode.table.name;
    const schemaName = tableNode.table.schema || 'public';

    let currentParams: PageParams = {
      page: 1,
      pageSize: 50,
    };

    const loadData = async () => {
      try {
        const driver = DriverManager.getInstance().getDriver(connectionConfig);
        const result = await driver.getTableData(tableName, currentParams, schemaName);
        panel.webview.postMessage({
          type: 'renderData',
          tableName,
          result,
          params: currentParams,
        });
      } catch (err: any) {
        panel.webview.postMessage({
          type: 'error',
          message: err.message,
        });
      }
    };

    panel.webview.onDidReceiveMessage(async (msg) => {
      switch (msg.type) {
        case 'fetchData':
          if (msg.params) {
            currentParams = { ...currentParams, ...msg.params };
          }
          await loadData();
          break;
        case 'executeSql':
          try {
            const driver = DriverManager.getInstance().getDriver(connectionConfig);
            const res = await driver.executeQuery(msg.sql);
            panel.webview.postMessage({ type: 'queryResult', result: res });
          } catch (err: any) {
            panel.webview.postMessage({ type: 'error', message: err.message });
          }
          break;
      }
    });

    panel.webview.html = TableWebviewProvider.getHtml(tableName);
    loadData();
  }

  public static openQueryConsole(connectionConfig: ConnectionConfig, password?: string) {
    const panel = vscode.window.createWebviewPanel(
      'dbClientQueryConsole',
      `Console: ${connectionConfig.name}`,
      vscode.ViewColumn.One,
      {
        enableScripts: true,
        retainContextWhenHidden: true,
      }
    );

    panel.webview.onDidReceiveMessage(async (msg) => {
      if (msg.type === 'executeSql') {
        try {
          const driver = DriverManager.getInstance().getDriver(connectionConfig, password);
          const res = await driver.executeQuery(msg.sql);
          panel.webview.postMessage({ type: 'queryResult', result: res });
        } catch (err: any) {
          panel.webview.postMessage({ type: 'error', message: err.message });
        }
      }
    });

    panel.webview.html = TableWebviewProvider.getConsoleHtml(connectionConfig.name);
  }

