import * as net from 'net';
import { Client } from 'ssh2';
import { ConnectionConfig } from '../model/ConnectionConfig.js';

export interface SshTunnelResult {
  localPort: number;
  close: () => void;
}

export class SshTunnelManager {
  public static async createTunnel(
    config: ConnectionConfig,
    sshPassword?: string
  ): Promise<SshTunnelResult> {
    if (!config.ssh || !config.ssh.enabled) {
      throw new Error('SSH is not enabled in configuration');
    }

    const sshClient = new Client();

    return new Promise((resolve, reject) => {
      const server = net.createServer((socket) => {
        sshClient.forwardOut(
          '127.0.0.1',
          socket.remotePort || 0,
          config.host || '127.0.0.1',
          config.port || 3306,
          (err, stream) => {
            if (err) {
              socket.end();
              return;
            }
            socket.pipe(stream).pipe(socket);
          }
        );
      });

      server.listen(0, '127.0.0.1', () => {
        const address = server.address() as net.AddressInfo;
        const localPort = address.port;

        sshClient
          .on('ready', () => {
            resolve({
              localPort,
              close: () => {
                server.close();
                sshClient.end();
              },
            });
          })
          .on('error', (err) => {
            server.close();
            reject(new Error(`SSH Tunnel Error: ${err.message}`));
          })
          .connect({
            host: config.ssh?.host || '',
            port: config.ssh?.port || 22,
            username: config.ssh?.username || '',
            password: sshPassword,
          });
      });
    });
  }
}

import mysql from 'mysql2/promise';
import { BaseDriver } from './BaseDriver.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { ColumnInfo, PageParams, QueryResult, TableInfo } from '../model/QueryTypes.js';

export class MysqlDriver extends BaseDriver {
  private connection: mysql.Connection | null = null;

  constructor(config: ConnectionConfig, password?: string) {
    super(config, password);
  }

  private async getClient(databaseName?: string): Promise<mysql.Connection> {
    return await mysql.createConnection({
      host: this.config.host || 'localhost',
      port: this.config.port || 3306,
      user: this.config.user || 'root',
      password: this.password || '',
      database: databaseName || this.config.database,
      ssl: this.config.ssl ? { rejectUnauthorized: false } : undefined,
      connectTimeout: 5000,
    });
  }

  async connect(): Promise<void> {
    if (this.connection) {
      await this.disconnect();
    }
    this.connection = await this.getClient();
    this.isConnected = true;
  }

  async disconnect(): Promise<void> {
    if (this.connection) {
      try {
        await this.connection.end();
      } catch (e) {}
      this.connection = null;
      this.isConnected = false;
    }
  }

  async testConnection(): Promise<{ success: boolean; message?: string }> {
    try {
      const conn = await this.getClient();
      await conn.query('SELECT 1');
      await conn.end();
      return { success: true, message: 'Successfully connected to MySQL database!' };
    } catch (err: any) {
      return { success: false, message: err.message || 'Connection failed' };
    }
  }

  async getDatabases(): Promise<string[]> {
    const res = await this.executeQuery('SHOW DATABASES;');
    return res.rows.map((r) => Object.values(r)[0] as string);
  }

  async getTables(databaseName?: string): Promise<TableInfo[]> {
    const db = databaseName || this.config.database;
    const sql = db ? `SHOW FULL TABLES FROM \`${db}\`;` : 'SHOW FULL TABLES;';
    const res = await this.executeQuery(sql);
    return res.rows.map((r) => {
      const vals = Object.values(r);
      return {
        name: vals[0] as string,
        type: vals[1] === 'VIEW' ? 'view' : 'table',
      };
    });
  }

  async getColumns(tableName: string, databaseName?: string): Promise<ColumnInfo[]> {
    const db = databaseName || this.config.database;
    const sql = `
      SELECT COLUMN_NAME, DATA_TYPE, IS_NULLABLE, COLUMN_KEY, COLUMN_DEFAULT
      FROM INFORMATION_SCHEMA.COLUMNS
      WHERE TABLE_SCHEMA = '${db}' AND TABLE_NAME = '${tableName}'
      ORDER BY ORDINAL_POSITION ASC;
    `;
    const res = await this.executeQuery(sql);
    return res.rows.map((r) => ({
      name: r.COLUMN_NAME,
      type: r.DATA_TYPE,
      nullable: r.IS_NULLABLE === 'YES',
      isPrimaryKey: r.COLUMN_KEY === 'PRI',
      defaultValue: r.COLUMN_DEFAULT,
    }));
  }

  async executeQuery(sql: string): Promise<QueryResult> {
    if (!this.connection) {
      await this.connect();
    }
    const startTime = Date.now();
    const [rows, fields] = await this.connection!.query(sql);
    const costTimeMs = Date.now() - startTime;

    const columnInfos: ColumnInfo[] = Array.isArray(fields)
      ? fields.map((f: any) => ({
          name: f.name,
          type: 'unknown',
          nullable: true,
        }))
      : [];

    return {
      rows: Array.isArray(rows) ? (rows as Record<string, any>[]) : [],
      fields: columnInfos,
      affectedRows: (rows as any)?.affectedRows || (Array.isArray(rows) ? rows.length : 0),
      costTimeMs,
    };
  }

  async getTableData(tableName: string, params: PageParams): Promise<QueryResult> {
    const offset = (params.page - 1) * params.pageSize;
    let sql = `SELECT * FROM \`${tableName}\``;

    if (params.filterSql) {
      sql += ` WHERE ${params.filterSql}`;
    }

    if (params.sortField && params.sortOrder) {
      sql += ` ORDER BY \`${params.sortField}\` ${params.sortOrder}`;
    }

    sql += ` LIMIT ${params.pageSize} OFFSET ${offset};`;

    const countSql = `SELECT COUNT(*) as total FROM \`${tableName}\`;`;
    const countRes = await this.executeQuery(countSql);
    const totalCount = parseInt(Object.values(countRes.rows[0] || {})[0] as string || '0', 10);

    const queryResult = await this.executeQuery(sql);
    queryResult.totalCount = totalCount;
    return queryResult;
  }
}

import sqlite3 from 'sqlite3';
import { BaseDriver } from './BaseDriver.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { ColumnInfo, PageParams, QueryResult, TableInfo } from '../model/QueryTypes.js';

export class SqliteDriver extends BaseDriver {
  private db: sqlite3.Database | null = null;

  constructor(config: ConnectionConfig, password?: string) {
    super(config, password);
  }

  async connect(): Promise<void> {
    if (this.db) {
      await this.disconnect();
    }
    const dbPath = this.config.dbPath || this.config.database || ':memory:';
    return new Promise((resolve, reject) => {
      this.db = new sqlite3.Database(dbPath, (err) => {
        if (err) {
          reject(err);
        } else {
          this.isConnected = true;
          resolve();
        }
      });
    });
  }

  async disconnect(): Promise<void> {
    if (this.db) {
      return new Promise((resolve) => {
        this.db?.close(() => {
          this.db = null;
          this.isConnected = false;
          resolve();
        });
      });
    }
  }

  async testConnection(): Promise<{ success: boolean; message?: string }> {
    try {
      await this.connect();
      await this.executeQuery('SELECT 1');
      await this.disconnect();
      return { success: true, message: 'Successfully connected to SQLite database!' };
    } catch (err: any) {
      return { success: false, message: err.message || 'Connection failed' };
    }
  }

  async getDatabases(): Promise<string[]> {
    return ['main'];
  }

  async getTables(): Promise<TableInfo[]> {
    const res = await this.executeQuery(
      "SELECT name, type FROM sqlite_master WHERE type IN ('table', 'view') AND name NOT LIKE 'sqlite_%' ORDER BY name ASC;"
    );
    return res.rows.map((r) => ({
      name: r.name,
      type: r.type === 'view' ? 'view' : 'table',
    }));
  }

  async getColumns(tableName: string): Promise<ColumnInfo[]> {
    const res = await this.executeQuery(`PRAGMA table_info("${tableName}");`);
    return res.rows.map((r) => ({
      name: r.name,
      type: r.type,
      nullable: r.notnull === 0,
      isPrimaryKey: r.pk === 1,
      defaultValue: r.dflt_value,
    }));
  }

  async executeQuery(sql: string): Promise<QueryResult> {
    if (!this.db) {
      await this.connect();
    }
    const startTime = Date.now();
    return new Promise((resolve, reject) => {
      this.db!.all(sql, [], (err, rows: any[]) => {
        if (err) {
          return reject(err);
        }
        const costTimeMs = Date.now() - startTime;
        const fields: ColumnInfo[] =
          rows && rows.length > 0
            ? Object.keys(rows[0]).map((k) => ({ name: k, type: 'unknown', nullable: true }))
            : [];

        resolve({
          rows: rows || [],
          fields,
          affectedRows: rows ? rows.length : 0,
          costTimeMs,
        });
      });
    });
  }

  async getTableData(tableName: string, params: PageParams): Promise<QueryResult> {
    const offset = (params.page - 1) * params.pageSize;
    let sql = `SELECT * FROM "${tableName}"`;

    if (params.filterSql) {
      sql += ` WHERE ${params.filterSql}`;
    }

    if (params.sortField && params.sortOrder) {
      sql += ` ORDER BY "${params.sortField}" ${params.sortOrder}`;
    }

    sql += ` LIMIT ${params.pageSize} OFFSET ${offset};`;

    const countRes = await this.executeQuery(`SELECT COUNT(*) as total FROM "${tableName}";`);
    const totalCount = parseInt(countRes.rows[0]?.total || '0', 10);

    const queryResult = await this.executeQuery(sql);
    queryResult.totalCount = totalCount;
    return queryResult;
  }
}

import Redis from 'ioredis';
import { BaseDriver } from './BaseDriver.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { ColumnInfo, PageParams, QueryResult, TableInfo } from '../model/QueryTypes.js';

export class RedisDriver extends BaseDriver {
  private client: Redis | null = null;

  constructor(config: ConnectionConfig, password?: string) {
    super(config, password);
  }

  async connect(): Promise<void> {
    if (this.client) {
      await this.disconnect();
    }
    this.client = new Redis({
      host: this.config.host || '127.0.0.1',
      port: this.config.port || 6379,
      password: this.password || undefined,
      db: parseInt(this.config.database || '0', 10),
      connectTimeout: 5000,
      lazyConnect: true,
    });
    await this.client.connect();
    this.isConnected = true;
  }

  async disconnect(): Promise<void> {
    if (this.client) {
      try {
        await this.client.quit();
      } catch (e) {}
      this.client = null;
      this.isConnected = false;
    }
  }

  async testConnection(): Promise<{ success: boolean; message?: string }> {
    try {
      await this.connect();
      await this.client?.ping();
      await this.disconnect();
      return { success: true, message: 'Successfully connected to Redis instance!' };
    } catch (err: any) {
      return { success: false, message: err.message || 'Connection failed' };
    }
  }

  async getDatabases(): Promise<string[]> {
    return Array.from({ length: 16 }, (_, i) => `db${i}`);
  }

  async getTables(): Promise<TableInfo[]> {
    if (!this.client) {
      await this.connect();
    }
    const keys = await this.client!.keys('*');
    return keys.slice(0, 100).map((k) => ({
      name: k,
      type: 'table',
    }));
  }

  async getColumns(keyName: string): Promise<ColumnInfo[]> {
    return [
      { name: 'key', type: 'string', nullable: false, isPrimaryKey: true },
      { name: 'type', type: 'string', nullable: false },
      { name: 'value', type: 'string', nullable: true },
      { name: 'ttl', type: 'number', nullable: true },
    ];
  }

  async executeQuery(commandString: string): Promise<QueryResult> {
    if (!this.client) {
      await this.connect();
    }
    const startTime = Date.now();
    const parts = commandString.trim().split(/\s+/);
    const cmd = parts[0].toLowerCase();
    const args = parts.slice(1);

    const rawResult = await (this.client as any)[cmd](...args);
    const costTimeMs = Date.now() - startTime;

    const rows = Array.isArray(rawResult)
      ? rawResult.map((v, i) => ({ index: i, value: typeof v === 'object' ? JSON.stringify(v) : v }))
      : [{ result: typeof rawResult === 'object' ? JSON.stringify(rawResult) : rawResult }];

    const fields: ColumnInfo[] = rows.length > 0 ? Object.keys(rows[0]).map((k) => ({ name: k, type: 'string', nullable: true })) : [];

    return {
      rows,
      fields,
      costTimeMs,
    };
  }

  async getTableData(keyName: string, params: PageParams): Promise<QueryResult> {
    if (!this.client) {
      await this.connect();
    }
    const startTime = Date.now();
    const type = await this.client!.type(keyName);
    const ttl = await this.client!.ttl(keyName);
    let val: any = '';

    if (type === 'string') {
      val = await this.client!.get(keyName);
    } else if (type === 'hash') {
      val = JSON.stringify(await this.client!.hgetall(keyName));
    } else if (type === 'list') {
      val = JSON.stringify(await this.client!.lrange(keyName, 0, 50));
    } else if (type === 'set') {
      val = JSON.stringify(await this.client!.smembers(keyName));
    }

    return {
      rows: [{ key: keyName, type, value: val, ttl }],
      fields: [
        { name: 'key', type: 'string', nullable: false, isPrimaryKey: true },
        { name: 'type', type: 'string', nullable: false },
        { name: 'value', type: 'string', nullable: true },
        { name: 'ttl', type: 'number', nullable: true },
      ],
      totalCount: 1,
      costTimeMs: Date.now() - startTime,
    };
  }
}

import { MongoClient } from 'mongodb';
import { BaseDriver } from './BaseDriver.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { ColumnInfo, PageParams, QueryResult, TableInfo } from '../model/QueryTypes.js';

export class MongoDriver extends BaseDriver {
  private client: MongoClient | null = null;

  constructor(config: ConnectionConfig, password?: string) {
    super(config, password);
  }

  async connect(): Promise<void> {
    if (this.client) {
      await this.disconnect();
    }
    const host = this.config.host || 'localhost';
    const port = this.config.port || 27017;
    const auth = this.config.user && this.password ? `${this.config.user}:${encodeURIComponent(this.password)}@` : '';
    const uri = `mongodb://${auth}${host}:${port}`;

    this.client = new MongoClient(uri, { connectTimeoutMS: 5000 });
    await this.client.connect();
    this.isConnected = true;
  }

  async disconnect(): Promise<void> {
    if (this.client) {
      try {
        await this.client.close();
      } catch (e) {}
      this.client = null;
      this.isConnected = false;
    }
  }

  async testConnection(): Promise<{ success: boolean; message?: string }> {
    try {
      await this.connect();
      await this.client?.db().admin().ping();
      await this.disconnect();
      return { success: true, message: 'Successfully connected to MongoDB server!' };
    } catch (err: any) {
      return { success: false, message: err.message || 'Connection failed' };
    }
  }

  async getDatabases(): Promise<string[]> {
    if (!this.client) {
      await this.connect();
    }
    const res = await this.client!.db().admin().listDatabases();
    return res.databases.map((d) => d.name);
  }

  async getTables(databaseName?: string): Promise<TableInfo[]> {
    if (!this.client) {
      await this.connect();
    }
    const db = this.client!.db(databaseName || this.config.database || 'test');
    const collections = await db.listCollections().toArray();
    return collections.map((c) => ({
      name: c.name,
      type: 'table',
    }));
  }

  async getColumns(collectionName: string, databaseName?: string): Promise<ColumnInfo[]> {
    if (!this.client) {
      await this.connect();
    }
    const db = this.client!.db(databaseName || this.config.database || 'test');
    const sampleDoc = await db.collection(collectionName).findOne();
    if (!sampleDoc) {
      return [{ name: '_id', type: 'ObjectId', nullable: false, isPrimaryKey: true }];
    }
    return Object.keys(sampleDoc).map((key) => ({
      name: key,
      type: typeof sampleDoc[key],
      nullable: true,
      isPrimaryKey: key === '_id',
    }));
  }

  async executeQuery(queryJson: string): Promise<QueryResult> {
    if (!this.client) {
      await this.connect();
    }
    const startTime = Date.now();
    const db = this.client!.db(this.config.database || 'test');
    const filter = queryJson.trim() ? JSON.parse(queryJson) : {};

    const docs = await db.collection('sample').find(filter).limit(100).toArray();
    const costTimeMs = Date.now() - startTime;

    const fields: ColumnInfo[] = docs.length > 0 ? Object.keys(docs[0]).map((k) => ({ name: k, type: 'unknown', nullable: true })) : [];

    return {
      rows: docs,
      fields,
      costTimeMs,
    };
  }

  async getTableData(collectionName: string, params: PageParams): Promise<QueryResult> {
    if (!this.client) {
      await this.connect();
    }
    const startTime = Date.now();
    const db = this.client!.db(this.config.database || 'test');
    const collection = db.collection(collectionName);

    const totalCount = await collection.countDocuments();
    const offset = (params.page - 1) * params.pageSize;

    const docs = await collection.find({}).skip(offset).limit(params.pageSize).toArray();
    const costTimeMs = Date.now() - startTime;

    const fields: ColumnInfo[] = docs.length > 0 ? Object.keys(docs[0]).map((k) => ({ name: k, type: typeof docs[0][k], nullable: true })) : [];

    return {
      rows: docs,
      fields,
      totalCount,
      costTimeMs,
    };
  }
}

import { BaseDriver } from './BaseDriver.js';
import { PostgresDriver } from './PostgresDriver.js';
import { MysqlDriver } from './MysqlDriver.js';
import { SqliteDriver } from './SqliteDriver.js';
import { RedisDriver } from './RedisDriver.js';
import { MongoDriver } from './MongoDriver.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { SshTunnelManager, SshTunnelResult } from '../ssh/SshTunnelManager.js';

export class DriverManager {
  private static instance: DriverManager;
  private activeDrivers: Map<string, BaseDriver> = new Map();
  private sshTunnels: Map<string, SshTunnelResult> = new Map();

  private constructor() {}

  public static getInstance(): DriverManager {
    if (!DriverManager.instance) {
      DriverManager.instance = new DriverManager();
    }
    return DriverManager.instance;
  }

  public async getDriver(config: ConnectionConfig, password?: string, sshPassword?: string): Promise<BaseDriver> {
    let driver = this.activeDrivers.get(config.id);
    if (!driver) {
      let finalConfig = { ...config };

      if (config.ssh && config.ssh.enabled) {
        const tunnel = await SshTunnelManager.createTunnel(config, sshPassword);
        this.sshTunnels.set(config.id, tunnel);
        finalConfig.host = '127.0.0.1';
        finalConfig.port = tunnel.localPort;
      }

      switch (config.type) {
        case 'PostgreSQL':
          driver = new PostgresDriver(finalConfig, password);
          break;
        case 'MySQL':
          driver = new MysqlDriver(finalConfig, password);
          break;
        case 'SQLite':
          driver = new SqliteDriver(finalConfig, password);
          break;
        case 'Redis':
          driver = new RedisDriver(finalConfig, password);
          break;
        case 'MongoDB':
          driver = new MongoDriver(finalConfig, password);
          break;
        default:
          throw new Error(`Unsupported database type: ${config.type}`);
      }
      this.activeDrivers.set(config.id, driver);
    }
    return driver;
  }

  public async disconnectAll(): Promise<void> {
    for (const [id, driver] of this.activeDrivers.entries()) {
      await driver.disconnect();
    }
    this.activeDrivers.clear();

    for (const [id, tunnel] of this.sshTunnels.entries()) {
      tunnel.close();
    }
    this.sshTunnels.clear();
  }

  public async removeDriver(id: string): Promise<void> {
    const driver = this.activeDrivers.get(id);
    if (driver) {
      await driver.disconnect();
      this.activeDrivers.delete(id);
    }
    const tunnel = this.sshTunnels.get(id);
    if (tunnel) {
      tunnel.close();
      this.sshTunnels.delete(id);
    }
  }
}

import * as vscode from 'vscode';
import * as fs from 'fs';
import { QueryResult } from '../model/QueryTypes.js';

export class ExportService {
  public static async exportData(tableName: string, result: QueryResult, format: 'csv' | 'json' | 'sql') {
    const uri = await vscode.window.showSaveDialog({
      defaultUri: vscode.Uri.file(`${tableName}_export.${format}`),
      filters: {
        [format.toUpperCase()]: [format],
      },
    });

    if (!uri) {
      return;
    }

    let content = '';

    if (format === 'json') {
      content = JSON.stringify(result.rows, null, 2);
    } else if (format === 'csv') {
      const headers = result.fields.map((f) => `"${f.name}"`).join(',');
      const rows = result.rows.map((r) =>
        result.fields
          .map((f) => {
            const val = r[f.name];
            if (val === null || val === undefined) return '""';
            return `"${String(val).replace(/"/g, '""')}"`;
          })
          .join(',')
      );
      content = [headers, ...rows].join('\n');
    } else if (format === 'sql') {
      const fieldNames = result.fields.map((f) => `"${f.name}"`).join(', ');
      const insertRows = result.rows.map((r) => {
        const values = result.fields
          .map((f) => {
            const val = r[f.name];
            if (val === null || val === undefined) return 'NULL';
            if (typeof val === 'number') return val;
            return `'${String(val).replace(/'/g, "''")}'`;
          })
          .join(', ');
        return `INSERT INTO "${tableName}" (${fieldNames}) VALUES (${values});`;
      });
      content = insertRows.join('\n');
    }

    fs.writeFileSync(uri.fsPath, content, 'utf-8');
    vscode.window.showInformationMessage(`Successfully exported data to ${uri.fsPath}`);
  }
}

import * as vscode from 'vscode';
import { BaseNode } from './BaseNode.js';
import { DatabaseNode } from './DatabaseNode.js';
import { TableGroupNode } from './TableGroupNode.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { DriverManager } from '../drivers/DriverManager.js';

export class ConnectionNode extends BaseNode {
  public config: ConnectionConfig;
  public password?: string;
  private isConnected: boolean = false;

  constructor(config: ConnectionConfig, password?: string) {
    super(`conn_${config.id}`, config.name, 'connectionNode', vscode.TreeItemCollapsibleState.Collapsed);
    this.config = config;
    this.password = password;
  }

  getTreeItem(): vscode.TreeItem {
    const item = new vscode.TreeItem(this.label, vscode.TreeItemCollapsibleState.Collapsed);
    item.description = `${this.config.type} (${this.config.host || 'local'}:${this.config.port || ''})`;
    item.iconPath = new vscode.ThemeIcon(this.isConnected ? 'plug' : 'server');
    item.contextValue = 'connectionNode';
    return item;
  }

  async getChildren(): Promise<BaseNode[]> {
    try {
      const driver = await DriverManager.getInstance().getDriver(this.config, this.password);
      await driver.connect();
      this.isConnected = true;

      if (this.config.type === 'SQLite') {
        return [new TableGroupNode(this.config, this.password, 'main', this)];
      }

      if (this.config.database) {
        return [new TableGroupNode(this.config, this.password, this.config.schema || 'public', this)];
      }

      const dbs = await driver.getDatabases();
      return dbs.map((dbName) => new DatabaseNode(dbName, this.config, this.password, this));
    } catch (err: any) {
      vscode.window.showErrorMessage(`Failed to connect to ${this.config.name}: ${err.message}`);
      return [];
    }
  }
}

