export type DatabaseType = 'PostgreSQL' | 'MySQL' | 'SQLite' | 'Redis' | 'MongoDB';

export interface ConnectionConfig {
  id: string;
  name: string;
  type: DatabaseType;
  host?: string;
  port?: number;
  user?: string;
  database?: string;
  schema?: string;
  dbPath?: string; // For SQLite
  ssl?: boolean;
  ssh?: {
    enabled: boolean;
    host?: string;
    port?: number;
    username?: string;
    privateKeyPath?: string;
    usePrivateKey?: boolean;
  };
}

export interface SavedConnectionProfile extends ConnectionConfig {}

import * as vscode from 'vscode';
import { ConnectionConfig, SavedConnectionProfile } from '../model/ConnectionConfig.js';

export class ConnectionStorageService {
  private static readonly STORAGE_KEY = 'database_client_connections';
  private context: vscode.ExtensionContext;

  constructor(context: vscode.ExtensionContext) {
    this.context = context;
  }

  public getConnections(): SavedConnectionProfile[] {
    return this.context.globalState.get<SavedConnectionProfile[]>(ConnectionStorageService.STORAGE_KEY, []);
  }

  public getConnectionById(id: string): SavedConnectionProfile | undefined {
    return this.getConnections().find((c) => c.id === id);
  }

  public async saveConnection(config: ConnectionConfig, password?: string, sshPassword?: string): Promise<SavedConnectionProfile> {
    const connections = this.getConnections();
    const existingIndex = connections.findIndex((c) => c.id === config.id);

    const profile: SavedConnectionProfile = {
      id: config.id || `conn_${Date.now()}`,
      name: config.name,
      type: config.type,
      host: config.host,
      port: config.port,
      user: config.user,
      database: config.database,
      schema: config.schema,
      dbPath: config.dbPath,
      ssl: config.ssl,
      ssh: config.ssh,
    };

    if (password !== undefined && password !== '') {
      await this.context.secrets.store(`password_${profile.id}`, password);
    }

    if (sshPassword !== undefined && sshPassword !== '') {
      await this.context.secrets.store(`ssh_password_${profile.id}`, sshPassword);
    }

    if (existingIndex >= 0) {
      connections[existingIndex] = profile;
    } else {
      connections.push(profile);
    }

    await this.context.globalState.update(ConnectionStorageService.STORAGE_KEY, connections);
    return profile;
  }

  public async getPassword(id: string): Promise<string | undefined> {
    return await this.context.secrets.get(`password_${id}`);
  }

  public async getSshPassword(id: string): Promise<string | undefined> {
    return await this.context.secrets.get(`ssh_password_${id}`);
  }

  public async deleteConnection(id: string): Promise<void> {
    const connections = this.getConnections().filter((c) => c.id !== id);
    await this.context.globalState.update(ConnectionStorageService.STORAGE_KEY, connections);
    await this.context.secrets.delete(`password_${id}`);
    await this.context.secrets.delete(`ssh_password_${id}`);
  }
}

import * as net from 'net';
import * as fs from 'fs';
import { Client, ConnectConfig } from 'ssh2';
import { ConnectionConfig } from '../model/ConnectionConfig.js';

export interface SshTunnelResult {
  localPort: number;
  close: () => void;
}

export class SshTunnelManager {
  public static async createTunnel(
    config: ConnectionConfig,
    sshPassword?: string
  ): Promise<SshTunnelResult> {
    if (!config.ssh || !config.ssh.enabled) {
      throw new Error('SSH is not enabled in configuration');
    }

    const sshClient = new Client();

    return new Promise((resolve, reject) => {
      const server = net.createServer((socket) => {
        sshClient.forwardOut(
          '127.0.0.1',
          socket.remotePort || 0,
          config.host || '127.0.0.1',
          config.port || 3306,
          (err, stream) => {
            if (err) {
              socket.end();
              return;
            }
            socket.pipe(stream).pipe(socket);
          }
        );
      });

      server.listen(0, '127.0.0.1', () => {
        const address = server.address() as net.AddressInfo;
        const localPort = address.port;

        const sshConnectOpts: ConnectConfig = {
          host: config.ssh?.host || '',
          port: config.ssh?.port || 22,
          username: config.ssh?.username || '',
          readyTimeout: 20000,
          keepaliveInterval: 10000,
        };

        if (config.ssh?.usePrivateKey && config.ssh.privateKeyPath) {
          try {
            sshConnectOpts.privateKey = fs.readFileSync(config.ssh.privateKeyPath);
            if (sshPassword) {
              sshConnectOpts.passphrase = sshPassword;
            }
          } catch (e: any) {
            server.close();
            return reject(new Error(`Failed to read SSH Private Key at "${config.ssh.privateKeyPath}": ${e.message}`));
          }
        } else {
          sshConnectOpts.password = sshPassword || '';
          sshConnectOpts.tryKeyboard = true;
        }

        sshClient
          .on('keyboard-interactive', (name, instructions, instructionsLang, prompts, finish) => {
            finish([sshPassword || '']);
          })
          .on('ready', () => {
            resolve({
              localPort,
              close: () => {
                server.close();
                sshClient.end();
              },
            });
          })
          .on('error', (err) => {
            server.close();
            reject(new Error(`SSH Tunnel Error: ${err.message}`));
          })
          .connect(sshConnectOpts);
      });
    });
  }
}

import * as vscode from 'vscode';
import { BaseNode } from './BaseNode.js';
import { DatabaseNode } from './DatabaseNode.js';
import { TableGroupNode } from './TableGroupNode.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { DriverManager } from '../drivers/DriverManager.js';

export class ConnectionNode extends BaseNode {
  public config: ConnectionConfig;
  public password?: string;
  public sshPassword?: string;
  private isConnected: boolean = false;

  constructor(config: ConnectionConfig, password?: string, sshPassword?: string) {
    super(`conn_${config.id}`, config.name, 'connectionNode', vscode.TreeItemCollapsibleState.Collapsed);
    this.config = config;
    this.password = password;
    this.sshPassword = sshPassword;
  }

  getTreeItem(): vscode.TreeItem {
    const item = new vscode.TreeItem(this.label, vscode.TreeItemCollapsibleState.Collapsed);
    item.description = `${this.config.type} (${this.config.host || 'local'}:${this.config.port || ''})`;
    item.iconPath = new vscode.ThemeIcon(this.isConnected ? 'plug' : 'server');
    item.contextValue = 'connectionNode';
    return item;
  }

  async getChildren(): Promise<BaseNode[]> {
    try {
      const driver = await DriverManager.getInstance().getDriver(this.config, this.password, this.sshPassword);
      await driver.connect();
      this.isConnected = true;

      if (this.config.type === 'SQLite') {
        return [new TableGroupNode(this.config, this.password, 'main', this)];
      }

      if (this.config.database) {
        return [new TableGroupNode(this.config, this.password, this.config.schema || 'public', this)];
      }

      const dbs = await driver.getDatabases();
      return dbs.map((dbName) => new DatabaseNode(dbName, this.config, this.password, this));
    } catch (err: any) {
      vscode.window.showErrorMessage(`Failed to connect to ${this.config.name}: ${err.message}`);
      return [];
    }
  }
}

import * as vscode from 'vscode';
import { BaseNode } from './BaseNode.js';
import { ConnectionNode } from './ConnectionNode.js';
import { ConnectionStorageService } from '../storage/ConnectionStorage.js';

export class DatabaseTreeProvider implements vscode.TreeDataProvider<BaseNode> {
  private _onDidChangeTreeData: vscode.EventEmitter<BaseNode | undefined | void> = new vscode.EventEmitter<BaseNode | undefined | void>();
  readonly onDidChangeTreeData: vscode.Event<BaseNode | undefined | void> = this._onDidChangeTreeData.event;

  private storageService: ConnectionStorageService;

  constructor(storageService: ConnectionStorageService) {
    this.storageService = storageService;
  }

  refresh(): void {
    this._onDidChangeTreeData.fire();
  }

  getTreeItem(element: BaseNode): vscode.TreeItem | Promise<vscode.TreeItem> {
    return element.getTreeItem();
  }

  async getChildren(element?: BaseNode): Promise<BaseNode[]> {
    if (!element) {
      const profiles = this.storageService.getConnections();
      const nodes: ConnectionNode[] = [];
      for (const p of profiles) {
        const pass = await this.storageService.getPassword(p.id);
        const sshPass = await this.storageService.getSshPassword(p.id);
        nodes.push(new ConnectionNode(p, pass, sshPass));
      }
      return nodes;
    }
    return element.getChildren();
  }
}

