export interface SavedConnectionProfile extends ConnectionConfig {}

import * as vscode from 'vscode';
import { BaseNode } from './BaseNode.js';
import { ConnectionNode } from './ConnectionNode.js';

export class GroupNode extends BaseNode {
  public groupName: string;
  public connectionNodes: ConnectionNode[];

  constructor(groupName: string, connectionNodes: ConnectionNode[]) {
    super(`group_${groupName}`, groupName, 'groupNode', vscode.TreeItemCollapsibleState.Expanded);
    this.groupName = groupName;
    this.connectionNodes = connectionNodes;
  }

  getTreeItem(): vscode.TreeItem {
    const item = new vscode.TreeItem(this.label, vscode.TreeItemCollapsibleState.Expanded);
    item.iconPath = new vscode.ThemeIcon('folder');
    item.contextValue = 'groupNode';
    item.description = `(${this.connectionNodes.length})`;
    return item;
  }

  async getChildren(): Promise<BaseNode[]> {
    return this.connectionNodes;
  }
}

import * as vscode from 'vscode';
import { BaseNode } from './BaseNode.js';
import { DatabaseNode } from './DatabaseNode.js';
import { TableGroupNode } from './TableGroupNode.js';
import { ConnectionConfig, ConnectionColor } from '../model/ConnectionConfig.js';
import { DriverManager } from '../drivers/DriverManager.js';

export class ConnectionNode extends BaseNode {
  public config: ConnectionConfig;
  public password?: string;
  public sshPassword?: string;
  private isConnected: boolean = false;

  constructor(config: ConnectionConfig, password?: string, sshPassword?: string) {
    super(`conn_${config.id}`, config.name, 'connectionNode', vscode.TreeItemCollapsibleState.Collapsed);
    this.config = config;
    this.password = password;
    this.sshPassword = sshPassword;
  }

  private getColorTheme(color?: ConnectionColor): vscode.ThemeColor | undefined {
    switch (color) {
      case 'red':
        return new vscode.ThemeColor('charts.red');
      case 'green':
        return new vscode.ThemeColor('charts.green');
      case 'yellow':
        return new vscode.ThemeColor('charts.yellow');
      case 'blue':
        return new vscode.ThemeColor('charts.blue');
      case 'purple':
        return new vscode.ThemeColor('charts.purple');
      case 'orange':
        return new vscode.ThemeColor('charts.orange');
      default:
        return undefined;
    }
  }

  getTreeItem(): vscode.TreeItem {
    const item = new vscode.TreeItem(this.label, vscode.TreeItemCollapsibleState.Collapsed);
    item.description = `${this.config.type} (${this.config.host || 'local'}:${this.config.port || ''})`;

    const themeColor = this.getColorTheme(this.config.color);
    const iconName = this.isConnected ? 'plug' : 'server';

    item.iconPath = themeColor ? new vscode.ThemeIcon(iconName, themeColor) : new vscode.ThemeIcon(iconName);
    item.contextValue = 'connectionNode';
    return item;
  }

  async getChildren(): Promise<BaseNode[]> {
    try {
      const driver = await DriverManager.getInstance().getDriver(this.config, this.password, this.sshPassword);
      await driver.connect();
      this.isConnected = true;

      if (this.config.type === 'SQLite') {
        return [new TableGroupNode(this.config, this.password, 'main', this)];
      }

      if (this.config.database) {
        return [new TableGroupNode(this.config, this.password, this.config.schema || 'public', this)];
      }

      const dbs = await driver.getDatabases();
      return dbs.map((dbName) => new DatabaseNode(dbName, this.config, this.password, this));
    } catch (err: any) {
      vscode.window.showErrorMessage(`Failed to connect to ${this.config.name}: ${err.message}`);
      return [];
    }
  }
}

import * as vscode from 'vscode';
import { BaseNode } from './BaseNode.js';
import { ConnectionNode } from './ConnectionNode.js';
import { GroupNode } from './GroupNode.js';
import { ConnectionStorageService } from '../storage/ConnectionStorage.js';

export class DatabaseTreeProvider implements vscode.TreeDataProvider<BaseNode> {
  private _onDidChangeTreeData: vscode.EventEmitter<BaseNode | undefined | void> = new vscode.EventEmitter<BaseNode | undefined | void>();
  readonly onDidChangeTreeData: vscode.Event<BaseNode | undefined | void> = this._onDidChangeTreeData.event;

  private storageService: ConnectionStorageService;

  constructor(storageService: ConnectionStorageService) {
    this.storageService = storageService;
  }

  refresh(): void {
    this._onDidChangeTreeData.fire();
  }

  getTreeItem(element: BaseNode): vscode.TreeItem | Promise<vscode.TreeItem> {
    return element.getTreeItem();
  }

  async getChildren(element?: BaseNode): Promise<BaseNode[]> {
    if (!element) {
      const profiles = this.storageService.getConnections();
      const connectionNodes: ConnectionNode[] = [];

      for (const p of profiles) {
        const pass = await this.storageService.getPassword(p.id);
        const sshPass = await this.storageService.getSshPassword(p.id);
        connectionNodes.push(new ConnectionNode(p, pass, sshPass));
      }

      // Group connections if any connection has a group set
      const hasGroups = connectionNodes.some((node) => node.config.group && node.config.group.trim() !== '');

      if (!hasGroups) {
        return connectionNodes;
      }

      const groupsMap = new Map<string, ConnectionNode[]>();
      const rootNodes: ConnectionNode[] = [];

      for (const node of connectionNodes) {
        const gName = node.config.group ? node.config.group.trim() : '';
        if (gName) {
          if (!groupsMap.has(gName)) {
            groupsMap.set(gName, []);
          }
          groupsMap.get(gName)!.push(node);
        } else {
          rootNodes.push(node);
        }
      }

      const resultNodes: BaseNode[] = [];

      for (const [groupName, nodes] of groupsMap.entries()) {
        resultNodes.push(new GroupNode(groupName, nodes));
      }

      return [...resultNodes, ...rootNodes];
    }
    return element.getChildren();
  }
}

