</head>
<body>
  <h2>${text.title}</h2>

  <div class="row">
    <div class="form-group col" style="flex: 2;">
      <label>${text.connName}</label>
      <input type="text" id="name" value="${ru ? 'Моя База Данных' : 'My Database'}" placeholder="${text.connNamePh}">
