import { BaseDriver } from './BaseDriver.js';
import { PostgresDriver } from './PostgresDriver.js';
import { MysqlDriver } from './MysqlDriver.js';
import { SqliteDriver } from './SqliteDriver.js';
import { RedisDriver } from './RedisDriver.js';
import { MongoDriver } from './MongoDriver.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { SshTunnelManager, SshTunnelResult } from '../ssh/SshTunnelManager.js';

export class DriverManager {
  private static instance: DriverManager;
  private activeDrivers: Map<string, BaseDriver> = new Map();
  private sshTunnels: Map<string, SshTunnelResult> = new Map();

  private constructor() {}

  public static getInstance(): DriverManager {
    if (!DriverManager.instance) {
      DriverManager.instance = new DriverManager();
    }
    return DriverManager.instance;
  }

  public async getDriver(config: ConnectionConfig, password?: string, sshPassword?: string): Promise<BaseDriver> {
    const driverKey = `${config.id}_${config.database || ''}`;
    let driver = this.activeDrivers.get(driverKey);

    if (!driver) {
      let finalConfig = { ...config };

      if (config.ssh && config.ssh.enabled) {
        let tunnel = this.sshTunnels.get(config.id);
        if (!tunnel) {
          tunnel = await SshTunnelManager.createTunnel(config, sshPassword);
          this.sshTunnels.set(config.id, tunnel);
        }
        finalConfig.host = '127.0.0.1';
        finalConfig.port = tunnel.localPort;
      }

      switch (config.type) {
        case 'PostgreSQL':
          driver = new PostgresDriver(finalConfig, password);
          break;
        case 'MySQL':
          driver = new MysqlDriver(finalConfig, password);
          break;
        case 'SQLite':
          driver = new SqliteDriver(finalConfig, password);
          break;
        case 'Redis':
          driver = new RedisDriver(finalConfig, password);
          break;
        case 'MongoDB':
          driver = new MongoDriver(finalConfig, password);
          break;
        default:
          throw new Error(`Unsupported database type: ${config.type}`);
      }
      this.activeDrivers.set(driverKey, driver);
    }
    return driver;
  }

  public async disconnectAll(): Promise<void> {
    for (const [key, driver] of this.activeDrivers.entries()) {
      await driver.disconnect();
    }
    this.activeDrivers.clear();

    for (const [id, tunnel] of this.sshTunnels.entries()) {
      tunnel.close();
    }
    this.sshTunnels.clear();
  }

  public async removeDriver(id: string): Promise<void> {
    for (const [key, driver] of this.activeDrivers.entries()) {
      if (key.startsWith(id)) {
        await driver.disconnect();
        this.activeDrivers.delete(key);
      }
    }
    const tunnel = this.sshTunnels.get(id);
    if (tunnel) {
      tunnel.close();
      this.sshTunnels.delete(id);
    }
  }
}

import { Client } from 'pg';
import { BaseDriver } from './BaseDriver.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { ColumnInfo, PageParams, QueryResult, TableInfo } from '../model/QueryTypes.js';

export class PostgresDriver extends BaseDriver {
  private client: Client | null = null;

  constructor(config: ConnectionConfig, password?: string) {
    super(config, password);
  }

  private createClient(databaseName?: string): Client {
    return new Client({
      host: this.config.host || 'localhost',
      port: this.config.port || 5432,
      user: this.config.user || 'postgres',
      password: this.password || '',
      database: databaseName || this.config.database || 'postgres',
      ssl: this.config.ssl ? { rejectUnauthorized: false } : undefined,
      connectionTimeoutMillis: 5000,
    });
  }

  async connect(): Promise<void> {
    if (this.client) {
      await this.disconnect();
    }
    this.client = this.createClient();
    await this.client.connect();
    this.isConnected = true;
  }

  async disconnect(): Promise<void> {
    if (this.client) {
      try {
        await this.client.end();
      } catch (e) {
        // Ignore disconnect errors
      }
      this.client = null;
      this.isConnected = false;
    }
  }

  async testConnection(): Promise<{ success: boolean; message?: string }> {
    const tempClient = this.createClient();
    try {
      await tempClient.connect();
      await tempClient.query('SELECT 1');
      await tempClient.end();
      return { success: true, message: 'Successfully connected to PostgreSQL database!' };
    } catch (err: any) {
      return { success: false, message: err.message || 'Connection failed' };
    }
  }

  async getDatabases(): Promise<string[]> {
    const res = await this.executeQuery(
      "SELECT datname FROM pg_database WHERE datistemplate = false ORDER BY datname ASC;"
    );
    return res.rows.map((r) => r.datname);
  }

  async getTables(databaseName?: string, schemaName: string = 'public'): Promise<TableInfo[]> {
    const sql = `
      SELECT table_name, table_type
      FROM information_schema.tables
      WHERE table_schema = '${schemaName}'
      ORDER BY table_name ASC;
    `;
    const res = await this.executeQuery(sql);
    return res.rows.map((r) => ({
      name: r.table_name,
      schema: schemaName,
      type: r.table_type === 'VIEW' ? 'view' : 'table',
    }));
  }

  async getColumns(tableName: string, databaseName?: string, schemaName: string = 'public'): Promise<ColumnInfo[]> {
    const sql = `
      SELECT 
        c.column_name, 
        c.data_type, 
        c.is_nullable, 
        c.column_default,
        COALESCE(tc.constraint_type, '') as constraint_type
      FROM information_schema.columns c
      LEFT JOIN (
        SELECT kcu.table_schema, kcu.table_name, kcu.column_name, tc.constraint_type
        FROM information_schema.key_column_usage kcu
        JOIN information_schema.table_constraints tc
          ON kcu.table_schema = tc.table_schema 
          AND kcu.table_name = tc.table_name 
          AND kcu.constraint_name = tc.constraint_name 
          AND tc.constraint_type = 'PRIMARY KEY'
      ) tc
        ON c.table_schema = tc.table_schema 
        AND c.table_name = tc.table_name 
        AND c.column_name = tc.column_name
      WHERE c.table_schema = '${schemaName}' AND c.table_name = '${tableName}'
      ORDER BY c.ordinal_position ASC;
    `;
    const res = await this.executeQuery(sql);
    return res.rows.map((r) => ({
      name: r.column_name,
      type: r.data_type,
      nullable: r.is_nullable === 'YES',
      isPrimaryKey: r.constraint_type === 'PRIMARY KEY',
      defaultValue: r.column_default,
    }));
  }

  async executeQuery(sql: string): Promise<QueryResult> {
    if (!this.client) {
      await this.connect();
    }
    const startTime = Date.now();
    const res = await this.client!.query(sql);
    const costTimeMs = Date.now() - startTime;

    const fields: ColumnInfo[] = (res.fields || []).map((f) => ({
      name: f.name,
      type: 'unknown',
      nullable: true,
    }));

    return {
      rows: res.rows || [],
      fields,
      affectedRows: res.rowCount || 0,
      costTimeMs,
    };
  }

  async getTableData(tableName: string, params: PageParams, schemaName: string = 'public'): Promise<QueryResult> {
    const offset = (params.page - 1) * params.pageSize;
    let sql = `SELECT * FROM "${schemaName}"."${tableName}"`;

    if (params.filterSql) {
      sql += ` WHERE ${params.filterSql}`;
    }

    if (params.sortField && params.sortOrder) {
      sql += ` ORDER BY "${params.sortField}" ${params.sortOrder}`;
    }

    sql += ` LIMIT ${params.pageSize} OFFSET ${offset};`;

    const countSql = `SELECT COUNT(*) as total FROM "${schemaName}"."${tableName}"`;
    const countRes = await this.executeQuery(countSql);
    const totalCount = parseInt(countRes.rows[0]?.total || '0', 10);

    const queryResult = await this.executeQuery(sql);
    queryResult.totalCount = totalCount;
    return queryResult;
  }
}

import * as vscode from 'vscode';
import { BaseNode } from './BaseNode.js';
import { TableNode } from './TableNode.js';
import { DriverManager } from '../drivers/DriverManager.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { isRussian } from '../util/i18n.js';

export class TableGroupNode extends BaseNode {
  public connectionConfig: ConnectionConfig;
  public password?: string;
  public sshPassword?: string;
  public schemaName: string;

  constructor(connectionConfig: ConnectionConfig, password?: string, sshPassword?: string, schemaName: string = 'public', parent?: BaseNode) {
    const label = isRussian() ? 'Таблицы / Коллекции' : 'Tables / Collections';
    super(`table_group_${connectionConfig.id}_${schemaName}`, label, 'tableGroupNode', vscode.TreeItemCollapsibleState.Collapsed, parent);
    this.connectionConfig = connectionConfig;
    this.password = password;
    this.sshPassword = sshPassword;
    this.schemaName = schemaName;
  }

  getTreeItem(): vscode.TreeItem {
    const item = new vscode.TreeItem(this.label, vscode.TreeItemCollapsibleState.Collapsed);
    item.iconPath = new vscode.ThemeIcon('folder-library');
    item.contextValue = 'tableGroupNode';
    return item;
  }

  async getChildren(): Promise<BaseNode[]> {
    try {
      const driver = await DriverManager.getInstance().getDriver(this.connectionConfig, this.password, this.sshPassword);
      const tables = await driver.getTables(this.connectionConfig.database, this.schemaName);
      return tables.map((tbl) => new TableNode(tbl, this.connectionConfig, this.password, this.sshPassword, this));
    } catch (err: any) {
      vscode.window.showErrorMessage(`Failed to fetch tables: ${err.message}`);
      return [];
    }
  }
}

import * as vscode from 'vscode';
import { BaseNode } from './BaseNode.js';
import { ColumnNode } from './ColumnNode.js';
import { TableInfo } from '../model/QueryTypes.js';
import { DriverManager } from '../drivers/DriverManager.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';

export class TableNode extends BaseNode {
  public table: TableInfo;
  public connectionConfig: ConnectionConfig;
  public password?: string;
  public sshPassword?: string;

  constructor(table: TableInfo, connectionConfig: ConnectionConfig, password?: string, sshPassword?: string, parent?: BaseNode) {
    super(`table_${table.name}`, table.name, 'tableNode', vscode.TreeItemCollapsibleState.Collapsed, parent);
    this.table = table;
    this.connectionConfig = connectionConfig;
    this.password = password;
    this.sshPassword = sshPassword;
  }

  getTreeItem(): vscode.TreeItem {
    const item = new vscode.TreeItem(this.label, vscode.TreeItemCollapsibleState.Collapsed);
    item.iconPath = new vscode.ThemeIcon(this.table.type === 'view' ? 'eye' : 'table');
    item.contextValue = 'tableNode';
    item.command = {
      command: 'dbClient.openTable',
      title: 'Open Table',
      arguments: [this],
    };
    return item;
  }

  async getChildren(): Promise<BaseNode[]> {
    try {
      const driver = await DriverManager.getInstance().getDriver(this.connectionConfig, this.password, this.sshPassword);
      const columns = await driver.getColumns(this.table.name, this.connectionConfig.database, this.table.schema);
      return columns.map((col) => new ColumnNode(col, this));
    } catch (err: any) {
      vscode.window.showErrorMessage(`Failed to fetch columns for table ${this.table.name}: ${err.message}`);
      return [];
    }
  }
}

