import * as vscode from 'vscode';
import { BaseNode } from './BaseNode.js';
import { DatabaseNode } from './DatabaseNode.js';
import { TableGroupNode } from './TableGroupNode.js';
import { ConnectionConfig, ConnectionColor } from '../model/ConnectionConfig.js';
import { DriverManager } from '../drivers/DriverManager.js';

export class ConnectionNode extends BaseNode {
  public config: ConnectionConfig;
  public password?: string;
  public sshPassword?: string;
  private isConnected: boolean = false;

  constructor(config: ConnectionConfig, password?: string, sshPassword?: string) {
    super(`conn_${config.id}`, config.name, 'connectionNode', vscode.TreeItemCollapsibleState.Collapsed);
    this.config = config;
    this.password = password;
    this.sshPassword = sshPassword;
  }

  private getColorTheme(color?: ConnectionColor): vscode.ThemeColor | undefined {
    switch (color) {
      case 'red':
        return new vscode.ThemeColor('charts.red');
      case 'green':
        return new vscode.ThemeColor('charts.green');
      case 'yellow':
        return new vscode.ThemeColor('charts.yellow');
      case 'blue':
        return new vscode.ThemeColor('charts.blue');
      case 'purple':
        return new vscode.ThemeColor('charts.purple');
      case 'orange':
        return new vscode.ThemeColor('charts.orange');
      default:
        return undefined;
    }
  }

  getTreeItem(): vscode.TreeItem {
    const item = new vscode.TreeItem(this.label, vscode.TreeItemCollapsibleState.Collapsed);
    item.description = `${this.config.type} (${this.config.host || 'local'}:${this.config.port || ''})`;

    const themeColor = this.getColorTheme(this.config.color);
    const iconName = this.isConnected ? 'plug' : 'server';

    item.iconPath = themeColor ? new vscode.ThemeIcon(iconName, themeColor) : new vscode.ThemeIcon(iconName);
    item.contextValue = 'connectionNode';
    return item;
  }

  async getChildren(): Promise<BaseNode[]> {
    try {
      const driver = await DriverManager.getInstance().getDriver(this.config, this.password, this.sshPassword);
      await driver.connect();
      this.isConnected = true;

      if (this.config.type === 'SQLite') {
        return [new TableGroupNode(this.config, this.password, this.sshPassword, 'main', this)];
      }

      if (this.config.database) {
        return [new TableGroupNode(this.config, this.password, this.sshPassword, this.config.schema || 'public', this)];
      }

      const dbs = await driver.getDatabases();
      return dbs.map((dbName) => new DatabaseNode(dbName, this.config, this.password, this.sshPassword, this));
    } catch (err: any) {
      vscode.window.showErrorMessage(`Failed to connect to ${this.config.name}: ${err.message}`);
      return [];
    }
  }
}

import * as vscode from 'vscode';
import { DriverManager } from '../drivers/DriverManager.js';
import { TableNode } from '../tree/TableNode.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { PageParams, QueryResult } from '../model/QueryTypes.js';
import { ExportService } from '../export/ExportService.js';
import { isRussian, t } from '../util/i18n.js';

export class TableWebviewProvider {
  public static openTable(tableNode: TableNode) {
    const title = t(`Data: ${tableNode.table.name}`, `Данные: ${tableNode.table.name}`);
    const panel = vscode.window.createWebviewPanel(
      'dbClientDataGrid',
      title,
      vscode.ViewColumn.One,
      {
        enableScripts: true,
        retainContextWhenHidden: true,
      }
    );

    const connectionConfig = tableNode.connectionConfig;
    const tableName = tableNode.table.name;
    const schemaName = tableNode.table.schema || 'public';
    const password = tableNode.password;
    const sshPassword = tableNode.sshPassword;

    let currentParams: PageParams = {
      page: 1,
      pageSize: 50,
    };

    let lastResult: QueryResult | null = null;

    const loadData = async () => {
      try {
        const driver = await DriverManager.getInstance().getDriver(connectionConfig, password, sshPassword);
        const result = await driver.getTableData(tableName, currentParams, schemaName);
        lastResult = result;
        panel.webview.postMessage({
          type: 'renderData',
          tableName,
          result,
          params: currentParams,
        });
      } catch (err: any) {
        panel.webview.postMessage({
          type: 'error',
          message: err.message,
        });
      }
    };

    panel.webview.onDidReceiveMessage(async (msg) => {
      switch (msg.type) {
        case 'fetchData':
          if (msg.params) {
            currentParams = { ...currentParams, ...msg.params };
          }
          await loadData();
          break;
        case 'export':
          if (lastResult) {
            await ExportService.exportData(tableName, lastResult, msg.format);
          } else {
            vscode.window.showWarningMessage(t('No data available to export.', 'Нет данных для экспорта.'));
          }
          break;
      }
    });

    panel.webview.html = TableWebviewProvider.getHtml(tableName);
    loadData();
  }

  public static openQueryConsole(connectionConfig: ConnectionConfig, password?: string, sshPassword?: string) {
    const title = t(`Console: ${connectionConfig.name}`, `Консоль: ${connectionConfig.name}`);
    const panel = vscode.window.createWebviewPanel(
      'dbClientQueryConsole',
      title,
      vscode.ViewColumn.One,
      {
        enableScripts: true,
        retainContextWhenHidden: true,
      }
    );

    let lastResult: QueryResult | null = null;

    panel.webview.onDidReceiveMessage(async (msg) => {
      switch (msg.type) {
        case 'executeSql':
          try {
            const driver = await DriverManager.getInstance().getDriver(connectionConfig, password, sshPassword);
            const res = await driver.executeQuery(msg.sql);
            lastResult = res;
            panel.webview.postMessage({ type: 'queryResult', result: res });
          } catch (err: any) {
            panel.webview.postMessage({ type: 'error', message: err.message });
          }
          break;
        case 'export':
          if (lastResult) {
            await ExportService.exportData('query_result', lastResult, msg.format);
          } else {
            vscode.window.showWarningMessage(t('No query result available to export.', 'Нет результатов запроса для экспорта.'));
          }
          break;
      }
    });

    panel.webview.html = TableWebviewProvider.getConsoleHtml(connectionConfig.name);
  }

