import * as vscode from 'vscode';
import { BaseNode } from './BaseNode.js';
import { TableGroupNode } from './TableGroupNode.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';

export class SchemaNode extends BaseNode {
  public schemaName: string;
  public connectionConfig: ConnectionConfig;
  public password?: string;
  public sshPassword?: string;

  constructor(schemaName: string, connectionConfig: ConnectionConfig, password?: string, sshPassword?: string, parent?: BaseNode) {
    super(`schema_${connectionConfig.id}_${connectionConfig.database}_${schemaName}`, schemaName, 'schemaNode', vscode.TreeItemCollapsibleState.Collapsed, parent);
    this.schemaName = schemaName;
    this.connectionConfig = connectionConfig;
    this.password = password;
    this.sshPassword = sshPassword;
  }

  getTreeItem(): vscode.TreeItem {
    const item = new vscode.TreeItem(this.label, vscode.TreeItemCollapsibleState.Collapsed);
    item.iconPath = new vscode.ThemeIcon('symbol-namespace');
    item.contextValue = 'schemaNode';
    return item;
  }

  async getChildren(): Promise<BaseNode[]> {
    return [new TableGroupNode(this.connectionConfig, this.password, this.sshPassword, this.schemaName, this)];
  }
}

import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { ColumnInfo, QueryResult, TableInfo, PageParams } from '../model/QueryTypes.js';

export abstract class BaseDriver {
  protected config: ConnectionConfig;
  protected password?: string;
  protected isConnected: boolean = false;

  constructor(config: ConnectionConfig, password?: string) {
    this.config = config;
    this.password = password;
  }

  abstract connect(): Promise<void>;
  abstract disconnect(): Promise<void>;
  abstract testConnection(): Promise<{ success: boolean; message?: string }>;

  abstract getDatabases(): Promise<string[]>;
  async getSchemas(databaseName?: string): Promise<string[]> {
    return ['public'];
  }
  abstract getTables(databaseName?: string, schemaName?: string): Promise<TableInfo[]>;
  abstract getColumns(tableName: string, databaseName?: string, schemaName?: string): Promise<ColumnInfo[]>;

  abstract executeQuery(sql: string): Promise<QueryResult>;
  abstract getTableData(tableName: string, params: PageParams, schemaName?: string): Promise<QueryResult>;

  public getIsConnected(): boolean {
    return this.isConnected;
  }
}

import { Client } from 'pg';
import { BaseDriver } from './BaseDriver.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { ColumnInfo, PageParams, QueryResult, TableInfo } from '../model/QueryTypes.js';

export class PostgresDriver extends BaseDriver {
  private client: Client | null = null;

  constructor(config: ConnectionConfig, password?: string) {
    super(config, password);
  }

  private createClient(databaseName?: string): Client {
    return new Client({
      host: this.config.host || 'localhost',
      port: this.config.port || 5432,
      user: this.config.user || 'postgres',
      password: this.password || '',
      database: databaseName || this.config.database || 'postgres',
      ssl: this.config.ssl ? { rejectUnauthorized: false } : undefined,
      connectionTimeoutMillis: 5000,
    });
  }

  async connect(): Promise<void> {
    if (this.client) {
      await this.disconnect();
    }
    this.client = this.createClient();
    await this.client.connect();
    this.isConnected = true;
  }

  async disconnect(): Promise<void> {
    if (this.client) {
      try {
        await this.client.end();
      } catch (e) {
        // Ignore disconnect errors
      }
      this.client = null;
      this.isConnected = false;
    }
  }

  async testConnection(): Promise<{ success: boolean; message?: string }> {
    const tempClient = this.createClient();
    try {
      await tempClient.connect();
      await tempClient.query('SELECT 1');
      await tempClient.end();
      return { success: true, message: 'Successfully connected to PostgreSQL database!' };
    } catch (err: any) {
      return { success: false, message: err.message || 'Connection failed' };
    }
  }

  async getDatabases(): Promise<string[]> {
    const res = await this.executeQuery(
      "SELECT datname FROM pg_database WHERE datistemplate = false ORDER BY datname ASC;"
    );
    return res.rows.map((r) => r.datname);
  }

  async getSchemas(databaseName?: string): Promise<string[]> {
    const res = await this.executeQuery(
      "SELECT schema_name FROM information_schema.schemata WHERE schema_name NOT IN ('information_schema', 'pg_catalog', 'pg_toast') ORDER BY schema_name ASC;"
    );
    const schemas = res.rows.map((r) => r.schema_name);
    return schemas.length > 0 ? schemas : ['public'];
  }

  async getTables(databaseName?: string, schemaName?: string): Promise<TableInfo[]> {
    let whereClause = "table_schema NOT IN ('information_schema', 'pg_catalog', 'pg_toast')";
    if (schemaName) {
      whereClause = `table_schema = '${schemaName}'`;
    }

    const sql = `
      SELECT table_schema, table_name, table_type
      FROM information_schema.tables
      WHERE ${whereClause}
      ORDER BY table_name ASC;
    `;
    const res = await this.executeQuery(sql);
    return res.rows.map((r) => ({
      name: r.table_name,
      schema: r.table_schema || schemaName || 'public',
      type: r.table_type === 'VIEW' ? 'view' : 'table',
    }));
  }

  async getColumns(tableName: string, databaseName?: string, schemaName: string = 'public'): Promise<ColumnInfo[]> {
    const sql = `
      SELECT 
        c.column_name, 
        c.data_type, 
        c.is_nullable, 
        c.column_default,
        COALESCE(tc.constraint_type, '') as constraint_type
      FROM information_schema.columns c
      LEFT JOIN (
        SELECT kcu.table_schema, kcu.table_name, kcu.column_name, tc.constraint_type
        FROM information_schema.key_column_usage kcu
        JOIN information_schema.table_constraints tc
          ON kcu.table_schema = tc.table_schema 
          AND kcu.table_name = tc.table_name 
          AND kcu.constraint_name = tc.constraint_name 
          AND tc.constraint_type = 'PRIMARY KEY'
      ) tc
        ON c.table_schema = tc.table_schema 
        AND c.table_name = tc.table_name 
        AND c.column_name = tc.column_name
      WHERE c.table_schema = '${schemaName}' AND c.table_name = '${tableName}'
      ORDER BY c.ordinal_position ASC;
    `;
    const res = await this.executeQuery(sql);
    return res.rows.map((r) => ({
      name: r.column_name,
      type: r.data_type,
      nullable: r.is_nullable === 'YES',
      isPrimaryKey: r.constraint_type === 'PRIMARY KEY',
      defaultValue: r.column_default,
    }));
  }

  async executeQuery(sql: string): Promise<QueryResult> {
    if (!this.client) {
      await this.connect();
    }
    const startTime = Date.now();
    const res = await this.client!.query(sql);
    const costTimeMs = Date.now() - startTime;

    const fields: ColumnInfo[] = (res.fields || []).map((f) => ({
      name: f.name,
      type: 'unknown',
      nullable: true,
    }));

    return {
      rows: res.rows || [],
      fields,
      affectedRows: res.rowCount || 0,
      costTimeMs,
    };
  }

  async getTableData(tableName: string, params: PageParams, schemaName: string = 'public'): Promise<QueryResult> {
    const offset = (params.page - 1) * params.pageSize;
    let sql = `SELECT * FROM "${schemaName}"."${tableName}"`;

    if (params.filterSql) {
      sql += ` WHERE ${params.filterSql}`;
    }

    if (params.sortField && params.sortOrder) {
      sql += ` ORDER BY "${params.sortField}" ${params.sortOrder}`;
    }

    sql += ` LIMIT ${params.pageSize} OFFSET ${offset};`;

    const countSql = `SELECT COUNT(*) as total FROM "${schemaName}"."${tableName}"`;
    const countRes = await this.executeQuery(countSql);
    const totalCount = parseInt(countRes.rows[0]?.total || '0', 10);

    const queryResult = await this.executeQuery(sql);
    queryResult.totalCount = totalCount;
    return queryResult;
  }
}

import * as vscode from 'vscode';
import { BaseNode } from './BaseNode.js';
import { TableGroupNode } from './TableGroupNode.js';
import { SchemaNode } from './SchemaNode.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { DriverManager } from '../drivers/DriverManager.js';

export class DatabaseNode extends BaseNode {
  public dbName: string;
  public connectionConfig: ConnectionConfig;
  public password?: string;
  public sshPassword?: string;

  constructor(dbName: string, connectionConfig: ConnectionConfig, password?: string, sshPassword?: string, parent?: BaseNode) {
    super(`db_${connectionConfig.id}_${dbName}`, dbName, 'databaseNode', vscode.TreeItemCollapsibleState.Collapsed, parent);
    this.dbName = dbName;
    this.connectionConfig = { ...connectionConfig, database: dbName };
    this.password = password;
    this.sshPassword = sshPassword;
  }

  getTreeItem(): vscode.TreeItem {
    const item = new vscode.TreeItem(this.label, vscode.TreeItemCollapsibleState.Collapsed);
    item.iconPath = new vscode.ThemeIcon('database');
    item.contextValue = 'databaseNode';
    return item;
  }

  async getChildren(): Promise<BaseNode[]> {
    try {
      if (this.connectionConfig.type === 'PostgreSQL') {
        const driver = await DriverManager.getInstance().getDriver(this.connectionConfig, this.password, this.sshPassword);
        const schemas = await driver.getSchemas(this.dbName);

        if (schemas.length > 1) {
          return schemas.map((s) => new SchemaNode(s, this.connectionConfig, this.password, this.sshPassword, this));
        } else if (schemas.length === 1) {
          return [new TableGroupNode(this.connectionConfig, this.password, this.sshPassword, schemas[0], this)];
        }
      }
    } catch (e: any) {
      vscode.window.showErrorMessage(`Failed to load schemas for database ${this.dbName}: ${e.message}`);
    }

    return [new TableGroupNode(this.connectionConfig, this.password, this.sshPassword, this.connectionConfig.schema || 'public', this)];
  }
}

import * as vscode from 'vscode';
import { BaseNode } from './BaseNode.js';
import { DatabaseNode } from './DatabaseNode.js';
import { TableGroupNode } from './TableGroupNode.js';
import { ConnectionConfig, ConnectionColor } from '../model/ConnectionConfig.js';
import { DriverManager } from '../drivers/DriverManager.js';

export class ConnectionNode extends BaseNode {
  public config: ConnectionConfig;
  public password?: string;
  public sshPassword?: string;
  private isConnected: boolean = false;

  constructor(config: ConnectionConfig, password?: string, sshPassword?: string) {
    super(`conn_${config.id}`, config.name, 'connectionNode', vscode.TreeItemCollapsibleState.Collapsed);
    this.config = config;
    this.password = password;
    this.sshPassword = sshPassword;
  }

  private getColorTheme(color?: ConnectionColor): vscode.ThemeColor | undefined {
    switch (color) {
      case 'red':
        return new vscode.ThemeColor('charts.red');
      case 'green':
        return new vscode.ThemeColor('charts.green');
      case 'yellow':
        return new vscode.ThemeColor('charts.yellow');
      case 'blue':
        return new vscode.ThemeColor('charts.blue');
      case 'purple':
        return new vscode.ThemeColor('charts.purple');
      case 'orange':
        return new vscode.ThemeColor('charts.orange');
      default:
        return undefined;
    }
  }

  getTreeItem(): vscode.TreeItem {
    const item = new vscode.TreeItem(this.label, vscode.TreeItemCollapsibleState.Collapsed);
    item.description = `${this.config.type} (${this.config.host || 'local'}:${this.config.port || ''})`;

    const themeColor = this.getColorTheme(this.config.color);
    const iconName = this.isConnected ? 'plug' : 'server';

    item.iconPath = themeColor ? new vscode.ThemeIcon(iconName, themeColor) : new vscode.ThemeIcon(iconName);
    item.contextValue = 'connectionNode';
    return item;
  }

  async getChildren(): Promise<BaseNode[]> {
    try {
      const driver = await DriverManager.getInstance().getDriver(this.config, this.password, this.sshPassword);
      await driver.connect();
      this.isConnected = true;

      if (this.config.type === 'SQLite') {
        return [new TableGroupNode(this.config, this.password, this.sshPassword, 'main', this)];
      }

      if (this.config.database) {
        return [new DatabaseNode(this.config.database, this.config, this.password, this.sshPassword, this)];
      }

      const dbs = await driver.getDatabases();
      return dbs.map((dbName) => new DatabaseNode(dbName, this.config, this.password, this.sshPassword, this));
    } catch (err: any) {
      vscode.window.showErrorMessage(`Failed to connect to ${this.config.name}: ${err.message}`);
      return [];
    }
  }
}

