export type DatabaseType = 'PostgreSQL' | 'MySQL' | 'SQLite' | 'Redis' | 'MongoDB' | 'Elasticsearch';

export type ConnectionColor = 'red' | 'green' | 'yellow' | 'blue' | 'purple' | 'orange' | 'default';

export interface ConnectionConfig {
  id: string;
  name: string;
  type: DatabaseType;
  group?: string;
  color?: ConnectionColor;
  host?: string;
  port?: number;
  user?: string;
  database?: string;
  schema?: string;
  dbPath?: string; // For SQLite
  ssl?: boolean;
  ssh?: {
    enabled: boolean;
    host?: string;
    port?: number;
    username?: string;
    privateKeyPath?: string;
    usePrivateKey?: boolean;
  };
}

export interface SavedConnectionProfile extends ConnectionConfig {}

import { Client } from '@elastic/elasticsearch';
import { BaseDriver } from './BaseDriver.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { ColumnInfo, PageParams, QueryResult, TableInfo } from '../model/QueryTypes.js';

export class ElasticsearchDriver extends BaseDriver {
  private client: Client | null = null;

  constructor(config: ConnectionConfig, password?: string) {
    super(config, password);
  }

  async connect(): Promise<void> {
    if (this.client) {
      await this.disconnect();
    }
    const protocol = this.config.ssl ? 'https' : 'http';
    const host = this.config.host || 'localhost';
    const port = this.config.port || 9200;
    const node = `${protocol}://${host}:${port}`;

    const auth =
      this.config.user && this.password
        ? { username: this.config.user, password: this.password }
        : undefined;

    this.client = new Client({
      node,
      auth,
      tls: this.config.ssl ? { rejectUnauthorized: false } : undefined,
    });
    this.isConnected = true;
  }

  async disconnect(): Promise<void> {
    if (this.client) {
      try {
        await this.client.close();
      } catch (e) {}
      this.client = null;
      this.isConnected = false;
    }
  }

  async testConnection(): Promise<{ success: boolean; message?: string }> {
    try {
      await this.connect();
      const ping = await this.client?.ping();
      await this.disconnect();
      return { success: true, message: 'Successfully connected to Elasticsearch cluster!' };
    } catch (err: any) {
      return { success: false, message: err.message || 'Connection failed' };
    }
  }

  async getDatabases(): Promise<string[]> {
    return ['cluster'];
  }

  async getTables(): Promise<TableInfo[]> {
    if (!this.client) {
      await this.connect();
    }
    const catIndices = await this.client!.cat.indices({ format: 'json' });
    const indices = Array.isArray(catIndices) ? catIndices : [];
    return indices
      .filter((idx: any) => !idx.index.startsWith('.'))
      .map((idx: any) => ({
        name: idx.index,
        type: 'table',
      }));
  }

  async getColumns(indexName: string): Promise<ColumnInfo[]> {
    if (!this.client) {
      await this.connect();
    }
    try {
      const mapping = await this.client!.indices.getMapping({ index: indexName });
      const properties = (mapping as any)[indexName]?.mappings?.properties || {};
      return Object.keys(properties).map((prop) => ({
        name: prop,
        type: properties[prop].type || 'object',
        nullable: true,
        isPrimaryKey: prop === '_id',
      }));
    } catch (e) {
      return [{ name: '_id', type: 'keyword', nullable: false, isPrimaryKey: true }];
    }
  }

  async executeQuery(queryJson: string): Promise<QueryResult> {
    if (!this.client) {
      await this.connect();
    }
    const startTime = Date.now();
    const body = queryJson.trim() ? JSON.parse(queryJson) : { query: { match_all: {} } };

    const searchRes = await this.client!.search({
      index: this.config.database || '_all',
      body,
    });
    const costTimeMs = Date.now() - startTime;

    const hits = searchRes.hits.hits.map((h: any) => ({
      _id: h._id,
      _index: h._index,
      ...h._source,
    }));

    const fields: ColumnInfo[] =
      hits.length > 0 ? Object.keys(hits[0]).map((k) => ({ name: k, type: 'unknown', nullable: true })) : [];

    return {
      rows: hits,
      fields,
      totalCount: typeof searchRes.hits.total === 'number' ? searchRes.hits.total : (searchRes.hits.total as any)?.value || 0,
      costTimeMs,
    };
  }

  async getTableData(indexName: string, params: PageParams): Promise<QueryResult> {
    if (!this.client) {
      await this.connect();
    }
    const startTime = Date.now();
    const from = (params.page - 1) * params.pageSize;

    const searchRes = await this.client!.search({
      index: indexName,
      from,
      size: params.pageSize,
    });
    const costTimeMs = Date.now() - startTime;

    const hits = searchRes.hits.hits.map((h: any) => ({
      _id: h._id,
      _score: h._score,
      ...h._source,
    }));

    const fields: ColumnInfo[] =
      hits.length > 0 ? Object.keys(hits[0]).map((k) => ({ name: k, type: typeof hits[0][k], nullable: true })) : [];

    const totalCount =
      typeof searchRes.hits.total === 'number' ? searchRes.hits.total : (searchRes.hits.total as any)?.value || 0;

    return {
      rows: hits,
      fields,
      totalCount,
      costTimeMs,
    };
  }
}

import { BaseDriver } from './BaseDriver.js';
import { PostgresDriver } from './PostgresDriver.js';
import { MysqlDriver } from './MysqlDriver.js';
import { SqliteDriver } from './SqliteDriver.js';
import { RedisDriver } from './RedisDriver.js';
import { MongoDriver } from './MongoDriver.js';
import { ElasticsearchDriver } from './ElasticsearchDriver.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { SshTunnelManager, SshTunnelResult } from '../ssh/SshTunnelManager.js';

export class DriverManager {
  private static instance: DriverManager;
  private activeDrivers: Map<string, BaseDriver> = new Map();
  private sshTunnels: Map<string, SshTunnelResult> = new Map();

  private constructor() {}

  public static getInstance(): DriverManager {
    if (!DriverManager.instance) {
      DriverManager.instance = new DriverManager();
    }
    return DriverManager.instance;
  }

  public async getDriver(config: ConnectionConfig, password?: string, sshPassword?: string): Promise<BaseDriver> {
    const driverKey = `${config.id}_${config.database || ''}`;
    let driver = this.activeDrivers.get(driverKey);

    if (!driver) {
      let finalConfig = { ...config };

      if (config.ssh && config.ssh.enabled) {
        let tunnel = this.sshTunnels.get(config.id);
        if (!tunnel) {
          tunnel = await SshTunnelManager.createTunnel(config, sshPassword);
          this.sshTunnels.set(config.id, tunnel);
        }
        finalConfig.host = '127.0.0.1';
        finalConfig.port = tunnel.localPort;
      }

      switch (config.type) {
        case 'PostgreSQL':
          driver = new PostgresDriver(finalConfig, password);
          break;
        case 'MySQL':
          driver = new MysqlDriver(finalConfig, password);
          break;
        case 'SQLite':
          driver = new SqliteDriver(finalConfig, password);
          break;
        case 'Redis':
          driver = new RedisDriver(finalConfig, password);
          break;
        case 'MongoDB':
          driver = new MongoDriver(finalConfig, password);
          break;
        case 'Elasticsearch':
          driver = new ElasticsearchDriver(finalConfig, password);
          break;
        default:
          throw new Error(`Unsupported database type: ${config.type}`);
      }
      this.activeDrivers.set(driverKey, driver);
    }
    return driver;
  }

  public async disconnectAll(): Promise<void> {
    for (const [key, driver] of this.activeDrivers.entries()) {
      await driver.disconnect();
    }
    this.activeDrivers.clear();

    for (const [id, tunnel] of this.sshTunnels.entries()) {
      tunnel.close();
    }
    this.sshTunnels.clear();
  }

  public async removeDriver(id: string): Promise<void> {
    for (const [key, driver] of this.activeDrivers.entries()) {
      if (key.startsWith(id)) {
        await driver.disconnect();
        this.activeDrivers.delete(key);
      }
    }
    const tunnel = this.sshTunnels.get(id);
    if (tunnel) {
      tunnel.close();
      this.sshTunnels.delete(id);
    }
  }
}

