import * as vscode from 'vscode';

export interface HistoryItem {
  id: string;
  sql: string;
  timestamp: number;
  costTimeMs?: number;
  connectionName: string;
}

export interface FavoriteSnippet {
  id: string;
  title: string;
  sql: string;
  createdAt: number;
}

export class QueryHistoryStorage {
  private static readonly HISTORY_KEY = 'db_client_query_history';
  private static readonly SNIPPETS_KEY = 'db_client_query_snippets';
  private context: vscode.ExtensionContext;

  constructor(context: vscode.ExtensionContext) {
    this.context = context;
  }

  public getHistory(): HistoryItem[] {
    return this.context.globalState.get<HistoryItem[]>(QueryHistoryStorage.HISTORY_KEY, []);
  }

  public async addHistory(sql: string, connectionName: string, costTimeMs?: number): Promise<void> {
    const list = this.getHistory();
    const newItem: HistoryItem = {
      id: 'hist_' + Date.now(),
      sql: sql.trim(),
      timestamp: Date.now(),
      costTimeMs,
      connectionName,
    };

    // Filter duplicates and cap at 100 entries
    const filtered = [newItem, ...list.filter((item) => item.sql !== newItem.sql)].slice(0, 100);
    await this.context.globalState.update(QueryHistoryStorage.HISTORY_KEY, filtered);
  }

  public getSnippets(): FavoriteSnippet[] {
    return this.context.globalState.get<FavoriteSnippet[]>(QueryHistoryStorage.SNIPPETS_KEY, []);
  }

  public async addSnippet(title: string, sql: string): Promise<void> {
    const snippets = this.getSnippets();
    const newSnippet: FavoriteSnippet = {
      id: 'snip_' + Date.now(),
      title,
      sql: sql.trim(),
      createdAt: Date.now(),
    };
    snippets.unshift(newSnippet);
    await this.context.globalState.update(QueryHistoryStorage.SNIPPETS_KEY, snippets);
  }

  public async deleteSnippet(id: string): Promise<void> {
    const snippets = this.getSnippets().filter((s) => s.id !== id);
    await this.context.globalState.update(QueryHistoryStorage.SNIPPETS_KEY, snippets);
  }
}

import * as vscode from 'vscode';
import * as fs from 'fs';
import { DriverManager } from '../drivers/DriverManager.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { t } from '../util/i18n.js';

export class DatabaseDumpService {
  public static async dumpDatabase(config: ConnectionConfig, password?: string, sshPassword?: string) {
    const saveUri = await vscode.window.showSaveDialog({
      defaultUri: vscode.Uri.file(`${config.database || config.name}_dump.sql`),
      filters: { 'SQL Files': ['sql'] },
      saveLabel: t('Export SQL Dump', 'Экспортировать дамп SQL'),
    });

    if (!saveUri) {
      return;
    }

    await vscode.window.withProgress(
      {
        location: vscode.ProgressLocation.Notification,
        title: t(`Exporting SQL dump for ${config.name}...`, `Экспорт дампа SQL для ${config.name}...`),
        cancellable: false,
      },
      async () => {
        try {
          const driver = await DriverManager.getInstance().getDriver(config, password, sshPassword);
          const tables = await driver.getTables(config.database);

          let sqlDump = `-- Anarchy DB Client SQL Dump\n-- Database: ${config.database || config.name}\n-- Date: ${new Date().toISOString()}\n\n`;

          for (const tbl of tables) {
            sqlDump += `-- Table structure for "${tbl.name}"\n`;
            const columns = await driver.getColumns(tbl.name, config.database, tbl.schema);

            sqlDump += `DROP TABLE IF EXISTS "${tbl.name}";\nCREATE TABLE "${tbl.name}" (\n`;
            const colDefs = columns.map(
              (c) => `  "${c.name}" ${c.type}${c.isPrimaryKey ? ' PRIMARY KEY' : ''}${c.nullable ? '' : ' NOT NULL'}${c.defaultValue ? ` DEFAULT ${c.defaultValue}` : ''}`
            );
            sqlDump += colDefs.join(',\n');
            sqlDump += '\n);\n\n';

            // Dump Table Rows
            const rowData = await driver.getTableData(tbl.name, { page: 1, pageSize: 500 }, tbl.schema);
            if (rowData.rows && rowData.rows.length > 0) {
              sqlDump += `-- Dumping data for "${tbl.name}"\n`;
              for (const row of rowData.rows) {
                const colNames = rowData.fields.map((f) => `"${f.name}"`).join(', ');
                const valStrings = rowData.fields.map((f) => {
                  const val = row[f.name];
                  if (val === null || val === undefined) return 'NULL';
                  if (typeof val === 'number') return val;
                  return `'${String(val).replace(/'/g, "''")}'`;
                }).join(', ');
                sqlDump += `INSERT INTO "${tbl.name}" (${colNames}) VALUES (${valStrings});\n`;
              }
              sqlDump += '\n';
            }
          }

          fs.writeFileSync(saveUri.fsPath, sqlDump, 'utf8');
          vscode.window.showInformationMessage(
            t(`SQL Dump exported successfully to ${saveUri.fsPath}!`, `Дамп SQL успешно экспортирован в ${saveUri.fsPath}!`)
          );
        } catch (err: any) {
          vscode.window.showErrorMessage(`Dump failed: ${err.message}`);
        }
      }
    );
  }

  public static async importSqlFile(config: ConnectionConfig, password?: string, sshPassword?: string) {
    const openUris = await vscode.window.showOpenDialog({
      canSelectMany: false,
      filters: { 'SQL Files': ['sql'] },
      openLabel: t('Import SQL File', 'Импортировать файл SQL'),
    });

    if (!openUris || openUris.length === 0) {
      return;
    }

    const filePath = openUris[0].fsPath;

    await vscode.window.withProgress(
      {
        location: vscode.ProgressLocation.Notification,
        title: t(`Importing SQL file into ${config.name}...`, `Импорт файла SQL в ${config.name}...`),
        cancellable: false,
      },
      async () => {
        try {
          const sqlContent = fs.readFileSync(filePath, 'utf8');
          const driver = await DriverManager.getInstance().getDriver(config, password, sshPassword);

          // Split queries by semicolon
          const queries = sqlContent
            .split(';')
            .map((q) => q.trim())
            .filter((q) => q.length > 0);

          for (const q of queries) {
            await driver.executeQuery(q);
          }

          vscode.window.showInformationMessage(
            t(`Successfully executed ${queries.length} queries from ${filePath}!`, `Успешно выполнено ${queries.length} запросов из ${filePath}!`)
          );
        } catch (err: any) {
          vscode.window.showErrorMessage(`Import failed: ${err.message}`);
        }
      }
    );
  }
}

import * as vscode from 'vscode';
import { DriverManager } from '../drivers/DriverManager.js';
import { TableNode } from '../tree/TableNode.js';
import { ColumnInfo } from '../model/QueryTypes.js';
import { t } from '../util/i18n.js';

export class MockDataGenerator {
  public static async generateForTable(tableNode: TableNode) {
    const countInput = await vscode.window.showInputBox({
      prompt: t('Enter number of mock rows to generate (1 - 500):', 'Введите количество фейковых строк (1 - 500):'),
      value: '50',
      validateInput: (val) => {
        const num = parseInt(val, 10);
        if (isNaN(num) || num < 1 || num > 500) {
          return t('Please enter a valid number between 1 and 500', 'Введите число от 1 до 500');
        }
        return null;
      },
    });

    if (!countInput) {
      return;
    }

    const count = parseInt(countInput, 10);

    await vscode.window.withProgress(
      {
        location: vscode.ProgressLocation.Notification,
        title: t(`Generating ${count} mock rows for "${tableNode.table.name}"...`, `Генерация ${count} фейковых строк для "${tableNode.table.name}"...`),
        cancellable: false,
      },
      async () => {
        try {
          const driver = await DriverManager.getInstance().getDriver(
            tableNode.connectionConfig,
            tableNode.password,
            tableNode.sshPassword
          );

          const columns = await driver.getColumns(
            tableNode.table.name,
            tableNode.connectionConfig.database,
            tableNode.table.schema
          );

          // Filter out auto-incrementing primary keys if possible
          const insertCols = columns.filter((c) => !c.isPrimaryKey || !c.name.includes('id'));

          for (let i = 0; i < count; i++) {
            const values = insertCols.map((col) => MockDataGenerator.generateMockValue(col, i));
            const colNames = insertCols.map((c) => `"${c.name}"`).join(', ');
            const valStrings = values.map((v) => (v === null ? 'NULL' : typeof v === 'number' ? v : `'${v}'`)).join(', ');

            const sql = `INSERT INTO "${tableNode.table.name}" (${colNames}) VALUES (${valStrings});`;
            await driver.executeQuery(sql);
          }

          vscode.window.showInformationMessage(
            t(`Successfully inserted ${count} mock rows into "${tableNode.table.name}"!`, `Успешно добавлено ${count} фейковых строк в "${tableNode.table.name}"!`)
          );
        } catch (err: any) {
          vscode.window.showErrorMessage(`Mock generation failed: ${err.message}`);
        }
      }
    );
  }

  private static generateMockValue(col: ColumnInfo, index: number): any {
    const colName = col.name.toLowerCase();
    const type = col.type.toLowerCase();

    if (colName.includes('email')) {
      return `user_${index + 100}@example.com`;
    }
    if (colName.includes('name') || colName.includes('user')) {
      const names = ['Alex', 'Dmitry', 'Elena', 'Maria', 'Sergey', 'Anna', 'Ivan', 'Olga'];
      return `${names[index % names.length]}_${index + 1}`;
    }
    if (colName.includes('phone')) {
      return `+7999${String(1000000 + index).slice(1)}`;
    }
    if (colName.includes('status')) {
      return index % 2 === 0 ? 'active' : 'pending';
    }
    if (colName.includes('price') || colName.includes('amount') || colName.includes('cost')) {
      return parseFloat((Math.random() * 500 + 10).toFixed(2));
    }
    if (type.includes('int') || type.includes('number')) {
      return index + 1;
    }
    if (type.includes('bool')) {
      return index % 2 === 0;
    }
    if (type.includes('date') || type.includes('time')) {
      return new Date(Date.now() - index * 86400000).toISOString().slice(0, 19).replace('T', ' ');
    }

    return `Sample_${col.name}_${index + 1}`;
  }
}

import * as vscode from 'vscode';
import { DriverManager } from '../drivers/DriverManager.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { isRussian, t } from '../util/i18n.js';

export class ProcessListWebviewProvider {
  public static async show(connectionConfig: ConnectionConfig, password?: string, sshPassword?: string) {
    const title = t(`Process List: ${connectionConfig.name}`, `Процессы: ${connectionConfig.name}`);
    const panel = vscode.window.createWebviewPanel(
      'dbClientProcessList',
      title,
      vscode.ViewColumn.One,
      {
        enableScripts: true,
        retainContextWhenHidden: true,
      }
    );

    const loadProcesses = async () => {
      try {
        const driver = await DriverManager.getInstance().getDriver(connectionConfig, password, sshPassword);
        let sql = 'SHOW PROCESSLIST;';
        if (connectionConfig.type === 'PostgreSQL') {
          sql = 'SELECT pid as id, usename as user, datname as db, state, query_start, query FROM pg_stat_activity WHERE pid != pg_backend_pid();';
        }

        const result = await driver.executeQuery(sql);
        panel.webview.postMessage({ type: 'renderProcesses', result });
      } catch (err: any) {
        panel.webview.postMessage({ type: 'error', message: err.message });
      }
    };

    panel.webview.onDidReceiveMessage(async (msg) => {
      switch (msg.type) {
        case 'refresh':
          await loadProcesses();
          break;
        case 'killProcess':
          try {
            const driver = await DriverManager.getInstance().getDriver(connectionConfig, password, sshPassword);
            let killSql = `KILL ${msg.pid};`;
            if (connectionConfig.type === 'PostgreSQL') {
              killSql = `SELECT pg_terminate_backend(${msg.pid});`;
            }
            await driver.executeQuery(killSql);
            vscode.window.showInformationMessage(t(`Terminated process ${msg.pid}`, `Процесс ${msg.pid} успешно завершен`));
            await loadProcesses();
          } catch (e: any) {
            vscode.window.showErrorMessage(`Failed to kill process: ${e.message}`);
          }
          break;
      }
    });

    panel.webview.html = ProcessListWebviewProvider.getHtml(connectionConfig.name);
    await loadProcesses();
  }

  private static getHtml(connectionName: string): string {
    const ru = isRussian();
    const text = {
      title: ru ? '⚡ Мониторинг Активных Процессов' : '⚡ Active Server Process List',
      refresh: ru ? '🔄 Обновить' : '🔄 Refresh',
      kill: ru ? '❌ Завершить процесс' : '❌ Kill Process',
      time: ru ? 'Время' : 'Time',
      err: ru ? '❌ Ошибка:' : '❌ Error:',
    };

    return `<!DOCTYPE html>
<html lang="${ru ? 'ru' : 'en'}">
<head>
  <meta charset="UTF-8">
  <title>${text.title}</title>
  <style>
    body {
      font-family: var(--vscode-font-family, system-ui, sans-serif);
      color: var(--vscode-foreground);
      background-color: var(--vscode-editor-background);
      padding: 15px;
      margin: 0;
    }
    .header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 15px;
    }
    button {
      padding: 6px 12px;
      background: var(--vscode-button-background);
      color: var(--vscode-button-foreground);
      border: none;
      border-radius: 4px;
      cursor: pointer;
    }
    button.danger {
      background: #dc2626;
      color: white;
    }
    table {
      width: 100%;
      border-collapse: collapse;
      font-size: 13px;
    }
    th, td {
      padding: 8px 12px;
      border-bottom: 1px solid var(--vscode-panel-border, #333);
      text-align: left;
    }
    th {
      background: var(--vscode-editorHeader-noTabsBackground, #252526);
    }
    tr:hover {
      background: rgba(255,255,255,0.05);
    }
    #errorBox {
      display: none;
      background: #5a1d1d;
      color: #fca5a5;
      padding: 10px;
      border-radius: 4px;
      margin-bottom: 15px;
    }
  </style>
</head>
<body>
  <div class="header">
    <h3>${text.title} [${connectionName}]</h3>
    <button id="refreshBtn">${text.refresh}</button>
  </div>

  <div id="errorBox"></div>

  <table>
    <thead><tr id="tableHead"></tr></thead>
    <tbody id="tableBody"></tbody>
  </table>

  <script>
    const vscode = acquireVsCodeApi();

    document.getElementById('refreshBtn').onclick = () => {
      vscode.postMessage({ type: 'refresh' });
    };

    function killProcess(pid) {
      if (confirm('${text.kill} ID: ' + pid + '?')) {
        vscode.postMessage({ type: 'killProcess', pid });
      }
    }

    window.addEventListener('message', event => {
      const msg = event.data;
      const errorBox = document.getElementById('errorBox');

      if (msg.type === 'error') {
        errorBox.style.display = 'block';
        errorBox.innerText = '${text.err} ' + msg.message;
        return;
      }

      if (msg.type === 'renderProcesses') {
        errorBox.style.display = 'none';
        const res = msg.result;

        const headTr = document.getElementById('tableHead');
        headTr.innerHTML = res.fields.map(f => \`<th>\${f.name}</th>\`).join('') + '<th>Action</th>';

        const body = document.getElementById('tableBody');
        body.innerHTML = res.rows.map(row => {
          const pid = row.Id || row.id || row.PID || row.pid;
          const cells = res.fields.map(f => \`<td>\${row[f.name] === null ? '<i>null</i>' : String(row[f.name])}</td>\`).join('');
          const killBtn = pid ? \`<button class="danger" onclick="killProcess(\${pid})">Kill</button>\` : '';
          return \`<tr>\${cells}<td>\${killBtn}</td></tr>\`;
        }).join('');
      }
    });
  </script>
</body>
</html>`;
  }
}

