          }).join('');
          return \`<tr><td>\${(currentPage - 1) * pageSize + idx + 1}</td>\${cells}<td><button class="danger" onclick="deleteRow('\${pkField ? pkField.name : ''}', '\${pkVal}')">🗑️</button></td></tr>\`;
        }).join('');
      }
    });
