import * as vscode from 'vscode';
import { ConnectionStorageService } from './storage/ConnectionStorage.js';
import { QueryHistoryStorage } from './storage/QueryHistoryStorage.js';
import { DatabaseTreeProvider } from './tree/DatabaseTreeProvider.js';
import { ConnectionNode } from './tree/ConnectionNode.js';
import { TableNode } from './tree/TableNode.js';
import { ColumnNode } from './tree/ColumnNode.js';
import { DatabaseNode } from './tree/DatabaseNode.js';
import { ConnectWebviewProvider } from './webview/ConnectWebviewProvider.js';
import { TableWebviewProvider } from './webview/TableWebviewProvider.js';
import { TableDesignWebviewProvider } from './webview/TableDesignWebviewProvider.js';
import { ProcessListWebviewProvider } from './webview/ProcessListWebviewProvider.js';
import { ErdWebviewProvider } from './webview/ErdWebviewProvider.js';
import { DatabaseDumpService } from './dump/DatabaseDumpService.js';
import { MockDataGenerator } from './mock/MockDataGenerator.js';
import { SqlCompletionProvider } from './provider/SqlCompletionProvider.js';
import { DriverManager } from './drivers/DriverManager.js';
import { IconHelper } from './util/IconHelper.js';
import { t } from './util/i18n.js';

export function activate(context: vscode.ExtensionContext) {
  console.log('Anarchy Database Client extension activated!');

  // Initialize IconHelper with extension path for SVG icon resolution
  IconHelper.setExtensionPath(context.extensionPath);

  const storageService = new ConnectionStorageService(context);
  const historyStorage = new QueryHistoryStorage(context);
  const treeProvider = new DatabaseTreeProvider(storageService);

  // Register Tree View
  vscode.window.registerTreeDataProvider('database-client-explorer', treeProvider);

  // Register Commands
  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.addConnection', () => {
      ConnectWebviewProvider.show(context, storageService, () => treeProvider.refresh());
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.editConnection', async (node: ConnectionNode) => {
      if (node && node.config) {
        const pass = await storageService.getPassword(node.config.id);
        const sshPass = await storageService.getSshPassword(node.config.id);
        ConnectWebviewProvider.show(
          context,
          storageService,
          () => treeProvider.refresh(),
          node.config,
          pass,
          sshPass
        );
      }
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.refreshTree', () => {
      treeProvider.refresh();
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.deleteConnection', async (node: ConnectionNode) => {
      if (node && node.config) {
        const title = t(
          `Are you sure you want to delete connection "${node.config.name}"?`,
          `Вы уверены, что хотите удалить подключение "${node.config.name}"?`
        );
        const btnLabel = t('Delete', 'Удалить');
        const confirm = await vscode.window.showWarningMessage(title, { modal: true }, btnLabel);

        if (confirm === btnLabel) {
          await storageService.deleteConnection(node.config.id);
          await DriverManager.getInstance().removeDriver(node.config.id);
          treeProvider.refresh();
          vscode.window.showInformationMessage(
            t(`Deleted connection "${node.config.name}"`, `Удалено подключение "${node.config.name}"`)
          );
        }
      }
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.openTable', (node: TableNode) => {
      if (node && node instanceof TableNode) {
        TableWebviewProvider.openTable(node);
      }
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.designTable', (node: TableNode) => {
      if (node && node instanceof TableNode) {
        TableDesignWebviewProvider.show(node);
      }
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.copyTableName', (node: TableNode) => {
      if (node && node.table) {
        vscode.env.clipboard.writeText(node.table.name);
        vscode.window.showInformationMessage(
          t(`Copied table name "${node.table.name}"`, `Имя таблицы "${node.table.name}" скопировано`)
        );
      }
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.copyColumnName', (node: ColumnNode) => {
      if (node && node.column) {
        vscode.env.clipboard.writeText(node.column.name);
        vscode.window.showInformationMessage(
          t(`Copied column name "${node.column.name}"`, `Имя колонки "${node.column.name}" скопировано`)
        );
      }
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.showTableDdl', async (node: TableNode) => {
      if (node && node.table) {
        try {
          const driver = await DriverManager.getInstance().getDriver(node.connectionConfig, node.password, node.sshPassword);
          const columns = await driver.getColumns(node.table.name, node.connectionConfig.database, node.table.schema);

          let ddl = `-- DDL for table ${node.table.name}\nCREATE TABLE "${node.table.name}" (\n`;
          const colDefs = columns.map(
            (c) => `  "${c.name}" ${c.type}${c.isPrimaryKey ? ' PRIMARY KEY' : ''}${c.nullable ? '' : ' NOT NULL'}${c.defaultValue ? ` DEFAULT ${c.defaultValue}` : ''}`
          );
          ddl += colDefs.join(',\n');
          ddl += '\n);';

          const doc = await vscode.workspace.openTextDocument({ language: 'sql', content: ddl });
          await vscode.window.showTextDocument(doc);
        } catch (e: any) {
          vscode.window.showErrorMessage(`Failed to generate DDL: ${e.message}`);
        }
      }
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.dumpDatabase', async (node: ConnectionNode | DatabaseNode) => {
      if (node) {
        const config = node.connectionConfig || (node as ConnectionNode).config;
        const pass = (node as ConnectionNode).password;
        const sshPass = (node as ConnectionNode).sshPassword;
        await DatabaseDumpService.dumpDatabase(config, pass, sshPass);
      }
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.importSql', async (node: ConnectionNode | DatabaseNode) => {
      if (node) {
        const config = node.connectionConfig || (node as ConnectionNode).config;
        const pass = (node as ConnectionNode).password;
        const sshPass = (node as ConnectionNode).sshPassword;
        await DatabaseDumpService.importSqlFile(config, pass, sshPass);
      }
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.openErd', async (node: DatabaseNode) => {
      if (node) {
        await ErdWebviewProvider.show(node.connectionConfig, node.password, node.sshPassword);
      }
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.processList', async (node: ConnectionNode) => {
      if (node) {
        await ProcessListWebviewProvider.show(node.config, node.password, node.sshPassword);
      }
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.generateMockData', async (node: TableNode) => {
      if (node && node instanceof TableNode) {
        await MockDataGenerator.generateForTable(node);
      }
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.newQuery', async (node?: ConnectionNode | DatabaseNode) => {
      if (node) {
        const config = node.connectionConfig || (node as ConnectionNode).config;
        const pass = (node as ConnectionNode).password;
        TableWebviewProvider.openQueryConsole(config, pass);
      } else {
        const sqlComment = t('-- Enter your SQL query below\nSELECT 1;', '-- Введите ваш SQL-запрос ниже\nSELECT 1;');
        const doc = await vscode.workspace.openTextDocument({ language: 'sql', content: sqlComment });
        await vscode.window.showTextDocument(doc);
      }
    })
  );

  // Register SQL IntelliSense
  context.subscriptions.push(
    vscode.languages.registerCompletionItemProvider(
      { language: 'sql' },
      new SqlCompletionProvider(),
      ' ', '.'
    )
  );
}

export function deactivate() {
  DriverManager.getInstance().disconnectAll();
}

import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { ColumnInfo, QueryResult, TableInfo, PageParams } from '../model/QueryTypes.js';

export interface ForeignKeyInfo {
  columnName: string;
  foreignTableName: string;
  foreignColumnName: string;
}

export abstract class BaseDriver {
  protected config: ConnectionConfig;
  protected password?: string;
  protected isConnected: boolean = false;

  constructor(config: ConnectionConfig, password?: string) {
    this.config = config;
    this.password = password;
  }

  abstract connect(): Promise<void>;
  abstract disconnect(): Promise<void>;
  abstract testConnection(): Promise<{ success: boolean; message?: string }>;

  abstract getDatabases(): Promise<string[]>;
  async getSchemas(databaseName?: string): Promise<string[]> {
    return ['public'];
  }
  abstract getTables(databaseName?: string, schemaName?: string): Promise<TableInfo[]>;
  abstract getColumns(tableName: string, databaseName?: string, schemaName?: string): Promise<ColumnInfo[]>;

  async getForeignKeys(tableName: string, databaseName?: string, schemaName?: string): Promise<ForeignKeyInfo[]> {
    return [];
  }

  abstract executeQuery(sql: string): Promise<QueryResult>;
  abstract getTableData(tableName: string, params: PageParams, schemaName?: string): Promise<QueryResult>;

  public getIsConnected(): boolean {
    return this.isConnected;
  }
}

import { Client } from 'pg';
import { BaseDriver, ForeignKeyInfo } from './BaseDriver.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { ColumnInfo, PageParams, QueryResult, TableInfo } from '../model/QueryTypes.js';

export class PostgresDriver extends BaseDriver {
  private client: Client | null = null;

  constructor(config: ConnectionConfig, password?: string) {
    super(config, password);
  }

  private createClient(databaseName?: string): Client {
    return new Client({
      host: this.config.host || 'localhost',
      port: this.config.port || 5432,
      user: this.config.user || 'postgres',
      password: this.password || '',
      database: databaseName || this.config.database || 'postgres',
      ssl: this.config.ssl ? { rejectUnauthorized: false } : undefined,
      connectionTimeoutMillis: 5000,
    });
  }

  async connect(): Promise<void> {
    if (this.client) {
      await this.disconnect();
    }
    this.client = this.createClient();
    await this.client.connect();
    this.isConnected = true;
  }

  async disconnect(): Promise<void> {
    if (this.client) {
      try {
        await this.client.end();
      } catch (e) {
        // Ignore disconnect errors
      }
      this.client = null;
      this.isConnected = false;
    }
  }

  async testConnection(): Promise<{ success: boolean; message?: string }> {
    const tempClient = this.createClient();
    try {
      await tempClient.connect();
      await tempClient.query('SELECT 1');
      await tempClient.end();
      return { success: true, message: 'Successfully connected to PostgreSQL database!' };
    } catch (err: any) {
      return { success: false, message: err.message || 'Connection failed' };
    }
  }

  async getDatabases(): Promise<string[]> {
    const res = await this.executeQuery(
      "SELECT datname FROM pg_database WHERE datistemplate = false ORDER BY datname ASC;"
    );
    return res.rows.map((r) => r.datname);
  }

  async getSchemas(databaseName?: string): Promise<string[]> {
    const res = await this.executeQuery(
      "SELECT schema_name FROM information_schema.schemata WHERE schema_name NOT IN ('information_schema', 'pg_catalog', 'pg_toast') ORDER BY schema_name ASC;"
    );
    const schemas = res.rows.map((r) => r.schema_name);
    return schemas.length > 0 ? schemas : ['public'];
  }

  async getTables(databaseName?: string, schemaName?: string): Promise<TableInfo[]> {
    let whereClause = "table_schema NOT IN ('information_schema', 'pg_catalog', 'pg_toast')";
    if (schemaName) {
      whereClause = `table_schema = '${schemaName}'`;
    }

    const sql = `
      SELECT table_schema, table_name, table_type
      FROM information_schema.tables
      WHERE ${whereClause}
      ORDER BY table_name ASC;
    `;
    const res = await this.executeQuery(sql);
    return res.rows.map((r) => ({
      name: r.table_name,
      schema: r.table_schema || schemaName || 'public',
      type: r.table_type === 'VIEW' ? 'view' : 'table',
    }));
  }

  async getColumns(tableName: string, databaseName?: string, schemaName: string = 'public'): Promise<ColumnInfo[]> {
    const sql = `
      SELECT 
        c.column_name, 
        c.data_type, 
        c.is_nullable, 
        c.column_default,
        COALESCE(tc.constraint_type, '') as constraint_type
      FROM information_schema.columns c
      LEFT JOIN (
        SELECT kcu.table_schema, kcu.table_name, kcu.column_name, tc.constraint_type
        FROM information_schema.key_column_usage kcu
        JOIN information_schema.table_constraints tc
          ON kcu.table_schema = tc.table_schema 
          AND kcu.table_name = tc.table_name 
          AND kcu.constraint_name = tc.constraint_name 
          AND tc.constraint_type = 'PRIMARY KEY'
      ) tc
        ON c.table_schema = tc.table_schema 
        AND c.table_name = tc.table_name 
        AND c.column_name = tc.column_name
      WHERE c.table_schema = '${schemaName}' AND c.table_name = '${tableName}'
      ORDER BY c.ordinal_position ASC;
    `;
    const res = await this.executeQuery(sql);
    return res.rows.map((r) => ({
      name: r.column_name,
      type: r.data_type,
      nullable: r.is_nullable === 'YES',
      isPrimaryKey: r.constraint_type === 'PRIMARY KEY',
      defaultValue: r.column_default,
    }));
  }

  async getForeignKeys(tableName: string, databaseName?: string, schemaName: string = 'public'): Promise<ForeignKeyInfo[]> {
    const sql = `
      SELECT
        kcu.column_name,
        ccu.table_name AS foreign_table_name,
        ccu.column_name AS foreign_column_name
      FROM information_schema.table_constraints AS tc
      JOIN information_schema.key_column_usage AS kcu
        ON tc.constraint_name = kcu.constraint_name AND tc.table_schema = kcu.table_schema
      JOIN information_schema.constraint_column_usage AS ccu
        ON ccu.constraint_name = tc.constraint_name AND ccu.table_schema = tc.table_schema
      WHERE tc.constraint_type = 'FOREIGN KEY' AND tc.table_schema = '${schemaName}' AND tc.table_name = '${tableName}';
    `;
    try {
      const res = await this.executeQuery(sql);
      return res.rows.map((r) => ({
        columnName: r.column_name,
        foreignTableName: r.foreign_table_name,
        foreignColumnName: r.foreign_column_name,
      }));
    } catch (e) {
      return [];
    }
  }

  async executeQuery(sql: string): Promise<QueryResult> {
    if (!this.client) {
      await this.connect();
    }
    const startTime = Date.now();
    const res = await this.client!.query(sql);
    const costTimeMs = Date.now() - startTime;

    const fields: ColumnInfo[] = (res.fields || []).map((f) => ({
      name: f.name,
      type: 'unknown',
      nullable: true,
    }));

    return {
      rows: res.rows || [],
      fields,
      affectedRows: res.rowCount || 0,
      costTimeMs,
    };
  }

  async getTableData(tableName: string, params: PageParams, schemaName: string = 'public'): Promise<QueryResult> {
    const offset = (params.page - 1) * params.pageSize;
    let sql = `SELECT * FROM "${schemaName}"."${tableName}"`;

    if (params.filterSql) {
      sql += ` WHERE ${params.filterSql}`;
    }

    if (params.sortField && params.sortOrder) {
      sql += ` ORDER BY "${params.sortField}" ${params.sortOrder}`;
    }

    sql += ` LIMIT ${params.pageSize} OFFSET ${offset};`;

    const countSql = `SELECT COUNT(*) as total FROM "${schemaName}"."${tableName}"`;
    const countRes = await this.executeQuery(countSql);
    const totalCount = parseInt(countRes.rows[0]?.total || '0', 10);

    const queryResult = await this.executeQuery(sql);
    queryResult.totalCount = totalCount;
    return queryResult;
  }
}

import mysql from 'mysql2/promise';
import { BaseDriver, ForeignKeyInfo } from './BaseDriver.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { ColumnInfo, PageParams, QueryResult, TableInfo } from '../model/QueryTypes.js';

export class MysqlDriver extends BaseDriver {
  private connection: mysql.Connection | null = null;

  constructor(config: ConnectionConfig, password?: string) {
    super(config, password);
  }

  async connect(): Promise<void> {
    if (this.connection) {
      await this.disconnect();
    }
    this.connection = await mysql.createConnection({
      host: this.config.host || 'localhost',
      port: this.config.port || 3306,
      user: this.config.user || 'root',
      password: this.password || '',
      database: this.config.database || undefined,
      ssl: this.config.ssl ? { rejectUnauthorized: false } : undefined,
      connectTimeout: 5000,
    });
    this.isConnected = true;
  }

  async disconnect(): Promise<void> {
    if (this.connection) {
      try {
        await this.connection.end();
      } catch (e) {
        // Ignore disconnect errors
      }
      this.connection = null;
      this.isConnected = false;
    }
  }

  async testConnection(): Promise<{ success: boolean; message?: string }> {
    try {
      const conn = await mysql.createConnection({
        host: this.config.host || 'localhost',
        port: this.config.port || 3306,
        user: this.config.user || 'root',
        password: this.password || '',
        database: this.config.database || undefined,
        ssl: this.config.ssl ? { rejectUnauthorized: false } : undefined,
        connectTimeout: 5000,
      });
      await conn.query('SELECT 1');
      await conn.end();
      return { success: true, message: 'Successfully connected to MySQL database!' };
    } catch (err: any) {
      return { success: false, message: err.message || 'Connection failed' };
    }
  }

  async getDatabases(): Promise<string[]> {
    const res = await this.executeQuery("SHOW DATABASES WHERE `Database` NOT IN ('information_schema', 'performance_schema', 'mysql', 'sys');");
    return res.rows.map((r) => r.Database);
  }

  async getTables(databaseName?: string): Promise<TableInfo[]> {
    if (databaseName) {
      await this.executeQuery(`USE \`${databaseName}\`;`);
    }
    const res = await this.executeQuery('SHOW FULL TABLES;');
    return res.rows.map((r) => {
      const keys = Object.keys(r);
      const tableName = r[keys[0]];
      const tableType = r[keys[1]];
      return {
        name: tableName,
        type: tableType === 'VIEW' ? 'view' : 'table',
      };
    });
  }

  async getColumns(tableName: string, databaseName?: string): Promise<ColumnInfo[]> {
    if (databaseName) {
      await this.executeQuery(`USE \`${databaseName}\`;`);
    }
    const res = await this.executeQuery(`DESCRIBE \`${tableName}\`;`);
    return res.rows.map((r) => ({
      name: r.Field,
      type: r.Type,
      nullable: r.Null === 'YES',
      isPrimaryKey: r.Key === 'PRI',
      defaultValue: r.Default,
    }));
  }

  async getForeignKeys(tableName: string, databaseName?: string): Promise<ForeignKeyInfo[]> {
    const db = databaseName || this.config.database;
    if (!db) return [];
    const sql = `
      SELECT 
        column_name, 
        referenced_table_name AS foreign_table_name, 
        referenced_column_name AS foreign_column_name
      FROM information_schema.key_column_usage
      WHERE table_schema = '${db}' AND table_name = '${tableName}' AND referenced_table_name IS NOT NULL;
    `;
    try {
      const res = await this.executeQuery(sql);
      return res.rows.map((r) => ({
        columnName: r.column_name,
        foreignTableName: r.foreign_table_name,
        foreignColumnName: r.foreign_column_name,
      }));
    } catch (e) {
      return [];
    }
  }

  async executeQuery(sql: string): Promise<QueryResult> {
    if (!this.connection) {
      await this.connect();
    }
    const startTime = Date.now();
    const [rows, fields] = await this.connection!.query(sql);
    const costTimeMs = Date.now() - startTime;

    const columnFields: ColumnInfo[] = (fields || []).map((f) => ({
      name: f.name,
      type: 'unknown',
      nullable: true,
    }));

    const resultRows = Array.isArray(rows) ? rows : [];
    const affected = (rows as mysql.ResultSetHeader).affectedRows || 0;

    return {
      rows: resultRows,
      fields: columnFields,
      affectedRows: affected,
      costTimeMs,
    };
  }

  async getTableData(tableName: string, params: PageParams, schemaName?: string): Promise<QueryResult> {
    const offset = (params.page - 1) * params.pageSize;
    let sql = `SELECT * FROM \`${tableName}\``;

    if (params.filterSql) {
      sql += ` WHERE ${params.filterSql}`;
    }

    if (params.sortField && params.sortOrder) {
      sql += ` ORDER BY \`${params.sortField}\` ${params.sortOrder}`;
    }

    sql += ` LIMIT ${params.pageSize} OFFSET ${offset};`;

    const countSql = `SELECT COUNT(*) as total FROM \`${tableName}\``;
    const countRes = await this.executeQuery(countSql);
    const totalCount = parseInt(countRes.rows[0]?.total || '0', 10);

    const queryResult = await this.executeQuery(sql);
    queryResult.totalCount = totalCount;
    return queryResult;
  }
}

import * as vscode from 'vscode';
import { DriverManager } from '../drivers/DriverManager.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { isRussian, t } from '../util/i18n.js';

export class ErdWebviewProvider {
  public static async show(connectionConfig: ConnectionConfig, password?: string, sshPassword?: string) {
    const title = t(`ER Diagram: ${connectionConfig.database || connectionConfig.name}`, `ER-Диаграмма: ${connectionConfig.database || connectionConfig.name}`);
    const panel = vscode.window.createWebviewPanel(
      'dbClientErd',
      title,
      vscode.ViewColumn.One,
      {
        enableScripts: true,
        retainContextWhenHidden: true,
      }
    );

    try {
      const driver = await DriverManager.getInstance().getDriver(connectionConfig, password, sshPassword);
      const tables = await driver.getTables(connectionConfig.database);

      const tableDataList = [];
      const allRelations = [];

      for (const tbl of tables.slice(0, 30)) {
        const columns = await driver.getColumns(tbl.name, connectionConfig.database, tbl.schema);
        const fks = await driver.getForeignKeys(tbl.name, connectionConfig.database, tbl.schema);

        tableDataList.push({ name: tbl.name, schema: tbl.schema, columns, foreignKeys: fks });

        for (const fk of fks) {
          allRelations.push({
            fromTable: tbl.name,
            fromCol: fk.columnName,
            toTable: fk.foreignTableName,
            toCol: fk.foreignColumnName,
          });
        }
      }

      panel.webview.onDidReceiveMessage((msg) => {
        if (msg.type === 'copyMermaid') {
          vscode.env.clipboard.writeText(msg.mermaidCode);
          vscode.window.showInformationMessage(t('Copied Mermaid ER diagram code to clipboard!', 'Код Mermaid ER-диаграммы скопирован!'));
        }
      });

      panel.webview.html = ErdWebviewProvider.getHtml(connectionConfig.database || connectionConfig.name, tableDataList, allRelations);
    } catch (err: any) {
      vscode.window.showErrorMessage(`Failed to build ER Diagram: ${err.message}`);
    }
  }

  private static getHtml(databaseName: string, tables: any[], relations: any[]): string {
    const ru = isRussian();
    const tablesJson = JSON.stringify(tables);
    const relationsJson = JSON.stringify(relations);

    // Build Mermaid syntax
    let mermaidCode = 'erDiagram\n';
    tables.forEach((t) => {
      mermaidCode += `    "${t.name}" {\n`;
      t.columns.forEach((c: any) => {
        const keyType = c.isPrimaryKey ? 'PK' : t.foreignKeys.some((f: any) => f.columnName === c.name) ? 'FK' : '';
        mermaidCode += `        ${c.type || 'string'} ${c.name} ${keyType}\n`;
      });
      mermaidCode += `    }\n`;
    });
    relations.forEach((r) => {
      mermaidCode += `    "${r.toTable}" ||--o{ "${r.fromTable}" : "${r.fromCol}"\n`;
    });

    const mermaidCodeJson = JSON.stringify(mermaidCode);

    return `<!DOCTYPE html>
<html lang="${ru ? 'ru' : 'en'}">
<head>
  <meta charset="UTF-8">
  <title>${ru ? 'ER-Диаграмма' : 'ER Diagram'}: ${databaseName}</title>
  <style>
    body {
      font-family: var(--vscode-font-family, system-ui, sans-serif);
      color: var(--vscode-foreground);
      background-color: var(--vscode-editor-background);
      margin: 0;
      padding: 20px;
      overflow: auto;
    }
    .header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 20px;
    }
    button {
      padding: 8px 14px;
      background: var(--vscode-button-background);
      color: var(--vscode-button-foreground);
      border: none;
      border-radius: 4px;
      cursor: pointer;
      font-weight: bold;
    }
    .diagram-grid {
      display: flex;
      flex-wrap: wrap;
      gap: 25px;
    }
    .erd-table {
      background: var(--vscode-sideBar-background, #252526);
      border: 1px solid var(--vscode-panel-border, #444);
      border-radius: 6px;
      width: 280px;
      box-shadow: 0 4px 6px rgba(0,0,0,0.3);
    }
    .table-header {
      background: var(--vscode-editorHeader-noTabsBackground, #1e1e1e);
      padding: 10px 12px;
      font-weight: bold;
      border-bottom: 1px solid var(--vscode-panel-border, #444);
      border-top-left-radius: 5px;
      border-top-right-radius: 5px;
      color: #61afef;
    }
    .column-row {
      display: flex;
      justify-content: space-between;
      padding: 6px 12px;
      font-size: 12px;
      border-bottom: 1px solid rgba(255,255,255,0.05);
    }
    .pk { font-weight: bold; color: #facc15; }
    .fk { font-weight: bold; color: #c084fc; }
    .type { color: #98c379; font-size: 11px; }
    .rel-badge {
      font-size: 11px;
      background: #312e81;
      color: #a5b4fc;
      padding: 4px 8px;
      border-radius: 4px;
      margin-top: 5px;
    }
  </style>
</head>
<body>
  <div class="header">
    <h2>📊 ${ru ? 'Схема Связей (ER Diagram)' : 'Entity-Relationship Diagram'}: ${databaseName}</h2>
    <button id="copyMermaidBtn">📋 ${ru ? 'Копировать Mermaid Код' : 'Copy Mermaid Code'}</button>
  </div>

  <div class="diagram-grid" id="grid"></div>

  <script>
    const vscode = acquireVsCodeApi();
    const tables = ${tablesJson};
    const relations = ${relationsJson};
    const mermaidCode = ${mermaidCodeJson};

    document.getElementById('copyMermaidBtn').onclick = () => {
      vscode.postMessage({ type: 'copyMermaid', mermaidCode });
    };

    const grid = document.getElementById('grid');

    tables.forEach(tbl => {
      const tableDiv = document.createElement('div');
      tableDiv.className = 'erd-table';

      let rowsHtml = tbl.columns.map(col => {
        const isPk = col.isPrimaryKey;
        const isFk = tbl.foreignKeys.some(f => f.columnName === col.name);
        const cls = isPk ? 'pk' : isFk ? 'fk' : '';
        const badge = isPk ? ' 🔑 PK' : isFk ? ' 🔗 FK' : '';
        return \`<div class="column-row \${cls}">
          <span>\${col.name}\${badge}</span>
          <span class="type">\${col.type}</span>
        </div>\`;
      }).join('');

      let relsHtml = tbl.foreignKeys.map(fk => \`
        <div class="rel-badge">🔗 \${fk.columnName} ➔ \${fk.foreignTableName}.\${fk.foreignColumnName}</div>
      \`).join('');

      tableDiv.innerHTML = \`<div class="table-header">📁 \${tbl.name}</div><div class="table-body">\${rowsHtml}</div>\${relsHtml ? '<div style="padding:8px;">' + relsHtml + '</div>' : ''}\`;
      grid.appendChild(tableDiv);
    });
  </script>
</body>
</html>`;
  }
}

import * as vscode from 'vscode';
import { DriverManager } from '../drivers/DriverManager.js';
import { TableNode } from '../tree/TableNode.js';
import { isRussian, t } from '../util/i18n.js';

export class TableDesignWebviewProvider {
  public static async show(tableNode: TableNode) {
    const title = t(`Design: ${tableNode.table.name}`, `Конструктор: ${tableNode.table.name}`);
    const panel = vscode.window.createWebviewPanel(
      'dbClientTableDesign',
      title,
      vscode.ViewColumn.One,
      {
        enableScripts: true,
        retainContextWhenHidden: true,
      }
    );

    const connectionConfig = tableNode.connectionConfig;
    const tableName = tableNode.table.name;
    const schemaName = tableNode.table.schema || 'public';

    const loadColumns = async () => {
      try {
        const driver = await DriverManager.getInstance().getDriver(connectionConfig, tableNode.password, tableNode.sshPassword);
        const columns = await driver.getColumns(tableName, connectionConfig.database, schemaName);
        panel.webview.postMessage({ type: 'renderColumns', columns });
      } catch (err: any) {
        panel.webview.postMessage({ type: 'error', message: err.message });
      }
    };

    panel.webview.onDidReceiveMessage(async (msg) => {
      switch (msg.type) {
        case 'addColumn': {
          try {
            const driver = await DriverManager.getInstance().getDriver(connectionConfig, tableNode.password, tableNode.sshPassword);
            const sql = `ALTER TABLE "${tableName}" ADD COLUMN "${msg.col.name}" ${msg.col.type}${msg.col.nullable ? '' : ' NOT NULL'};`;
            await driver.executeQuery(sql);
            vscode.window.showInformationMessage(t(`Added column "${msg.col.name}"`, `Колонка "${msg.col.name}" добавлена`));
            await loadColumns();
          } catch (e: any) {
            vscode.window.showErrorMessage(`Failed to add column: ${e.message}`);
          }
          break;
        }
        case 'editColumn': {
          try {
            const driver = await DriverManager.getInstance().getDriver(connectionConfig, tableNode.password, tableNode.sshPassword);
            let alterSql = '';
            if (connectionConfig.type === 'PostgreSQL') {
              alterSql = `ALTER TABLE "${tableName}" RENAME COLUMN "${msg.oldName}" TO "${msg.newName}";\nALTER TABLE "${tableName}" ALTER COLUMN "${msg.newName}" TYPE ${msg.newType};`;
            } else {
              alterSql = `ALTER TABLE \`${tableName}\` CHANGE \`${msg.oldName}\` \`${msg.newName}\` ${msg.newType};`;
            }
            await driver.executeQuery(alterSql);
            vscode.window.showInformationMessage(t(`Updated column "${msg.newName}"`, `Колонка "${msg.newName}" обновлена`));
            await loadColumns();
          } catch (e: any) {
            vscode.window.showErrorMessage(`Failed to edit column: ${e.message}`);
          }
          break;
        }
        case 'dropColumn': {
          try {
            const driver = await DriverManager.getInstance().getDriver(connectionConfig, tableNode.password, tableNode.sshPassword);
            const sql = `ALTER TABLE "${tableName}" DROP COLUMN "${msg.columnName}";`;
            await driver.executeQuery(sql);
            vscode.window.showInformationMessage(t(`Dropped column "${msg.columnName}"`, `Колонка "${msg.columnName}" удалена`));
            await loadColumns();
          } catch (e: any) {
            vscode.window.showErrorMessage(`Failed to drop column: ${e.message}`);
          }
          break;
        }
      }
    });

    panel.webview.html = TableDesignWebviewProvider.getHtml(tableName);
    await loadColumns();
  }

  private static getHtml(tableName: string): string {
    const ru = isRussian();
    const text = {
      title: ru ? '🛠 Конструктор Таблицы (Редактирование Колонок)' : '🛠 Table Designer & Column Editor',
      addCol: ru ? '➕ Добавить Колонку' : '➕ Add Column',
      colName: ru ? 'Имя колонки' : 'Column Name',
      colType: ru ? 'Тип данных' : 'Data Type',
      nullable: ru ? 'NULLABLE' : 'NULLABLE',
      pk: ru ? 'PRIMARY KEY' : 'PRIMARY KEY',
      actions: ru ? 'Действия' : 'Actions',
      edit: ru ? '✏️ Изменить' : '✏️ Edit',
      drop: ru ? '🗑️ Удалить' : '🗑️ Drop',
    };

    return `<!DOCTYPE html>
<html lang="${ru ? 'ru' : 'en'}">
<head>
  <meta charset="UTF-8">
  <title>${text.title}</title>
  <style>
    body {
      font-family: var(--vscode-font-family, system-ui, sans-serif);
      color: var(--vscode-foreground);
      background-color: var(--vscode-editor-background);
      padding: 15px;
      margin: 0;
    }
    .toolbar {
      display: flex;
      gap: 10px;
      margin-bottom: 15px;
      background: var(--vscode-sideBar-background);
      padding: 10px;
      border-radius: 4px;
      align-items: center;
    }
    input, select, button {
      padding: 6px 10px;
      background: var(--vscode-input-background);
      color: var(--vscode-input-foreground);
      border: 1px solid var(--vscode-input-border, #444);
      border-radius: 4px;
    }
    button {
      cursor: pointer;
      background: var(--vscode-button-background);
      color: var(--vscode-button-foreground);
      border: none;
      font-weight: bold;
    }
    button.secondary {
      background: var(--vscode-button-secondaryBackground);
      color: var(--vscode-button-secondaryForeground);
    }
    button.danger {
      background: #dc2626;
      color: white;
    }
    table {
      width: 100%;
      border-collapse: collapse;
      font-size: 13px;
    }
    th, td {
      padding: 8px 12px;
      border-bottom: 1px solid var(--vscode-panel-border, #333);
      text-align: left;
    }
    th {
      background: var(--vscode-editorHeader-noTabsBackground, #252526);
    }
  </style>
</head>
<body>
  <h3>${text.title}: ${tableName}</h3>

  <div class="toolbar">
    <input type="text" id="newColName" placeholder="${text.colName}">
    <select id="newColType">
      <option value="VARCHAR(255)">VARCHAR(255)</option>
      <option value="TEXT">TEXT</option>
      <option value="INTEGER">INTEGER</option>
      <option value="BIGINT">BIGINT</option>
      <option value="BOOLEAN">BOOLEAN</option>
      <option value="TIMESTAMP">TIMESTAMP</option>
      <option value="JSON">JSON</option>
    </select>
    <label><input type="checkbox" id="newColNullable" checked> ${text.nullable}</label>
    <button id="addBtn">${text.addCol}</button>
  </div>

  <table>
    <thead>
      <tr>
        <th>${text.colName}</th>
        <th>${text.colType}</th>
        <th>${text.nullable}</th>
        <th>${text.pk}</th>
        <th>${text.actions}</th>
      </tr>
    </thead>
    <tbody id="colBody"></tbody>
  </table>

  <script>
    const vscode = acquireVsCodeApi();

    document.getElementById('addBtn').onclick = () => {
      const name = document.getElementById('newColName').value;
      const type = document.getElementById('newColType').value;
      const nullable = document.getElementById('newColNullable').checked;

      if (!name) return;
      vscode.postMessage({ type: 'addColumn', col: { name, type, nullable } });
    };

    function editCol(oldName, oldType) {
      const newName = prompt('Enter new column name:', oldName);
      if (!newName) return;
      const newType = prompt('Enter data type (e.g. VARCHAR(255), INT, TEXT):', oldType);
      if (!newType) return;

      vscode.postMessage({ type: 'editColumn', oldName, newName, newType });
    }

    function dropCol(colName) {
      if (confirm('Drop column "' + colName + '"?')) {
        vscode.postMessage({ type: 'dropColumn', columnName: colName });
      }
    }

    window.addEventListener('message', event => {
      const msg = event.data;
      if (msg.type === 'renderColumns') {
        const body = document.getElementById('colBody');
        body.innerHTML = msg.columns.map(c => \`
          <tr>
            <td><b>\${c.name}</b></td>
            <td>\${c.type}</td>
            <td>\${c.nullable ? 'YES' : 'NO'}</td>
            <td>\${c.isPrimaryKey ? '🔑 YES' : 'NO'}</td>
            <td>
              <button class="secondary" onclick="editCol('\${c.name}', '\${c.type}')">${text.edit}</button>
              <button class="danger" onclick="dropCol('\${c.name}')">${text.drop}</button>
            </td>
          </tr>
        \`).join('');
      }
    });
  </script>
</body>
</html>`;
  }
}

import * as vscode from 'vscode';
