import mysql from 'mysql2/promise';
import { BaseDriver, ForeignKeyInfo } from './BaseDriver.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { ColumnInfo, PageParams, QueryResult, TableInfo } from '../model/QueryTypes.js';

export class MysqlDriver extends BaseDriver {
  private connection: mysql.Connection | null = null;

  constructor(config: ConnectionConfig, password?: string) {
    super(config, password);
  }

  async connect(): Promise<void> {
    if (this.connection) {
      await this.disconnect();
    }
    this.connection = await mysql.createConnection({
      host: this.config.host || 'localhost',
      port: this.config.port || 3306,
      user: this.config.user || 'root',
      password: this.password || '',
      database: this.config.database || undefined,
      ssl: this.config.ssl ? { rejectUnauthorized: false } : undefined,
      connectTimeout: 5000,
    });
    this.isConnected = true;
  }

  async disconnect(): Promise<void> {
    if (this.connection) {
      try {
        await this.connection.end();
      } catch (e) {
        // Ignore disconnect errors
      }
      this.connection = null;
      this.isConnected = false;
    }
  }

  async testConnection(): Promise<{ success: boolean; message?: string }> {
    try {
      const conn = await mysql.createConnection({
        host: this.config.host || 'localhost',
        port: this.config.port || 3306,
        user: this.config.user || 'root',
        password: this.password || '',
        database: this.config.database || undefined,
        ssl: this.config.ssl ? { rejectUnauthorized: false } : undefined,
        connectTimeout: 5000,
      });
      await conn.query('SELECT 1');
      await conn.end();
      return { success: true, message: 'Successfully connected to MySQL database!' };
    } catch (err: any) {
      return { success: false, message: err.message || 'Connection failed' };
    }
  }

  async getDatabases(): Promise<string[]> {
    const res = await this.executeQuery("SHOW DATABASES WHERE `Database` NOT IN ('information_schema', 'performance_schema', 'mysql', 'sys');");
    return res.rows.map((r) => r.Database);
  }

  async getTables(databaseName?: string): Promise<TableInfo[]> {
    const db = databaseName || this.config.database;
    if (db) {
      await this.executeQuery(`USE \`${db}\`;`);
    }
    const res = await this.executeQuery('SHOW FULL TABLES;');
    return res.rows.map((r) => {
      const keys = Object.keys(r);
      const tableName = r[keys[0]];
      const tableType = r[keys[1]];
      return {
        name: tableName,
        type: tableType === 'VIEW' ? 'view' : 'table',
      };
    });
  }

  async getColumns(tableName: string, databaseName?: string): Promise<ColumnInfo[]> {
    const db = databaseName || this.config.database;
    if (db) {
      try {
        await this.executeQuery(`USE \`${db}\`;`);
        const sql = `
          SELECT 
            COLUMN_NAME, 
            COLUMN_TYPE, 
            IS_NULLABLE, 
            COLUMN_DEFAULT, 
            COLUMN_KEY, 
            COLUMN_COMMENT
          FROM information_schema.columns
          WHERE table_schema = '${db}' AND table_name = '${tableName}'
          ORDER BY ORDINAL_POSITION ASC;
        `;
        const res = await this.executeQuery(sql);
        if (res.rows && res.rows.length > 0) {
          return res.rows.map((r) => {
            const name = r.COLUMN_NAME ?? r.column_name ?? r.Field;
            const type = r.COLUMN_TYPE ?? r.column_type ?? r.Type;
            const nullable = (r.IS_NULLABLE ?? r.is_nullable ?? r.Null) === 'YES';
            const isPk = (r.COLUMN_KEY ?? r.column_key ?? r.Key) === 'PRI';
            const defVal = r.COLUMN_DEFAULT ?? r.column_default;
            const comment = r.COLUMN_COMMENT ?? r.column_comment ?? r.Comment;

            return {
              name: String(name),
              type: String(type),
              nullable,
              isPrimaryKey: isPk,
              defaultValue: defVal !== null && defVal !== undefined ? String(defVal) : undefined,
              comment: comment ? String(comment) : undefined,
            };
          });
        }
      } catch (e) {
        // Fallback to DESCRIBE
      }
    }

    const res = await this.executeQuery(`DESCRIBE \`${tableName}\`;`);
    return res.rows.map((r) => ({
      name: String(r.Field),
      type: String(r.Type),
      nullable: r.Null === 'YES',
      isPrimaryKey: r.Key === 'PRI',
      defaultValue: r.Default !== null && r.Default !== undefined ? String(r.Default) : undefined,
    }));
  }

  async getForeignKeys(tableName: string, databaseName?: string): Promise<ForeignKeyInfo[]> {
    const db = databaseName || this.config.database;
    if (!db) return [];
    const sql = `
      SELECT 
        COLUMN_NAME as column_name, 
        REFERENCED_TABLE_NAME AS foreign_table_name, 
        REFERENCED_COLUMN_NAME AS foreign_column_name
      FROM information_schema.key_column_usage
      WHERE table_schema = '${db}' AND table_name = '${tableName}' AND REFERENCED_TABLE_NAME IS NOT NULL;
    `;
    try {
      const res = await this.executeQuery(sql);
      return res.rows.map((r) => ({
        columnName: r.column_name || r.COLUMN_NAME,
        foreignTableName: r.foreign_table_name || r.REFERENCED_TABLE_NAME,
        foreignColumnName: r.foreign_column_name || r.REFERENCED_COLUMN_NAME,
      }));
    } catch (e) {
      return [];
    }
  }

  async executeQuery(sql: string): Promise<QueryResult> {
    if (!this.connection) {
      await this.connect();
    }
    if (this.config.database) {
      try {
        await this.connection!.query(`USE \`${this.config.database}\`;`);
      } catch (e) {
        // Ignore USE database errors
      }
    }
    const startTime = Date.now();
    const [rows, fields] = await this.connection!.query(sql);
    const costTimeMs = Date.now() - startTime;

    const columnFields: ColumnInfo[] = (fields || []).map((f) => ({
      name: f.name,
      type: 'unknown',
      nullable: true,
    }));

    const resultRows = Array.isArray(rows) ? rows : [];
    const affected = (rows as mysql.ResultSetHeader).affectedRows || 0;

    return {
      rows: resultRows,
      fields: columnFields,
      affectedRows: affected,
      costTimeMs,
    };
  }

  async getTableData(tableName: string, params: PageParams, schemaName?: string): Promise<QueryResult> {
    const offset = (params.page - 1) * params.pageSize;
    let sql = `SELECT * FROM \`${tableName}\``;

    if (params.filterSql) {
      sql += ` WHERE ${params.filterSql}`;
    }

    if (params.sortField && params.sortOrder) {
      sql += ` ORDER BY \`${params.sortField}\` ${params.sortOrder}`;
    }

    sql += ` LIMIT ${params.pageSize} OFFSET ${offset};`;

    const countSql = `SELECT COUNT(*) as total FROM \`${tableName}\``;
    const countRes = await this.executeQuery(countSql);
    const totalCount = parseInt(countRes.rows[0]?.total || countRes.rows[0]?.TOTAL || '0', 10);

    const queryResult = await this.executeQuery(sql);
    queryResult.totalCount = totalCount;
    return queryResult;
  }
}

import * as vscode from 'vscode';
import { DriverManager } from '../drivers/DriverManager.js';
import { TableNode } from '../tree/TableNode.js';
import { isRussian, t } from '../util/i18n.js';

export class TableDesignWebviewProvider {
  public static async show(tableNode: TableNode) {
    const title = t(`Design: ${tableNode.table.name}`, `Конструктор: ${tableNode.table.name}`);
    const panel = vscode.window.createWebviewPanel(
      'dbClientTableDesign',
      title,
      vscode.ViewColumn.One,
      {
        enableScripts: true,
        retainContextWhenHidden: true,
      }
    );

    const connectionConfig = tableNode.connectionConfig;
    const tableName = tableNode.table.name;
    const schemaName = tableNode.table.schema || 'public';

    const loadColumns = async () => {
      try {
        const driver = await DriverManager.getInstance().getDriver(connectionConfig, tableNode.password, tableNode.sshPassword);
        const db = connectionConfig.database;
        if (db && connectionConfig.type === 'MySQL') {
          await driver.executeQuery(`USE \`${db}\`;`);
        }
        const columns = await driver.getColumns(tableName, db, schemaName);
        panel.webview.postMessage({ type: 'renderColumns', columns });
      } catch (err: any) {
        panel.webview.postMessage({ type: 'error', message: err.message });
      }
    };

    panel.webview.onDidReceiveMessage(async (msg) => {
      switch (msg.type) {
        case 'setTableComment': {
          try {
            const driver = await DriverManager.getInstance().getDriver(connectionConfig, tableNode.password, tableNode.sshPassword);
            const db = connectionConfig.database;
            if (db && connectionConfig.type === 'MySQL') {
              await driver.executeQuery(`USE \`${db}\`;`);
            }
            let sql = '';
            if (connectionConfig.type === 'PostgreSQL') {
              sql = `COMMENT ON TABLE "${schemaName}"."${tableName}" IS '${(msg.comment || '').replace(/'/g, "''")}';`;
            } else {
              sql = `ALTER TABLE \`${tableName}\` COMMENT = '${(msg.comment || '').replace(/'/g, "''")}';`;
            }
            await driver.executeQuery(sql);
            vscode.window.showInformationMessage(t('Table comment updated!', 'Комментарий к таблице обновлен!'));
            await loadColumns();
          } catch (e: any) {
            vscode.window.showErrorMessage(`Failed to set table comment: ${e.message}`);
          }
          break;
        }
        case 'setColumnComment': {
          try {
            const driver = await DriverManager.getInstance().getDriver(connectionConfig, tableNode.password, tableNode.sshPassword);
            const db = connectionConfig.database;
            if (db && connectionConfig.type === 'MySQL') {
              await driver.executeQuery(`USE \`${db}\`;`);
            }
            let sql = '';
            if (connectionConfig.type === 'PostgreSQL') {
              sql = `COMMENT ON COLUMN "${schemaName}"."${tableName}"."${msg.columnName}" IS '${(msg.comment || '').replace(/'/g, "''")}';`;
            } else {
              const cols = await driver.getColumns(tableName, db, schemaName);
              const colInfo = cols.find((c) => c.name === msg.columnName);
              const colType = colInfo ? colInfo.type : msg.columnType;
              const nullSql = colInfo && !colInfo.nullable ? ' NOT NULL' : '';
              const defSql = colInfo && colInfo.defaultValue !== undefined && colInfo.defaultValue !== null ? ` DEFAULT '${colInfo.defaultValue}'` : '';
              sql = `ALTER TABLE \`${tableName}\` MODIFY COLUMN \`${msg.columnName}\` ${colType}${nullSql}${defSql} COMMENT '${(msg.comment || '').replace(/'/g, "''")}';`;
            }
            await driver.executeQuery(sql);
            vscode.window.showInformationMessage(t(`Comment for "${msg.columnName}" updated!`, `Комментарий для колонки "${msg.columnName}" обновлен!`));
            await loadColumns();
          } catch (e: any) {
            vscode.window.showErrorMessage(`Failed to set column comment: ${e.message}`);
          }
          break;
        }
        case 'addColumn': {
          try {
            const driver = await DriverManager.getInstance().getDriver(connectionConfig, tableNode.password, tableNode.sshPassword);
            const db = connectionConfig.database;
            if (db && connectionConfig.type === 'MySQL') {
              await driver.executeQuery(`USE \`${db}\`;`);
            }
            const sql = connectionConfig.type === 'MySQL'
              ? `ALTER TABLE \`${tableName}\` ADD COLUMN \`${msg.col.name}\` ${msg.col.type}${msg.col.nullable ? '' : ' NOT NULL'};`
              : `ALTER TABLE "${tableName}" ADD COLUMN "${msg.col.name}" ${msg.col.type}${msg.col.nullable ? '' : ' NOT NULL'};`;
            await driver.executeQuery(sql);
            vscode.window.showInformationMessage(t(`Added column "${msg.col.name}"`, `Колонка "${msg.col.name}" добавлена`));
            await loadColumns();
          } catch (e: any) {
            vscode.window.showErrorMessage(`Failed to add column: ${e.message}`);
          }
          break;
        }
        case 'editColumn': {
          try {
            const driver = await DriverManager.getInstance().getDriver(connectionConfig, tableNode.password, tableNode.sshPassword);
            const db = connectionConfig.database;
            if (db && connectionConfig.type === 'MySQL') {
              await driver.executeQuery(`USE \`${db}\`;`);
            }
            let alterSql = '';
            if (connectionConfig.type === 'PostgreSQL') {
              alterSql = `ALTER TABLE "${tableName}" RENAME COLUMN "${msg.oldName}" TO "${msg.newName}";\nALTER TABLE "${tableName}" ALTER COLUMN "${msg.newName}" TYPE ${msg.newType};`;
            } else {
              alterSql = `ALTER TABLE \`${tableName}\` CHANGE \`${msg.oldName}\` \`${msg.newName}\` ${msg.newType};`;
            }
            await driver.executeQuery(alterSql);
            vscode.window.showInformationMessage(t(`Updated column "${msg.newName}"`, `Колонка "${msg.newName}" обновлена`));
            await loadColumns();
          } catch (e: any) {
            vscode.window.showErrorMessage(`Failed to edit column: ${e.message}`);
          }
          break;
        }
        case 'dropColumn': {
          try {
            const driver = await DriverManager.getInstance().getDriver(connectionConfig, tableNode.password, tableNode.sshPassword);
            const db = connectionConfig.database;
            if (db && connectionConfig.type === 'MySQL') {
              await driver.executeQuery(`USE \`${db}\`;`);
            }
            const sql = connectionConfig.type === 'MySQL'
              ? `ALTER TABLE \`${tableName}\` DROP COLUMN \`${msg.columnName}\`;`
              : `ALTER TABLE "${tableName}" DROP COLUMN "${msg.columnName}";`;
            await driver.executeQuery(sql);
            vscode.window.showInformationMessage(t(`Dropped column "${msg.columnName}"`, `Колонка "${msg.columnName}" удалена`));
            await loadColumns();
          } catch (e: any) {
            vscode.window.showErrorMessage(`Failed to drop column: ${e.message}`);
          }
          break;
        }
      }
    });

    panel.webview.html = TableDesignWebviewProvider.getHtml(tableName);
    await loadColumns();
  }

  private static getHtml(tableName: string): string {
    const ru = isRussian();
    const text = {
      title: ru ? '🛠 Конструктор Таблицы и Комментариев' : '🛠 Table & Comment Designer',
      addCol: ru ? '➕ Добавить Колонку' : '➕ Add Column',
      colName: ru ? 'Имя колонки' : 'Column Name',
      colType: ru ? 'Тип данных' : 'Data Type',
      nullable: ru ? 'NULLABLE' : 'NULLABLE',
      pk: ru ? 'PRIMARY KEY' : 'PRIMARY KEY',
      comment: ru ? 'Комментарий' : 'Comment',
      actions: ru ? 'Действия' : 'Actions',
      edit: ru ? '✏️ Изменить' : '✏️ Edit',
      editComment: ru ? '💬 Комментарий' : '💬 Comment',
      tableCommentBtn: ru ? '💬 Комментарий К Таблице' : '💬 Table Comment',
      drop: ru ? '🗑️ Удалить' : '🗑️ Drop',
      save: ru ? 'Сохранить' : 'Save',
      cancel: ru ? 'Отмена' : 'Cancel',
    };

    return `<!DOCTYPE html>
<html lang="${ru ? 'ru' : 'en'}">
<head>
  <meta charset="UTF-8">
  <title>${text.title}</title>
  <style>
    body {
      font-family: var(--vscode-font-family, system-ui, sans-serif);
      color: var(--vscode-foreground);
      background-color: var(--vscode-editor-background);
      padding: 15px;
      margin: 0;
    }
    .toolbar {
      display: flex;
      gap: 10px;
      margin-bottom: 15px;
      background: var(--vscode-sideBar-background);
      padding: 10px;
      border-radius: 4px;
      align-items: center;
      flex-wrap: wrap;
    }
    input, select, button, textarea {
      padding: 6px 10px;
      background: var(--vscode-input-background);
      color: var(--vscode-input-foreground);
      border: 1px solid var(--vscode-input-border, #444);
      border-radius: 4px;
    }
    button {
      cursor: pointer;
      background: var(--vscode-button-background);
      color: var(--vscode-button-foreground);
      border: none;
      font-weight: bold;
    }
    button.secondary {
      background: var(--vscode-button-secondaryBackground);
