import { BaseDriver } from './BaseDriver.js';
import { PostgresDriver } from './PostgresDriver.js';
import { MysqlDriver } from './MysqlDriver.js';
import { SqliteDriver } from './SqliteDriver.js';
import { RedisDriver } from './RedisDriver.js';
import { MongoDriver } from './MongoDriver.js';
import { ElasticsearchDriver } from './ElasticsearchDriver.js';
import { ClickhouseDriver } from './ClickhouseDriver.js';
import { CouchdbDriver } from './CouchdbDriver.js';
import { CouchbaseDriver } from './CouchbaseDriver.js';
import { FirestoreDriver } from './FirestoreDriver.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { SshTunnelManager, SshTunnelResult } from '../ssh/SshTunnelManager.js';

export class DriverManager {
  private static instance: DriverManager;
  private activeDrivers: Map<string, BaseDriver> = new Map();
  private sshTunnels: Map<string, SshTunnelResult> = new Map();

  private constructor() {}

  public static getInstance(): DriverManager {
    if (!DriverManager.instance) {
      DriverManager.instance = new DriverManager();
    }
    return DriverManager.instance;
  }

  public async getDriver(config: ConnectionConfig, password?: string, sshPassword?: string): Promise<BaseDriver> {
    const driverKey = `${config.id}_${config.database || ''}`;
    let driver = this.activeDrivers.get(driverKey);

    if (!driver) {
      let finalConfig = { ...config };

      if (config.ssh && config.ssh.enabled) {
        let tunnel = this.sshTunnels.get(config.id);
        if (!tunnel) {
          tunnel = await SshTunnelManager.createTunnel(config, sshPassword);
          this.sshTunnels.set(config.id, tunnel);
        }
        finalConfig.host = '127.0.0.1';
        finalConfig.port = tunnel.localPort;
      }

      switch (config.type) {
        case 'PostgreSQL':
          driver = new PostgresDriver(finalConfig, password);
          break;
        case 'MySQL':
          driver = new MysqlDriver(finalConfig, password);
          break;
        case 'SQLite':
          driver = new SqliteDriver(finalConfig, password);
          break;
        case 'Redis':
          driver = new RedisDriver(finalConfig, password);
          break;
        case 'MongoDB':
          driver = new MongoDriver(finalConfig, password);
          break;
        case 'Elasticsearch':
          driver = new ElasticsearchDriver(finalConfig, password);
          break;
        case 'ClickHouse':
          driver = new ClickhouseDriver(finalConfig, password);
          break;
        case 'CouchDB':
          driver = new CouchdbDriver(finalConfig, password);
          break;
        case 'Couchbase':
          driver = new CouchbaseDriver(finalConfig, password);
          break;
        case 'Firestore':
          driver = new FirestoreDriver(finalConfig, password);
          break;
        default:
          throw new Error(`Unsupported database type: ${config.type}`);
      }

      await driver.connect();
      this.activeDrivers.set(driverKey, driver);
    }

    return driver;
  }

  public async removeDriver(configId: string): Promise<void> {
    for (const [key, driver] of this.activeDrivers.entries()) {
      if (key.startsWith(`${configId}_`)) {
        await driver.disconnect();
        this.activeDrivers.delete(key);
      }
    }

    const tunnel = this.sshTunnels.get(configId);
    if (tunnel) {
      await SshTunnelManager.closeTunnel(tunnel);
      this.sshTunnels.delete(configId);
    }
  }

  public async disconnectAll(): Promise<void> {
    for (const driver of this.activeDrivers.values()) {
      await driver.disconnect();
    }
    this.activeDrivers.clear();

    for (const tunnel of this.sshTunnels.values()) {
      await SshTunnelManager.closeTunnel(tunnel);
    }
    this.sshTunnels.clear();
  }
}

import * as path from 'path';
import * as vscode from 'vscode';
import { DatabaseType } from '../model/ConnectionConfig.js';

export class IconHelper {
  private static extensionPath: string = '';

  public static setExtensionPath(extPath: string) {
    IconHelper.extensionPath = extPath;
  }

  private static getResourcePath(relativePath: string): vscode.Uri {
    const basePath = IconHelper.extensionPath || path.join(__dirname, '..');
    return vscode.Uri.file(path.join(basePath, 'resources', relativePath));
  }

  public static getConnectionIcon(type: DatabaseType, isConnected: boolean = false): vscode.Uri {
    let iconName = 'database.svg';

    switch (type) {
      case 'PostgreSQL':
        iconName = isConnected ? 'server/postgresql_active.svg' : 'server/postgresql.svg';
        break;
      case 'MySQL':
        iconName = isConnected ? 'server/mysql_active.svg' : 'server/mysql.svg';
        break;
      case 'SQLite':
        iconName = isConnected ? 'server/sqlite_active.svg' : 'server/sqlite.svg';
        break;
      case 'Redis':
        iconName = isConnected ? 'server/redis.svg' : 'server/redis.svg';
        break;
      case 'MongoDB':
        iconName = isConnected ? 'server/mongodb_active.svg' : 'server/mongodb.svg';
        break;
      case 'Elasticsearch':
        iconName = isConnected ? 'server/elasticsearch_active.svg' : 'server/elasticsearch.svg';
        break;
      case 'ClickHouse':
        iconName = isConnected ? 'server/clickhouse_active.svg' : 'server/clickhouse.svg';
        break;
      case 'CouchDB':
      case 'Couchbase':
      case 'Firestore':
        iconName = 'server/database.svg';
        break;
      default:
        iconName = 'server/db2.svg';
        break;
    }

    return IconHelper.getResourcePath(`icon/${iconName}`);
  }

  public static getDatabaseIcon(): vscode.Uri {
    return IconHelper.getResourcePath('icon/database.svg');
  }

  public static getSchemaIcon(): vscode.Uri {
    return IconHelper.getResourcePath('icon/layer-group.svg');
  }

  public static getFolderIcon(): vscode.Uri {
    return IconHelper.getResourcePath('icon/folder.svg');
  }

  public static getQueryIcon(): vscode.Uri {
    return IconHelper.getResourcePath('icon/webview/query.svg');
  }
}

import * as vscode from 'vscode';
import { ConnectionStorageService } from '../storage/ConnectionStorage.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { DriverManager } from '../drivers/DriverManager.js';
import { isRussian, t } from '../util/i18n.js';

export class ConnectWebviewProvider {
  public static show(
    context: vscode.ExtensionContext,
    storageService: ConnectionStorageService,
    onSaved: () => void,
    editingConfig?: ConnectionConfig,
    existingPassword?: string,
    existingSshPassword?: string
  ) {
    const isEdit = !!editingConfig;
    const title = isEdit ? t('Edit Connection', 'Редактировать подключение') : t('Add Connection', 'Добавить подключение');

    const panel = vscode.window.createWebviewPanel(
      'dbClientConnect',
      title,
      vscode.ViewColumn.One,
      {
        enableScripts: true,
        retainContextWhenHidden: true,
      }
    );

    panel.webview.onDidReceiveMessage(async (message) => {
      switch (message.type) {
        case 'test': {
          try {
            const tempConfig: ConnectionConfig = message.data.config;
            const password = message.data.password;
            const sshPassword = message.data.sshPassword;
            const driver = await DriverManager.getInstance().getDriver(tempConfig, password, sshPassword);
            const res = await driver.testConnection();
            panel.webview.postMessage({ type: 'testResult', result: res });
          } catch (err: any) {
            panel.webview.postMessage({
              type: 'testResult',
              result: { success: false, message: err.message || 'Connection test failed' },
            });
          }
          break;
        }
        case 'save': {
          try {
            const config: ConnectionConfig = message.data.config;
            const password = message.data.password;
            const sshPassword = message.data.sshPassword;

            await storageService.saveConnection(config);
            if (password !== undefined) {
              await storageService.savePassword(config.id, password);
            }
            if (sshPassword !== undefined) {
              await storageService.saveSshPassword(config.id, sshPassword);
            }

            vscode.window.showInformationMessage(
              t(`Successfully saved connection "${config.name}"!`, `Подключение "${config.name}" успешно сохранено!`)
            );
            onSaved();
            panel.dispose();
          } catch (err: any) {
            vscode.window.showErrorMessage(`Failed to save connection: ${err.message}`);
          }
          break;
        }
      }
    });

    panel.webview.html = ConnectWebviewProvider.getHtml(editingConfig, existingPassword, existingSshPassword);
  }

  private static getHtml(
    config?: ConnectionConfig,
    password?: string,
    sshPassword?: string
  ): string {
    const ru = isRussian();
    const text = {
      title: config ? (ru ? 'Редактировать Подключение' : 'Edit Database Connection') : (ru ? 'Новое Подключение к Базе Данных' : 'New Database Connection'),
      name: ru ? 'Имя подключения' : 'Connection Name',
      namePh: ru ? 'Мой Проект DB' : 'My Project DB',
      group: ru ? 'Группа / Проект' : 'Group / Folder',
      groupPh: ru ? 'Production, Staging, Local' : 'Production, Staging, Local',
      color: ru ? 'Цветовая метка' : 'Color Badge',
      dbType: ru ? 'Тип СУБД' : 'Database Type',
      host: ru ? 'Хост' : 'Host',
      port: ru ? 'Порт' : 'Port',
      user: ru ? 'Пользователь' : 'User',
      password: ru ? 'Пароль / API Key / Token' : 'Password / API Key / Token',
      database: ru ? 'База данных / Project ID' : 'Database / Project ID',
      dbPath: ru ? 'Путь к файлу базы (.db)' : 'Database File Path (.db)',
      dbPathPh: ru ? '/path/to/database.db' : '/path/to/database.db',
      sshSection: ru ? '🔒 SSH Туннель' : '🔒 SSH Tunnel',
      sshEnable: ru ? 'Использовать SSH туннелирование' : 'Use SSH Tunnel',
