import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { ColumnInfo, PageParams, QueryResult, TableInfo } from '../model/QueryTypes.js';

export interface ForeignKeyInfo {
  constraintName: string;
  columnName: string;
  referencedTable: string;
  referencedColumn: string;
}

export interface RoutineInfo {
  name: string;
  type: 'FUNCTION' | 'PROCEDURE';
  comment?: string;
}

export interface TriggerInfo {
  name: string;
  table: string;
  event?: string;
  timing?: string;
}

export abstract class BaseDriver {
  protected config: ConnectionConfig;
  protected password?: string;
  protected isConnected: boolean = false;

  constructor(config: ConnectionConfig, password?: string) {
    this.config = config;
    this.password = password;
  }

  abstract connect(): Promise<void>;
  abstract disconnect(): Promise<void>;
  abstract testConnection(): Promise<{ success: boolean; message?: string }>;

  abstract getDatabases(): Promise<string[]>;
  abstract getTables(databaseName?: string): Promise<TableInfo[]>;
  abstract getColumns(tableName: string, databaseName?: string, schemaName?: string): Promise<ColumnInfo[]>;
  abstract getForeignKeys(tableName: string, databaseName?: string, schemaName?: string): Promise<ForeignKeyInfo[]>;

  async getSchemas(databaseName?: string): Promise<string[]> {
    return ['public'];
  }

  async getViews(databaseName?: string, schemaName?: string): Promise<TableInfo[]> {
    return [];
  }

  async getFunctions(databaseName?: string, schemaName?: string): Promise<RoutineInfo[]> {
    return [];
  }

  async getProcedures(databaseName?: string, schemaName?: string): Promise<RoutineInfo[]> {
    return [];
  }

  async getTriggers(databaseName?: string, schemaName?: string): Promise<TriggerInfo[]> {
    return [];
  }

  async getScript(name: string, type: 'view' | 'function' | 'procedure' | 'trigger', databaseName?: string, schemaName?: string): Promise<string> {
    return `-- DDL for ${type} ${name}\n-- Not implemented for this driver`;
  }

  abstract executeQuery(sql: string): Promise<QueryResult>;
  abstract getTableData(tableName: string, params: PageParams, schemaName?: string): Promise<QueryResult>;
}

import mysql from 'mysql2/promise';
import { BaseDriver, ForeignKeyInfo, RoutineInfo, TriggerInfo } from './BaseDriver.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { ColumnInfo, PageParams, QueryResult, TableInfo } from '../model/QueryTypes.js';

export class MysqlDriver extends BaseDriver {
  private connection: mysql.Connection | null = null;

  constructor(config: ConnectionConfig, password?: string) {
    super(config, password);
  }

  async connect(): Promise<void> {
    if (!this.isConnected) {
      this.connection = await mysql.createConnection({
        host: this.config.host || 'localhost',
        port: this.config.port || 3306,
        user: this.config.user || 'root',
        password: this.password || '',
        database: this.config.database || undefined,
        multipleStatements: true,
      });
      this.isConnected = true;
    }
  }

  async disconnect(): Promise<void> {
    if (this.connection) {
      await this.connection.end();
      this.connection = null;
      this.isConnected = false;
    }
  }

  async testConnection(): Promise<{ success: boolean; message?: string }> {
    try {
      await this.connect();
      await this.connection!.ping();
      return { success: true, message: 'Successfully connected to MySQL database!' };
    } catch (err: any) {
      return { success: false, message: err.message || 'Connection failed' };
    } finally {
      await this.disconnect();
    }
  }

  async getDatabases(): Promise<string[]> {
    const res = await this.executeQuery('SHOW DATABASES;');
    return res.rows
      .map((r: any) => r.Database || r.database)
      .filter((db: string) => !['information_schema', 'mysql', 'performance_schema', 'sys'].includes(db));
  }

  async getTables(databaseName?: string): Promise<TableInfo[]> {
    const db = databaseName || this.config.database;
    if (db) {
      await this.executeQuery(`USE \`${db}\`;`);
    }
    const res = await this.executeQuery('SHOW FULL TABLES WHERE Table_type = "BASE TABLE";');
    return res.rows.map((r: any) => {
      const keys = Object.keys(r);
      const tableName = r[keys[0]];
      return {
        name: tableName,
        type: 'table',
      };
    });
  }

  async getViews(databaseName?: string): Promise<TableInfo[]> {
    const db = databaseName || this.config.database;
    if (db) {
      await this.executeQuery(`USE \`${db}\`;`);
    }
    const res = await this.executeQuery('SHOW FULL TABLES WHERE Table_type = "VIEW";');
    return res.rows.map((r: any) => {
      const keys = Object.keys(r);
      return {
        name: r[keys[0]],
        type: 'view',
      };
    });
  }

  async getFunctions(databaseName?: string): Promise<RoutineInfo[]> {
    const db = databaseName || this.config.database;
    const res = await this.executeQuery(
      `SELECT ROUTINE_NAME, ROUTINE_COMMENT FROM information_schema.ROUTINES WHERE ROUTINE_SCHEMA = '${db}' AND ROUTINE_TYPE = 'FUNCTION';`
    );
    return res.rows.map((r: any) => ({
      name: r.ROUTINE_NAME || r.routine_name,
      type: 'FUNCTION',
      comment: r.ROUTINE_COMMENT || r.routine_comment,
    }));
  }

  async getProcedures(databaseName?: string): Promise<RoutineInfo[]> {
    const db = databaseName || this.config.database;
    const res = await this.executeQuery(
      `SELECT ROUTINE_NAME, ROUTINE_COMMENT FROM information_schema.ROUTINES WHERE ROUTINE_SCHEMA = '${db}' AND ROUTINE_TYPE = 'PROCEDURE';`
    );
    return res.rows.map((r: any) => ({
      name: r.ROUTINE_NAME || r.routine_name,
      type: 'PROCEDURE',
      comment: r.ROUTINE_COMMENT || r.routine_comment,
    }));
  }

  async getTriggers(databaseName?: string): Promise<TriggerInfo[]> {
    const db = databaseName || this.config.database;
    const res = await this.executeQuery(
      `SELECT TRIGGER_NAME, EVENT_OBJECT_TABLE, ACTION_TIMING, EVENT_MANIPULATION FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA = '${db}';`
    );
    return res.rows.map((r: any) => ({
      name: r.TRIGGER_NAME || r.trigger_name,
      table: r.EVENT_OBJECT_TABLE || r.event_object_table,
      timing: r.ACTION_TIMING || r.action_timing,
      event: r.EVENT_MANIPULATION || r.event_manipulation,
    }));
  }

  async getScript(name: string, type: 'view' | 'function' | 'procedure' | 'trigger', databaseName?: string): Promise<string> {
    const db = databaseName || this.config.database;
    if (db) {
      await this.executeQuery(`USE \`${db}\`;`);
    }

    try {
      if (type === 'view') {
        const res = await this.executeQuery(`SHOW CREATE VIEW \`${name}\`;`);
        return res.rows[0]?.['Create View'] || res.rows[0]?.['create view'] || `-- Create View ${name}`;
      } else if (type === 'procedure') {
        const res = await this.executeQuery(`SHOW CREATE PROCEDURE \`${name}\`;`);
        return res.rows[0]?.['Create Procedure'] || res.rows[0]?.['create procedure'] || `-- Create Procedure ${name}`;
      } else if (type === 'function') {
        const res = await this.executeQuery(`SHOW CREATE FUNCTION \`${name}\`;`);
        return res.rows[0]?.['Create Function'] || res.rows[0]?.['create function'] || `-- Create Function ${name}`;
      } else if (type === 'trigger') {
        const res = await this.executeQuery(`SHOW CREATE TRIGGER \`${name}\`;`);
        return res.rows[0]?.['SQL Original Statement'] || res.rows[0]?.['sql original statement'] || `-- Create Trigger ${name}`;
      }
    } catch (e: any) {
      return `-- Failed to fetch DDL for ${type} ${name}: ${e.message}`;
    }
    return `-- DDL for ${type} ${name}`;
  }

  async getColumns(tableName: string, databaseName?: string): Promise<ColumnInfo[]> {
    const db = databaseName || this.config.database;
    if (db) {
      await this.executeQuery(`USE \`${db}\`;`);
    }
    const res = await this.executeQuery(
      `SELECT COLUMN_NAME, DATA_TYPE, IS_NULLABLE, COLUMN_KEY, COLUMN_DEFAULT, COLUMN_COMMENT, EXTRA FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = '${db}' AND TABLE_NAME = '${tableName}' ORDER BY ORDINAL_POSITION;`
    );

    return res.rows.map((r: any) => {
      const colName = r.COLUMN_NAME ?? r.column_name ?? r.Field ?? r.field;
      const dataType = r.DATA_TYPE ?? r.data_type ?? r.Type ?? r.type ?? 'VARCHAR';
      const isNullable = r.IS_NULLABLE ?? r.is_nullable ?? r.Null ?? r.null;
      const colKey = r.COLUMN_KEY ?? r.column_key ?? r.Key ?? r.key;
      const colDef = r.COLUMN_DEFAULT ?? r.column_default ?? r.Default ?? r.default;
      const colComment = r.COLUMN_COMMENT ?? r.column_comment ?? r.Comment ?? r.comment;

      return {
        name: colName,
        type: String(dataType).toUpperCase(),
        nullable: isNullable === 'YES' || isNullable === true,
        isPrimaryKey: colKey === 'PRI',
        defaultValue: colDef !== null ? String(colDef) : undefined,
        comment: colComment || undefined,
      };
    });
  }

  async getForeignKeys(tableName: string, databaseName?: string): Promise<ForeignKeyInfo[]> {
    const db = databaseName || this.config.database;
    const res = await this.executeQuery(
      `SELECT CONSTRAINT_NAME, COLUMN_NAME, REFERENCED_TABLE_NAME, REFERENCED_COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA = '${db}' AND TABLE_NAME = '${tableName}' AND REFERENCED_TABLE_NAME IS NOT NULL;`
    );

    return res.rows.map((r: any) => ({
      constraintName: r.CONSTRAINT_NAME || r.constraint_name,
      columnName: r.COLUMN_NAME || r.column_name,
      referencedTable: r.REFERENCED_TABLE_NAME || r.referenced_table_name,
      referencedColumn: r.REFERENCED_COLUMN_NAME || r.referenced_column_name,
    }));
  }

  async executeQuery(sql: string): Promise<QueryResult> {
    await this.connect();
    const startTime = Date.now();

    const db = this.config.database;
    if (db) {
      await this.connection!.query(`USE \`${db}\`;`);
    }

    const [results, fields] = await this.connection!.query(sql);
    const costTimeMs = Date.now() - startTime;

    if (Array.isArray(results)) {
      const columnFields: ColumnInfo[] = (fields || []).map((f: any) => ({
        name: f.name,
        type: String(f.type || 'VARCHAR'),
        nullable: true,
      }));

      return {
        rows: results as any[],
        fields: columnFields,
        affectedRows: results.length,
        costTimeMs,
      };
    } else {
      const okPacket = results as mysql.ResultSetHeader;
      return {
        rows: [],
        fields: [],
        affectedRows: okPacket.affectedRows || 0,
        costTimeMs,
      };
    }
  }

  async getTableData(tableName: string, params: PageParams, schemaName?: string): Promise<QueryResult> {
    const offset = (params.page - 1) * params.pageSize;
    const db = this.config.database;
    const tableRef = `\`${tableName}\``;

    let sql = `SELECT * FROM ${tableRef}`;
    let countSql = `SELECT COUNT(*) as total FROM ${tableRef}`;

    if (params.filterSql) {
      sql += ` WHERE ${params.filterSql}`;
      countSql += ` WHERE ${params.filterSql}`;
    }

    sql += ` LIMIT ${params.pageSize} OFFSET ${offset};`;

    if (db) {
      await this.executeQuery(`USE \`${db}\`;`);
    }

    const countRes = await this.executeQuery(countSql);
    const totalCount = parseInt(countRes.rows[0]?.total || '0', 10);

    const queryResult = await this.executeQuery(sql);
    queryResult.totalCount = totalCount;
    return queryResult;
  }
}

import pg from 'pg';
import { BaseDriver, ForeignKeyInfo, RoutineInfo, TriggerInfo } from './BaseDriver.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { ColumnInfo, PageParams, QueryResult, TableInfo } from '../model/QueryTypes.js';

export class PostgresDriver extends BaseDriver {
  private client: pg.Client | null = null;

  constructor(config: ConnectionConfig, password?: string) {
    super(config, password);
  }

  async connect(): Promise<void> {
    if (!this.isConnected) {
      this.client = new pg.Client({
        host: this.config.host || 'localhost',
        port: this.config.port || 5432,
        user: this.config.user || 'postgres',
        password: this.password || '',
        database: this.config.database || 'postgres',
        ssl: this.config.ssl ? { rejectUnauthorized: false } : undefined,
      });
      await this.client.connect();
      this.isConnected = true;
    }
  }

  async disconnect(): Promise<void> {
    if (this.client) {
      await this.client.end();
      this.client = null;
      this.isConnected = false;
    }
  }

  async testConnection(): Promise<{ success: boolean; message?: string }> {
    try {
      await this.connect();
      await this.client!.query('SELECT 1;');
      return { success: true, message: 'Successfully connected to PostgreSQL database!' };
    } catch (err: any) {
      return { success: false, message: err.message || 'Connection failed' };
    } finally {
      await this.disconnect();
    }
  }

  async getDatabases(): Promise<string[]> {
    const res = await this.executeQuery("SELECT datname FROM pg_database WHERE datistemplate = false AND datname != 'postgres';");
    return ['postgres', ...res.rows.map((r: any) => r.datname)];
  }

  async getSchemas(databaseName?: string): Promise<string[]> {
    const res = await this.executeQuery("SELECT schema_name FROM information_schema.schemata WHERE schema_name NOT IN ('pg_catalog', 'information_schema');");
    return res.rows.map((r: any) => r.schema_name);
  }

  async getTables(databaseName?: string, schemaName: string = 'public'): Promise<TableInfo[]> {
    const res = await this.executeQuery(
      `SELECT table_name FROM information_schema.tables WHERE table_schema = '${schemaName}' AND table_type = 'BASE TABLE';`
    );
    return res.rows.map((r: any) => ({
      name: r.table_name,
      type: 'table',
      schema: schemaName,
    }));
  }

  async getViews(databaseName?: string, schemaName: string = 'public'): Promise<TableInfo[]> {
    const res = await this.executeQuery(
      `SELECT table_name FROM information_schema.views WHERE table_schema = '${schemaName}';`
    );
    return res.rows.map((r: any) => ({
      name: r.table_name,
      type: 'view',
      schema: schemaName,
    }));
  }

  async getFunctions(databaseName?: string, schemaName: string = 'public'): Promise<RoutineInfo[]> {
    const res = await this.executeQuery(
      `SELECT routine_name FROM information_schema.routines WHERE routine_schema = '${schemaName}' AND routine_type = 'FUNCTION';`
    );
    return res.rows.map((r: any) => ({
      name: r.routine_name,
      type: 'FUNCTION',
    }));
  }

  async getProcedures(databaseName?: string, schemaName: string = 'public'): Promise<RoutineInfo[]> {
    const res = await this.executeQuery(
      `SELECT routine_name FROM information_schema.routines WHERE routine_schema = '${schemaName}' AND routine_type = 'PROCEDURE';`
    );
    return res.rows.map((r: any) => ({
      name: r.routine_name,
      type: 'PROCEDURE',
    }));
  }

  async getTriggers(databaseName?: string, schemaName: string = 'public'): Promise<TriggerInfo[]> {
    const res = await this.executeQuery(
      `SELECT trigger_name, event_object_table, action_timing, event_manipulation FROM information_schema.triggers WHERE trigger_schema = '${schemaName}';`
    );
    return res.rows.map((r: any) => ({
      name: r.trigger_name,
      table: r.event_object_table,
      timing: r.action_timing,
      event: r.event_manipulation,
    }));
  }

  async getScript(name: string, type: 'view' | 'function' | 'procedure' | 'trigger', databaseName?: string, schemaName: string = 'public'): Promise<string> {
    try {
      if (type === 'view') {
        const res = await this.executeQuery(`SELECT pg_get_viewdef('"${schemaName}"."${name}"', true) as def;`);
        return `CREATE OR REPLACE VIEW "${schemaName}"."${name}" AS\n` + (res.rows[0]?.def || '');
      } else if (type === 'function' || type === 'procedure') {
        const res = await this.executeQuery(`SELECT pg_get_functiondef(oid) as def FROM pg_proc WHERE proname = '${name}';`);
        return res.rows[0]?.def || `-- DDL for ${name}`;
      }
    } catch (e: any) {
      return `-- Failed to fetch DDL for ${type} ${name}: ${e.message}`;
    }
    return `-- DDL for ${type} ${name}`;
  }

  async getColumns(tableName: string, databaseName?: string, schemaName: string = 'public'): Promise<ColumnInfo[]> {
    const res = await this.executeQuery(
      `SELECT c.column_name, c.data_type, c.is_nullable, c.column_default, pgd.description as comment
       FROM information_schema.columns c
       LEFT JOIN pg_catalog.pg_statio_all_tables st ON st.schemaname = c.table_schema AND st.relname = c.table_name
       LEFT JOIN pg_catalog.pg_description pgd ON pgd.objoid = st.relid AND pgd.objsubid = c.ordinal_position
       WHERE c.table_schema = '${schemaName}' AND c.table_name = '${tableName}'
       ORDER BY c.ordinal_position;`
    );

    const pkRes = await this.executeQuery(
      `SELECT kcu.column_name FROM information_schema.table_constraints tc JOIN information_schema.key_column_usage kcu ON tc.constraint_name = kcu.constraint_name AND tc.table_schema = kcu.table_schema WHERE tc.constraint_type = 'PRIMARY KEY' AND tc.table_schema = '${schemaName}' AND tc.table_name = '${tableName}';`
    );

    const primaryKeys = new Set(pkRes.rows.map((r: any) => r.column_name));

    return res.rows.map((r: any) => ({
      name: r.column_name,
      type: String(r.data_type).toUpperCase(),
      nullable: r.is_nullable === 'YES',
      isPrimaryKey: primaryKeys.has(r.column_name),
      defaultValue: r.column_default || undefined,
      comment: r.comment || undefined,
    }));
  }

  async getForeignKeys(tableName: string, databaseName?: string, schemaName: string = 'public'): Promise<ForeignKeyInfo[]> {
    const res = await this.executeQuery(
      `SELECT tc.constraint_name, kcu.column_name, ccu.table_name AS referenced_table_name, ccu.column_name AS referenced_column_name FROM information_schema.table_constraints AS tc JOIN information_schema.key_column_usage AS kcu ON tc.constraint_name = kcu.constraint_name AND tc.table_schema = kcu.table_schema JOIN information_schema.constraint_column_usage AS ccu ON ccu.constraint_name = tc.constraint_name AND ccu.table_schema = tc.table_schema WHERE tc.constraint_type = 'FOREIGN KEY' AND tc.table_schema = '${schemaName}' AND tc.table_name = '${tableName}';`
    );

    return res.rows.map((r: any) => ({
      constraintName: r.constraint_name,
      columnName: r.column_name,
      referencedTable: r.referenced_table_name,
      referencedColumn: r.referenced_column_name,
    }));
  }

  async executeQuery(sql: string): Promise<QueryResult> {
    await this.connect();
    const startTime = Date.now();
    const result = await this.client!.query(sql);
    const costTimeMs = Date.now() - startTime;

    const columnFields: ColumnInfo[] = (result.fields || []).map((f: any) => ({
      name: f.name,
      type: String(f.dataTypeID),
      nullable: true,
    }));

    return {
      rows: result.rows || [],
      fields: columnFields,
      affectedRows: result.rowCount || 0,
      costTimeMs,
    };
  }

  async getTableData(tableName: string, params: PageParams, schemaName: string = 'public'): Promise<QueryResult> {
    const offset = (params.page - 1) * params.pageSize;
    const tableRef = `"${schemaName}"."${tableName}"`;

    let sql = `SELECT * FROM ${tableRef}`;
    let countSql = `SELECT COUNT(*) as total FROM ${tableRef}`;

    if (params.filterSql) {
      sql += ` WHERE ${params.filterSql}`;
      countSql += ` WHERE ${params.filterSql}`;
    }

    sql += ` LIMIT ${params.pageSize} OFFSET ${offset};`;

    const countRes = await this.executeQuery(countSql);
    const totalCount = parseInt(countRes.rows[0]?.total || '0', 10);

    const queryResult = await this.executeQuery(sql);
    queryResult.totalCount = totalCount;
    return queryResult;
  }
}

