import { BaseDriver } from './BaseDriver.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { ColumnInfo, PageParams, QueryResult, TableInfo } from '../model/QueryTypes.js';

export class SqliteDriver extends BaseDriver {
  private db: any = null;

  constructor(config: ConnectionConfig, password?: string) {
    super(config, password);
  }

  async connect(): Promise<void> {
    if (this.db) {
      await this.disconnect();
    }

    let sqlite3: any;
    try {
      sqlite3 = require('sqlite3');
    } catch (e) {
      throw new Error('sqlite3 native module is not available in this environment.');
    }

    const dbPath = this.config.dbPath || this.config.database || ':memory:';
    return new Promise((resolve, reject) => {
      this.db = new sqlite3.Database(dbPath, (err: any) => {
        if (err) {
          reject(err);
        } else {
          this.isConnected = true;
          resolve();
        }
      });
    });
  }

  async disconnect(): Promise<void> {
    if (this.db) {
      return new Promise((resolve, reject) => {
        this.db.close((err: any) => {
          this.db = null;
          this.isConnected = false;
          if (err) reject(err);
          else resolve();
        });
      });
    }
  }

  async testConnection(): Promise<{ success: boolean; message?: string }> {
    try {
      await this.connect();
      return { success: true, message: 'Successfully connected to SQLite database!' };
    } catch (err: any) {
      return { success: false, message: err.message || 'Connection failed' };
    } finally {
      await this.disconnect();
    }
  }

  async getDatabases(): Promise<string[]> {
    return ['main'];
  }

  async getTables(databaseName?: string): Promise<TableInfo[]> {
    const res = await this.executeQuery("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%';");
    return res.rows.map((r: any) => ({
      name: r.name,
      type: 'table',
    }));
  }

  async getViews(databaseName?: string): Promise<TableInfo[]> {
    const res = await this.executeQuery("SELECT name FROM sqlite_master WHERE type='view';");
    return res.rows.map((r: any) => ({
      name: r.name,
      type: 'view',
    }));
  }

  async getColumns(tableName: string): Promise<ColumnInfo[]> {
    const res = await this.executeQuery(`PRAGMA table_info("${tableName}");`);
    return res.rows.map((r: any) => ({
      name: r.name,
      type: String(r.type || 'TEXT').toUpperCase(),
      nullable: r.notnull === 0,
      isPrimaryKey: r.pk === 1,
      defaultValue: r.dflt_value !== null ? String(r.dflt_value) : undefined,
    }));
  }

  async getForeignKeys(tableName: string): Promise<any[]> {
    return [];
  }

  async executeQuery(sql: string): Promise<QueryResult> {
    await this.connect();
    const startTime = Date.now();

    return new Promise((resolve, reject) => {
      const trimmed = sql.trim().toUpperCase();
      if (trimmed.startsWith('SELECT') || trimmed.startsWith('PRAGMA') || trimmed.startsWith('EXPLAIN')) {
        this.db.all(sql, [], (err: any, rows: any[]) => {
          const costTimeMs = Date.now() - startTime;
          if (err) return reject(err);

          const sampleRow = rows && rows[0] ? rows[0] : {};
          const fields: ColumnInfo[] = Object.keys(sampleRow).map((k) => ({
            name: k,
            type: 'TEXT',
            nullable: true,
          }));

          resolve({
            rows: rows || [],
            fields,
            affectedRows: rows ? rows.length : 0,
            costTimeMs,
          });
        });
      } else {
        this.db.run(sql, [], function (this: any, err: any) {
          const costTimeMs = Date.now() - startTime;
          if (err) return reject(err);

          resolve({
            rows: [],
            fields: [],
            affectedRows: this.changes || 0,
            costTimeMs,
          });
        });
      }
    });
  }

  async getTableData(tableName: string, params: PageParams, schemaName?: string): Promise<QueryResult> {
    const offset = (params.page - 1) * params.pageSize;
    let sql = `SELECT * FROM "${tableName}"`;
    let countSql = `SELECT COUNT(*) as total FROM "${tableName}"`;

    if (params.filterSql) {
      sql += ` WHERE ${params.filterSql}`;
      countSql += ` WHERE ${params.filterSql}`;
    }

    sql += ` LIMIT ${params.pageSize} OFFSET ${offset};`;

    const countRes = await this.executeQuery(countSql);
    const totalCount = parseInt(countRes.rows[0]?.total || '0', 10);

    const queryResult = await this.executeQuery(sql);
    queryResult.totalCount = totalCount;
    return queryResult;
  }
}

import { BaseDriver, ForeignKeyInfo } from './BaseDriver.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { ColumnInfo, PageParams, QueryResult, TableInfo } from '../model/QueryTypes.js';

export class MongoDriver extends BaseDriver {
  private client: any = null;

  constructor(config: ConnectionConfig, password?: string) {
    super(config, password);
  }

  async connect(): Promise<void> {
    if (!this.isConnected) {
      let mongodb: any;
      try {
        mongodb = require('mongodb');
      } catch (e) {
        throw new Error('mongodb driver module is not available in this environment.');
      }

      const host = this.config.host || 'localhost';
      const port = this.config.port || 27017;
      const user = this.config.user ? `${this.config.user}:${this.password || ''}@` : '';
      const uri = `mongodb://${user}${host}:${port}`;

      this.client = new mongodb.MongoClient(uri);
      await this.client.connect();
      this.isConnected = true;
    }
  }

  async disconnect(): Promise<void> {
    if (this.client) {
      await this.client.close();
      this.client = null;
      this.isConnected = false;
    }
  }

  async testConnection(): Promise<{ success: boolean; message?: string }> {
    try {
      await this.connect();
      await this.client.db().admin().ping();
      return { success: true, message: 'Successfully connected to MongoDB server!' };
    } catch (err: any) {
      return { success: false, message: err.message || 'Connection failed' };
    } finally {
      await this.disconnect();
    }
  }

  async getDatabases(): Promise<string[]> {
    await this.connect();
    const adminDb = this.client.db().admin();
    const res = await adminDb.listDatabases();
    return res.databases.map((db: any) => db.name).filter((name: string) => !['admin', 'local', 'config'].includes(name));
  }

  async getTables(databaseName?: string): Promise<TableInfo[]> {
    await this.connect();
    const dbName = databaseName || this.config.database || 'test';
    const db = this.client.db(dbName);
    const collections = await db.listCollections().toArray();
    return collections.map((col: any) => ({
      name: col.name,
      type: 'collection',
    }));
  }

  async getColumns(tableName: string, databaseName?: string): Promise<ColumnInfo[]> {
    await this.connect();
    const dbName = databaseName || this.config.database || 'test';
    const db = this.client.db(dbName);
    const sample = await db.collection(tableName).findOne();

    if (!sample) {
      return [{ name: '_id', type: 'ObjectId', isPrimaryKey: true, nullable: false }];
    }

    return Object.keys(sample).map((key) => ({
      name: key,
      type: typeof sample[key] === 'object' ? 'Object/JSON' : typeof sample[key],
      isPrimaryKey: key === '_id',
      nullable: true,
    }));
  }

  async getForeignKeys(tableName: string, databaseName?: string): Promise<ForeignKeyInfo[]> {
    return [];
  }

  async executeQuery(sql: string): Promise<QueryResult> {
    const startTime = Date.now();
    await this.connect();
    const dbName = this.config.database || 'test';
    const db = this.client.db(dbName);

    try {
      const collections = await db.listCollections().toArray();
      const colName = collections[0]?.name || 'test';
      const docs = await db.collection(colName).find().limit(50).toArray();
      const costTimeMs = Date.now() - startTime;

      const sample = docs[0] || {};
      const fields: ColumnInfo[] = Object.keys(sample).map((k) => ({
        name: k,
        type: typeof sample[k],
        nullable: true,
      }));

      return {
        rows: docs,
        fields,
        affectedRows: docs.length,
        costTimeMs,
      };
    } catch (e: any) {
      return {
        rows: [],
        fields: [],
        affectedRows: 0,
        costTimeMs: Date.now() - startTime,
      };
    }
  }

  async getTableData(tableName: string, params: PageParams, schemaName?: string): Promise<QueryResult> {
    const startTime = Date.now();
    await this.connect();
    const dbName = this.config.database || 'test';
    const db = this.client.db(dbName);
    const skip = (params.page - 1) * params.pageSize;

    const totalCount = await db.collection(tableName).countDocuments();
    const docs = await db.collection(tableName).find().skip(skip).limit(params.pageSize).toArray();
    const costTimeMs = Date.now() - startTime;

    const sample = docs[0] || {};
    const fields: ColumnInfo[] = Object.keys(sample).map((k) => ({
      name: k,
      type: typeof sample[k],
      nullable: true,
    }));

    return {
      rows: docs,
      fields,
      totalCount,
      affectedRows: docs.length,
      costTimeMs,
    };
  }
}

import * as net from 'net';
import * as fs from 'fs';
import { ConnectionConfig } from '../model/ConnectionConfig.js';

export interface SshTunnelResult {
  server: net.Server;
  localPort: number;
}

export class SshTunnelManager {
  public static async createTunnel(config: ConnectionConfig, sshPassword?: string): Promise<SshTunnelResult> {
    let ssh2: any;
    try {
      ssh2 = require('ssh2');
    } catch (e) {
      throw new Error('ssh2 module is not available in this environment.');
    }

    if (!config.ssh || !config.ssh.enabled) {
      throw new Error('SSH is not enabled for this connection');
    }

    const sshHost = config.ssh.host;
    const sshPort = config.ssh.port || 22;
    const sshUser = config.ssh.username;

    if (!sshHost || !sshUser) {
      throw new Error('SSH Host and Username are required');
    }

    return new Promise((resolve, reject) => {
      const sshClient = new ssh2.Client();

      const server = net.createServer((localSocket) => {
        sshClient.forwardOut(
          '127.0.0.1',
          localSocket.remotePort || 0,
          config.host || 'localhost',
          config.port || 3306,
          (err, stream) => {
            if (err) {
              localSocket.destroy();
              return;
            }
            localSocket.pipe(stream).pipe(localSocket);
          }
        );
      });

      server.listen(0, '127.0.0.1', () => {
        const address = server.address() as net.AddressInfo;
        const localPort = address.port;

        const connectConfig: any = {
          host: sshHost,
          port: sshPort,
          username: sshUser,
        };

        if (config.ssh?.usePrivateKey && config.ssh?.privateKeyPath) {
          try {
            connectConfig.privateKey = fs.readFileSync(config.ssh.privateKeyPath);
          } catch (e: any) {
            server.close();
            return reject(new Error(`Failed to read private key file: ${e.message}`));
          }
        } else if (sshPassword) {
          connectConfig.password = sshPassword;
        }

        sshClient
          .on('ready', () => {
            resolve({ server, localPort });
          })
          .on('error', (err) => {
            server.close();
            reject(new Error(`SSH Tunnel connection error: ${err.message}`));
          })
          .connect(connectConfig);
      });

      server.on('error', (err) => {
        reject(err);
      });
    });
  }

  public static async closeTunnel(result: SshTunnelResult): Promise<void> {
    return new Promise((resolve) => {
      result.server.close(() => resolve());
    });
  }
}

import * as vscode from 'vscode';
import { ConnectionStorageService } from './storage/ConnectionStorage.js';
import { DatabaseTreeProvider } from './tree/DatabaseTreeProvider.js';
import { ConnectionNode } from './tree/ConnectionNode.js';
import { DatabaseNode } from './tree/DatabaseNode.js';
import { TableNode } from './tree/TableNode.js';
import { ConnectWebviewProvider } from './webview/ConnectWebviewProvider.js';
import { TableWebviewProvider } from './webview/TableWebviewProvider.js';
import { TableDesignWebviewProvider } from './webview/TableDesignWebviewProvider.js';
import { ErdWebviewProvider } from './webview/ErdWebviewProvider.js';
import { ProcessListWebviewProvider } from './webview/ProcessListWebviewProvider.js';
import { DatabaseDumpService } from './dump/DatabaseDumpService.js';
import { MockDataGenerator } from './mock/MockDataGenerator.js';
import { DriverManager } from './drivers/DriverManager.js';
import { ScriptNode } from './tree/ScriptNode.js';
import { IconHelper } from './util/IconHelper.js';
import { t } from './util/i18n.js';

export function activate(context: vscode.ExtensionContext) {
  IconHelper.setExtensionPath(context.extensionPath);

  const storageService = new ConnectionStorageService(context);
  const treeProvider = new DatabaseTreeProvider(storageService);

  // Register all tree view IDs to prevent any extension ID conflict
  vscode.window.registerTreeDataProvider('database-client-explorer', treeProvider);
  vscode.window.registerTreeDataProvider('dbClientView', treeProvider);
  vscode.window.registerTreeDataProvider('anarchy-database-client-explorer', treeProvider);

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.addConnection', () => {
      ConnectWebviewProvider.show(context, storageService, () => {
        treeProvider.refresh();
      });
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.editConnection', async (node: ConnectionNode) => {
      if (node && node.config) {
        const password = await storageService.getPassword(node.config.id);
        const sshPassword = await storageService.getSshPassword(node.config.id);
        ConnectWebviewProvider.show(
          context,
          storageService,
          () => {
            treeProvider.refresh();
          },
          node.config,
          password,
          sshPassword
        );
      }
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.deleteConnection', async (node: ConnectionNode) => {
      if (node && node.config) {
        const confirmText = t(`Are you sure you want to delete connection "${node.config.name}"?`, `Вы уверены, что хотите удалить подключение "${node.config.name}"?`);
        const result = await vscode.window.showWarningMessage(confirmText, { modal: true }, t('Delete', 'Удалить'));
        if (result === t('Delete', 'Удалить')) {
          await storageService.deleteConnection(node.config.id);
          await DriverManager.getInstance().removeDriver(node.config.id);
          treeProvider.refresh();
          vscode.window.showInformationMessage(t(`Deleted "${node.config.name}"`, `Удалено "${node.config.name}"`));
        }
      }
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.refresh', () => {
      treeProvider.refresh();
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.openTable', (node: TableNode) => {
      if (node && node instanceof TableNode) {
        TableWebviewProvider.openTable(node);
      }
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.designTable', (node: TableNode) => {
      if (node && node instanceof TableNode) {
        TableDesignWebviewProvider.show(node);
      }
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.openScript', async (node: ScriptNode) => {
      if (node && node instanceof ScriptNode) {
        try {
          const driver = await DriverManager.getInstance().getDriver(node.connectionConfig, node.password, node.sshPassword);
          const scriptSql = await driver.getScript(node.objectName, node.objectType, node.connectionConfig.database, node.schemaName);
          const doc = await vscode.workspace.openTextDocument({ language: 'sql', content: scriptSql });
          await vscode.window.showTextDocument(doc);
        } catch (e: any) {
          vscode.window.showErrorMessage(`Failed to open DDL script: ${e.message}`);
        }
      }
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.queryConsole', async (node: ConnectionNode | DatabaseNode) => {
      if (node) {
        const config = node.connectionConfig || (node as ConnectionNode).config;
        const pass = (node as ConnectionNode).password;
        const sshPass = (node as ConnectionNode).sshPassword;
        TableWebviewProvider.openQueryConsole(config, pass, sshPass);
      }
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.dumpDatabase', async (node: ConnectionNode | DatabaseNode) => {
      if (node) {
        const config = node.connectionConfig || (node as ConnectionNode).config;
        const pass = (node as ConnectionNode).password;
        const sshPass = (node as ConnectionNode).sshPassword;
        await DatabaseDumpService.dumpDatabase(config, pass, sshPass);
      }
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.importSql', async (node: ConnectionNode | DatabaseNode) => {
      if (node) {
        const config = node.connectionConfig || (node as ConnectionNode).config;
        const pass = (node as ConnectionNode).password;
        const sshPass = (node as ConnectionNode).sshPassword;
        await DatabaseDumpService.importSqlFile(config, pass, sshPass);
      }
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.openErd', async (node: DatabaseNode) => {
      if (node) {
        await ErdWebviewProvider.show(node.connectionConfig, node.password, node.sshPassword);
      }
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.processList', async (node: ConnectionNode) => {
      if (node) {
        await ProcessListWebviewProvider.show(node.config, node.password, node.sshPassword);
      }
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.generateMockData', async (node: TableNode) => {
      if (node && node instanceof TableNode) {
        await MockDataGenerator.generateForTable(node);
      }
    })
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('dbClient.newQuery', async (node?: ConnectionNode | DatabaseNode) => {
      if (node) {
        const config = node.connectionConfig || (node as ConnectionNode).config;
        const pass = (node as ConnectionNode).password;
        TableWebviewProvider.openQueryConsole(config, pass);
      } else {
