    const costTimeMs = Date.now() - startTime;

    if (Array.isArray(results)) {
      const columnFields: ColumnInfo[] = (fields || []).map((f: any) => ({
        name: f.name,
        type: String(f.type || 'VARCHAR'),
        nullable: true,
      }));

      return {
