import * as vscode from 'vscode';
import * as path from 'path';
import * as fs from 'fs';

export interface QueryFileItem {
  name: string;
  filePath: string;
}

export class QueryFileStorage {
  private static getStorageDir(context: vscode.ExtensionContext, connectionId: string, dbName?: string): string {
    const base = context.globalStorageUri.fsPath;
    const dbSub = dbName || 'default';
    const dir = path.join(base, 'queries', connectionId, dbSub);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    return dir;
  }

  public static getBoundFolder(context: vscode.ExtensionContext, connectionId: string, dbName?: string): string | undefined {
    const key = `queryFolder_${connectionId}_${dbName || 'default'}`;
    return context.globalState.get<string>(key);
  }

  public static async setBoundFolder(context: vscode.ExtensionContext, connectionId: string, folderPath: string, dbName?: string): Promise<void> {
    const key = `queryFolder_${connectionId}_${dbName || 'default'}`;
    await context.globalState.update(key, folderPath);
  }

  public static getQueryFiles(context: vscode.ExtensionContext, connectionId: string, dbName?: string): QueryFileItem[] {
    const boundFolder = QueryFileStorage.getBoundFolder(context, connectionId, dbName);
    const targetDir = (boundFolder && fs.existsSync(boundFolder))
      ? boundFolder
      : QueryFileStorage.getStorageDir(context, connectionId, dbName);

    if (!fs.existsSync(targetDir)) return [];

    try {
      const files = fs.readdirSync(targetDir);
      return files
        .filter((f) => f.endsWith('.sql'))
        .map((f) => ({
          name: f,
          filePath: path.join(targetDir, f),
        }));
    } catch (e) {
      return [];
    }
  }

  public static async createQueryFile(context: vscode.ExtensionContext, connectionId: string, fileName: string, dbName?: string): Promise<string> {
    const safeName = fileName.endsWith('.sql') ? fileName : `${fileName}.sql`;
    const boundFolder = QueryFileStorage.getBoundFolder(context, connectionId, dbName);
    const targetDir = (boundFolder && fs.existsSync(boundFolder))
      ? boundFolder
      : QueryFileStorage.getStorageDir(context, connectionId, dbName);

    const fullPath = path.join(targetDir, safeName);
    if (!fs.existsSync(fullPath)) {
      const initialComment = `-- Saved Query: ${safeName}\n-- Database: ${dbName || 'default'}\n\nSELECT 1;\n`;
      fs.writeFileSync(fullPath, initialComment, 'utf8');
    }
    return fullPath;
  }

  public static deleteQueryFile(filePath: string): void {
    if (fs.existsSync(filePath)) {
      fs.unlinkSync(filePath);
    }
  }

  public static renameQueryFile(oldPath: string, newName: string): string {
    const dir = path.dirname(oldPath);
    const safeName = newName.endsWith('.sql') ? newName : `${newName}.sql`;
    const newPath = path.join(dir, safeName);
    if (fs.existsSync(oldPath)) {
      fs.renameSync(oldPath, newPath);
    }
    return newPath;
  }
}

import * as vscode from 'vscode';
import { BaseNode } from './BaseNode.js';

export class QueryFileNode extends BaseNode {
  public filePath: string;
  public fileName: string;

  constructor(fileName: string, filePath: string, parent?: BaseNode) {
    super(`queryFile_${filePath}`, fileName, 'queryFileNode', vscode.TreeItemCollapsibleState.None, parent);
    this.fileName = fileName;
    this.filePath = filePath;
  }

  getTreeItem(): vscode.TreeItem {
    const item = new vscode.TreeItem(this.label, vscode.TreeItemCollapsibleState.None);
    item.iconPath = new vscode.ThemeIcon('file-code');
    item.contextValue = 'queryFileNode';
    item.command = {
      command: 'vscode.open',
      title: 'Open Query File',
      arguments: [vscode.Uri.file(this.filePath)],
    };
    return item;
  }

  async getChildren(): Promise<BaseNode[]> {
    return [];
  }
}

import * as vscode from 'vscode';
import { BaseNode } from './BaseNode.js';
import { QueryFileNode } from './QueryFileNode.js';
import { QueryFileStorage } from '../storage/QueryFileStorage.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { isRussian } from '../util/i18n.js';

class EmptyQueryPlaceholderNode extends BaseNode {
  constructor(parent?: BaseNode) {
    const label = isRussian() ? 'Нет сохраненных SQL файлов.' : 'No query files found.';
    super('empty_query_placeholder', label, 'emptyQueryNode', vscode.TreeItemCollapsibleState.None, parent);
  }

  getTreeItem(): vscode.TreeItem {
    const item = new vscode.TreeItem(this.label, vscode.TreeItemCollapsibleState.None);
    item.iconPath = new vscode.ThemeIcon('info');
    item.contextValue = 'emptyQueryNode';
    return item;
  }

  async getChildren(): Promise<BaseNode[]> {
    return [];
  }
}

export class QueryGroupNode extends BaseNode {
  public connectionConfig: ConnectionConfig;
  public dbName?: string;
  private context: vscode.ExtensionContext;

  constructor(context: vscode.ExtensionContext, connectionConfig: ConnectionConfig, dbName?: string, parent?: BaseNode) {
    const label = 'Query';
    super(`queryGroup_${connectionConfig.id}_${dbName || 'default'}`, label, 'queryGroupNode', vscode.TreeItemCollapsibleState.Collapsed, parent);
    this.context = context;
    this.connectionConfig = connectionConfig;
    this.dbName = dbName;
  }

  getTreeItem(): vscode.TreeItem {
    const item = new vscode.TreeItem(this.label, vscode.TreeItemCollapsibleState.Collapsed);
    item.iconPath = new vscode.ThemeIcon('database');
    item.contextValue = 'queryGroupNode';
    return item;
  }

  async getChildren(): Promise<BaseNode[]> {
    const files = QueryFileStorage.getQueryFiles(this.context, this.connectionConfig.id, this.dbName);
    if (files.length === 0) {
      return [new EmptyQueryPlaceholderNode(this)];
    }
    return files.map((f) => new QueryFileNode(f.name, f.filePath, this));
  }
}

import * as vscode from 'vscode';
import { BaseNode } from './BaseNode.js';
import { QueryGroupNode } from './QueryGroupNode.js';
import { TableGroupNode } from './TableGroupNode.js';
import { ViewGroupNode } from './ViewGroupNode.js';
import { FunctionGroupNode } from './FunctionGroupNode.js';
import { ProcedureGroupNode } from './ProcedureGroupNode.js';
import { TriggerGroupNode } from './TriggerGroupNode.js';
import { SchemaNode } from './SchemaNode.js';
import { ConnectionConfig } from '../model/ConnectionConfig.js';
import { DriverManager } from '../drivers/DriverManager.js';
import { IconHelper } from '../util/IconHelper.js';

export class DatabaseNode extends BaseNode {
  public dbName: string;
  public connectionConfig: ConnectionConfig;
  public password?: string;
  public sshPassword?: string;
  public context: vscode.ExtensionContext;

  constructor(dbName: string, connectionConfig: ConnectionConfig, context: vscode.ExtensionContext, password?: string, sshPassword?: string, parent?: BaseNode) {
    super(`db_${connectionConfig.id}_${dbName}`, dbName, 'databaseNode', vscode.TreeItemCollapsibleState.Collapsed, parent);
    this.dbName = dbName;
    this.connectionConfig = { ...connectionConfig, database: dbName };
    this.context = context;
    this.password = password;
    this.sshPassword = sshPassword;
  }

  getTreeItem(): vscode.TreeItem {
    const item = new vscode.TreeItem(this.label, vscode.TreeItemCollapsibleState.Collapsed);
    item.iconPath = IconHelper.getDatabaseIcon();
    item.contextValue = 'databaseNode';
    return item;
  }

  async getChildren(): Promise<BaseNode[]> {
    const dbType = this.connectionConfig.type;
    const queryGroup = new QueryGroupNode(this.context, this.connectionConfig, this.dbName, this);

    try {
      if (dbType === 'PostgreSQL') {
        const driver = await DriverManager.getInstance().getDriver(this.connectionConfig, this.password, this.sshPassword);
        const schemas = await driver.getSchemas(this.dbName);

        if (schemas.length > 1) {
          return [queryGroup, ...schemas.map((s) => new SchemaNode(s, this.connectionConfig, this.context, this.password, this.sshPassword, this))];
        }
      }
    } catch (e: any) {
      vscode.window.showErrorMessage(`Failed to load schemas for database ${this.dbName}: ${e.message}`);
    }

    const schema = this.connectionConfig.schema || 'public';

    if (dbType === 'MongoDB' || dbType === 'CouchDB' || dbType === 'Couchbase' || dbType === 'Firestore') {
      return [
        queryGroup,
        new TableGroupNode(this.connectionConfig, this.password, this.sshPassword, schema, this),
      ];
    }

    if (dbType === 'Elasticsearch') {
      return [
        queryGroup,
        new TableGroupNode(this.connectionConfig, this.password, this.sshPassword, schema, this),
        new ViewGroupNode(this.connectionConfig, this.password, this.sshPassword, schema, this),
      ];
    }

    if (dbType === 'SQLite') {
      return [
        queryGroup,
        new TableGroupNode(this.connectionConfig, this.password, this.sshPassword, schema, this),
        new ViewGroupNode(this.connectionConfig, this.password, this.sshPassword, schema, this),
        new TriggerGroupNode(this.connectionConfig, this.password, this.sshPassword, schema, this),
      ];
    }

    if (dbType === 'ClickHouse') {
      return [
        queryGroup,
        new TableGroupNode(this.connectionConfig, this.password, this.sshPassword, schema, this),
        new ViewGroupNode(this.connectionConfig, this.password, this.sshPassword, schema, this),
        new FunctionGroupNode(this.connectionConfig, this.password, this.sshPassword, schema, this),
      ];
    }

    return [
      queryGroup,
      new TableGroupNode(this.connectionConfig, this.password, this.sshPassword, schema, this),
      new ViewGroupNode(this.connectionConfig, this.password, this.sshPassword, schema, this),
      new FunctionGroupNode(this.connectionConfig, this.password, this.sshPassword, schema, this),
      new ProcedureGroupNode(this.connectionConfig, this.password, this.sshPassword, schema, this),
      new TriggerGroupNode(this.connectionConfig, this.password, this.sshPassword, schema, this),
    ];
  }
}

